window.__LIZZWORD_DEEP_SHARD && window.__LIZZWORD_DEEP_SHARD("0108", [{"word":"solar eclipse","ipa_uk":"/ˌsəʊlər ɪˈklɪps/","ipa_us":"/ˌsoʊlər ɪˈklɪps/","definition_zh":"日食；日蚀（月球运行到太阳与地球之间、遮住日面）","definition_en":"the event in which the moon passes between the earth and the sun and hides the sun's light","core_image":"正午的天空里，一枚黑圆盘从太阳边缘慢慢咬进去，地面像被调暗了灯","scene":"正午站在操场上，天色忽然暗下来，你说 A solar eclipse turned noon into dusk.","sceneCN":"这里 solar eclipse 指「月球挡住太阳、日面被遮的天象」（第 1 个义项：月球运行到太阳与地球之间、遮住日光的整体事件）；句意为一次日食把正午变成了黄昏。图中可辨识物件：黑圆盘、被咬掉一角的日面、忽然亮起的路灯、操场看台。","pos":[{"tag":"n.","zh":"日食；日蚀（可数，指一次具体天象；亦作定语，如 solar eclipse glasses）"}],"collocations":[{"phrase":"total solar eclipse","zh":"日全食"},{"phrase":"partial solar eclipse","zh":"日偏食"},{"phrase":"annular solar eclipse","zh":"日环食"},{"phrase":"observe a solar eclipse","zh":"观测日食"},{"phrase":"the path of a solar eclipse","zh":"日食带（月影扫过的路径）"},{"phrase":"solar eclipse glasses","zh":"日食观测镜"}],"forms":[{"label":"复数（指多次事件）","form":"solar eclipses"},{"label":"相关形容词","form":"solar"},{"label":"相关天象","form":"partial solar eclipse（日偏食）"},{"label":"相关天象","form":"annular solar eclipse（日环食）"},{"label":"相关术语","form":"totality（全食阶段）"},{"label":"相关术语","form":"path of totality（全食带）"}],"derivatives":[{"word":"eclipse","pos":"n./v.","zh":"eclipse 加 -ed 构成过去式：遮住；日食这一词根本身来自希腊语，指天体「缺席」"},{"word":"solar","pos":"adj.","zh":"sol + -ar：太阳的；由拉丁 solaris 直接进入英语"},{"word":"ecliptic","pos":"adj./n.","zh":"eclipse 同族 + -tic：黄道；指太阳在一年中走过的路径，与日食同出希腊 ekleipsis 的词族"},{"word":"eclipsed","pos":"adj.","zh":"eclipse + -ed：被遮住的；引申为黯然失色的"}],"senses":[{"no":"01","title":"The moon hides the sun","titleCN":"月球运行到太阳与地球之间，遮住日光","definition":"the event in which the moon comes between the earth and the sun, so that the sun's light is cut off","definitionCN":"月球运行到太阳与地球之间，使日光被切断的天象","example":"A solar eclipse darkened the whole valley for four minutes.","exampleCN":"一次日食让整个山谷暗了四分钟。","why":"the phrase is literal: sol is the sun and eclipse comes from a Greek word for a body failing to appear, so the sun is described as being left without its light.","whyCN":"这个短语是字面组合：sol 指太阳，eclipse 出自希腊语「天体缺席」，因此说的是太阳被夺去了光。"},{"no":"02","title":"The few minutes of totality","titleCN":"全食阶段：日面被完全遮住","definition":"the short period during which the moon covers the sun completely, leaving only the corona visible","definitionCN":"月球把日面完全遮住、只剩日冕可见的短暂阶段","example":"During totality the sky went dark enough for planets to appear.","exampleCN":"全食阶段天色暗到能看见行星。","why":"totality is the abstract noun of total, and astronomers borrowed it for the only interval when the cover is complete.","whyCN":"totality 是 total 的抽象名词，天文学借它专指唯一完全遮住的那一段时间。"},{"no":"03","title":"Only part of the sun covered","titleCN":"偏食：日面只被遮住一部分","definition":"the event as seen where the moon covers only a portion of the sun's disc","definitionCN":"在只能看到月球遮住日面一部分的地点所见的天象","example":"From the northern coast the solar eclipse was only partial.","exampleCN":"在北部海岸只能看到日偏食。","why":"a partial eclipse is simply the same geometry seen off the central line, so partial names the observer's position, not a different event.","whyCN":"偏食只是同一几何关系在中心线之外看到的样子，因此 partial 说的是观测者的位置，而非另一种天象。"},{"no":"04","title":"A ring of light left visible","titleCN":"环食：月影较远，边缘留下一圈光","definition":"a solar eclipse in which the moon is too far away to cover the disc fully, leaving a bright ring","definitionCN":"月球距离较远、不足以完全遮住日面，边缘留下一圈亮环的日食","example":"An annular solar eclipse left a thin ring around the dark moon.","exampleCN":"一次日环食在黑月周围留下一道细亮环。","why":"annular comes from Latin anulus 'little ring', so the name describes the leftover shape rather than the darkness.","whyCN":"annular 出自拉丁 anulus「小环」，名字描述的是剩余的形状，而非黑暗本身。"},{"no":"05","title":"Daylight dimming on the ground","titleCN":"地面上天色转暗、气温下降的现场感受","definition":"the visible and measurable effects on the ground, such as falling light and a drop in temperature","definitionCN":"地面上可见可测的影响，如光照减弱与气温下降","example":"Shadows sharpened and the air cooled as the solar eclipse deepened.","exampleCN":"随着日食加深，影子变锐，空气也凉了下来。","why":"eclipse also names the experience of the event, because what an observer notices is not the geometry but the light failing.","whyCN":"eclipse 也指这场天象的现场体验，因为观测者注意到的不是几何关系，而是光在失效。"},{"no":"06","title":"The narrow track of the shadow","titleCN":"全食带：月影扫过的狭窄地带","definition":"the narrow strip on the earth's surface from which the full cover can be seen","definitionCN":"地表上能够看到完全遮挡的狭长地带","example":"Hotels along the path of the solar eclipse were booked a year ahead.","exampleCN":"日食带沿线的旅馆提前一年就被订满。","why":"the shadow of the moon is a small spot on a large planet, so the phrase names the strip where that spot passes, not the whole hemisphere.","whyCN":"月影只是巨大行星上的一个小点，因此这个短语指小点扫过的狭带，而非整个半球。"},{"no":"07","title":"A chance for science","titleCN":"科学观测与验证的机会","definition":"an occasion used by astronomers to test instruments, measure the corona or check a theory","definitionCN":"天文学家借此检验仪器、测量日冕或验证理论的机会","example":"The 1919 solar eclipse was used to test the bending of starlight.","exampleCN":"1919 年的日食被用来检验星光偏折。","why":"because the corona is visible only then, the event became a scheduled experiment, and the phrase carries that scientific use.","whyCN":"正因日冕只在此时可见，这场天象成了可按日程安排的实验，短语也带上这层科研用途。"},{"no":"08","title":"Figurative: a total overshadowing","titleCN":"比喻义：一时把人或事完全盖住","definition":"a figurative use for something that briefly hides or outshines another person or thing completely","definitionCN":"比喻某人或某物一时把另一个完全遮住、使其黯然失色","example":"The champion's farewell was a solar eclipse for the whole league.","exampleCN":"那位冠军的告别对整个联盟而言是一场日食。","why":"the image of a greater light being blotted out transfers easily to any figure whose presence hides everyone else.","whyCN":"更强的光被遮住这一意象很容易转用到任何一出现就让别人失色的人物身上。"}],"etymology":{"intro":{"en":"Solar eclipse joins Latin sol 'sun' (through solaris 'of the sun') to eclipse, from Greek ekleipsis 'a failing, an abandonment'. The compound is a modern English astronomical term built from two older borrowings. Dates are approximate.","cn":"solar eclipse 把拉丁 sol「太阳」（经 solaris「太阳的」）与 eclipse 并置，后者出自希腊 ekleipsis「失守、缺席」。这个复合词是英语近代天文学用语，由两个更早的借词构成。年代均为约数。"},"items":[{"era":"LATIN SOL","en":"Sol, solis was the ordinary Latin noun for the sun. It is not the source of English sun but a cognate of it: both descend from a reconstructed Indo-European form commonly written *soh₂wl̥, a reconstruction rather than an attested word.","cn":"sol, solis 是拉丁语里「太阳」的普通名词。它不是英语 sun 的来源，而是同源词：两者都出自一个通常写作 *soh₂wl̥ 的印欧重构形式，那是重构而非有书证的原词。"},{"era":"GREEK EKLEIPSIS","en":"Greek ekleipsis meant 'abandonment, failing, cessation', built from ek- 'out' and leipein 'to leave'. An eclipse was so called because a body was said to leave its expected place in the sky.","cn":"希腊 ekleipsis 意为「弃置、失守、中止」，由 ek-「出」与 leipein「离开」构成。天象被称为 eclipse，是因为天体被说成离开了它在天空应有的位置。"},{"era":"LATIN ECLIPSIS","en":"Latin borrowed the Greek noun as eclipsis, and medieval and Old French writing passed eclipse into English in the fourteenth century, first for the failure of light and later for the astronomical event.","cn":"拉丁语把希腊名词借作 eclipsis，中世纪与古法语书写又在 14 世纪把 eclipse 传入英语，最初指光的中断，之后指天文事件。"},{"era":"LATIN SOLARIS","en":"Solaris 'of the sun' gave English solar in the fifteenth century; the adjective supplies the first half of the modern compound.","cn":"solaris「太阳的」在 15 世纪给出英语 solar；这个形容词提供了现代复合词的前半。"},{"era":"THE COMPOUND","en":"The fixed term solar eclipse is generally believed to have settled in English astronomical writing during the seventeenth century, once eclipse was routinely qualified as solar or lunar.","cn":"一般认为，solar eclipse 这一固定术语在 17 世纪的英语天文写作中定型，当时 eclipse 已习惯性地加上 solar 或 lunar 作限定。"},{"era":"UNCERTAIN DETAILS","en":"Two different uncertainties must be kept apart. Root uncertainty: the pre-Greek origin of leipein is a reconstruction, and any Indo-European root offered for it is a hypothesis. First-date uncertainty only: the earliest printed occurrence of the exact phrase solar eclipse is not recorded, although the seventeenth-century settling of the term is well supported.","cn":"两类不确定必须分开。词根存疑：leipein 在希腊语之前的来源属重构形式，凡为其给出的印欧词根都只是假说。仅首见年代存疑：solar eclipse 这一确切短语的最早印刷记录不明，不过该术语在 17 世纪定型有充分依据。"}]},"similar":{"note":{"en":"Group one holds terms built on the same eclipse or sun stock that are easily swapped; group two holds the different events that also hide one body behind another.","cn":"第一组是同出 eclipse 或太阳词干、容易被替换的术语；第二组是同样让一个天体遮住另一个的不同天象。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"lunar eclipse","ipa":"/ˈluːnər ɪˈklɪps/","tag":"the moon is hidden","definition":"The moon, not the sun, is covered, and the earth casts the shadow. The two names cannot be exchanged, though both use eclipse.","definitionCN":"被遮住的是月亮而非太阳，投下影子的是地球。两个名称都用 eclipse，但不能互换。"},{"word":"eclipse","ipa":"/ɪˈklɪps/","tag":"the general event","definition":"The general noun for any such hiding; solar eclipse is the specific member of the pair, so the bare word needs context to be clear.","definitionCN":"泛指这类遮蔽事件的普通名词；solar eclipse 是这一对中的具体一方，因此单说 eclipse 需要语境才明确。"},{"word":"ecliptic","ipa":"/ɪˈklɪptɪk/","tag":"the sun's yearly path","definition":"A different astronomical noun: the plane of the sun's apparent yearly path. It belongs to the same Greek family but names a path, not an event.","definitionCN":"另一个天文名词：太阳视运动一年所走的平面。它与希腊词族同源，但指一条路径，而非一次事件。"}]},{"heading":"NEAR MEANING","entries":[{"word":"occultation","ipa":"/ˌɒkʌlˈteɪʃn/","tag":"one body hides another","definition":"The general astronomical term for any body passing in front of another, including stars hidden by the moon; eclipse is the special case involving the sun or moon and a shadow.","definitionCN":"泛指任何天体从另一天体前方经过，包括恒星被月球遮住；eclipse 是涉及日、月与影子的特例。"},{"word":"transit","ipa":"/ˈtrænzɪt/","tag":"a small disc crosses a big one","definition":"Used when a smaller body crosses a larger disc, as Venus across the sun; no shadow reaches the earth, which is why transit is not called an eclipse.","definitionCN":"用于小天体横过大圆面，如金星凌日；此时没有影子落到地球，因此不叫 eclipse。"},{"word":"totality","ipa":"/təʊˈtæləti/","tag":"the full-cover interval","definition":"The name of the phase, not of the event; a solar eclipse may or may not reach totality, so the two words answer different questions.","definitionCN":"指阶段名称而非事件本身；日食未必达到全食，因此这两个词回答的是不同问题。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"sol 'sun' + eclipse 'failing': the sun's light fails.","cn":"sol「太阳」+ eclipse「失守」：太阳的光失守了。"},{"en":"Three fixed types: total, partial, annular.","cn":"三种固定类型：全食、偏食、环食。"},{"en":"The family runs eclipse, ecliptic, solar, solstice.","cn":"同族词包括 eclipse、ecliptic、solar、solstice。"},{"en":"The path on the ground is the path of totality.","cn":"地面上的那条带叫全食带。"},{"en":"Never look directly; the collocation is solar eclipse glasses.","cn":"不能直视；固定搭配是日食观测镜。"}],"abstract":[{"en":"Picture a lamp switched off at noon while everyone still stands in the room.","cn":"想象正午有人关掉灯，而所有人仍站在房间里。"},{"en":"Picture a coin sliding across the face of a coin, leaving a bright rim.","cn":"想象一枚硬币滑过另一枚硬币的正面，留下一圈亮边。"},{"en":"Picture a great name walking into a room and every other name going quiet.","cn":"想象一个显赫的名字走进房间，其余名字都安静下来。"}]},"examples":[{"en":"The total solar eclipse was visible along a narrow band of the Pacific.","cn":"这次日全食沿太平洋一条狭长地带可见。"},{"en":"Astronomers travelled to the desert to photograph the solar eclipse.","cn":"天文学家前往沙漠拍摄这次日食。"},{"en":"Never view a solar eclipse without certified filters.","cn":"绝不要在无认证滤镜的情况下观看日食。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「sol（太阳）+ eclipse（缺席）」——太阳被月球遮得「缺席」了 → 日食","word":"solar eclipse"},"root":"拉丁 sol, solis「太阳」+ 希腊 ekleipsis「失守、缺席」← ek-「出」+ leipein「离开」；英语经拉丁 eclipsis 与古法语 eclipse 借入，再与 solaris→solar 组合成现代天文术语。leipein 的更深来源属重构形式。","sensesIntro":{"en":"Eight senses follow one geometry: a dark disc slides across the sun, and the same event is then read as totality, as partial cover, as a ring, as a change in the air, as a strip on the map, as an experiment and finally as a metaphor for being outshone.","cn":"八个义项沿同一几何关系展开：一枚暗盘滑过太阳；同一事件随后被读成全食、偏食、亮环、地面上的明暗变化、地图上的一条带、一次实验，最后读成「被比下去」的比喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: a black disc sliding across a bright face, dimming everything below.","cn":"核心意象：一枚黑盘滑过明亮的面孔，把下方的一切调暗。"},"chain":["LIGHT BLOCKED","TOTAL COVER","PARTIAL COVER","RING LEFT","GROUND DIMS","SHADOW STRIP"],"branches":[{"senses":"S1","en":"THE EVENT: the moon stands between earth and sun and the light is cut off.","cn":"事件本身：月球位于地球与太阳之间，光被切断。"},{"senses":"S2 · S5","en":"THE EXPERIENCE: complete cover and the felt change in light and air belong to the same few minutes.","cn":"现场体验：完全遮挡与光、气温的变化属于同几分钟。"},{"senses":"S3 · S4","en":"THE GEOMETRY SEEN OFF CENTRE: part of the disc, or a rim of it, is all that remains.","cn":"偏离中心所见的几何：只剩一部分日面，或一圈边缘。"},{"senses":"S6","en":"THE PLACE ON EARTH: the moon's small shadow draws a narrow strip across the map.","cn":"地表位置：月球的小影子在地图上画出一条狭带。"},{"senses":"S7 · S8","en":"THE USES: the event becomes a scheduled experiment, then an image for being overshadowed.","cn":"两种用途：事件成为可安排的实验，再成为「被盖过」的意象。"}]},"affixes":{"intro":{"en":"The phrase is built from two borrowed elements, one Latin and one Greek, plus the Latin adjective suffix -ar; no single root carries the whole meaning.","cn":"这个短语由两个借入成分构成，一为拉丁、一为希腊，再加拉丁形容词后缀 -ar；整体意义不落在单一词根上。"},"latinIntro":{"en":"Latin sol and solaris supply the first half; Greek ekleipsis, through Latin eclipsis, supplies the second; the family also includes ecliptic.","cn":"拉丁 sol 与 solaris 提供前半；希腊 ekleipsis 经拉丁 eclipsis 提供后半；同族还包括 ecliptic。"},"items":[{"word":"sol","structure":"sol, solis (Latin noun, third declension)","meaning":"the sun","meaningCN":"太阳","example":"Sol is the Roman name of the sun god as well as the noun.","exampleCN":"sol 既是罗马太阳神之名，也是「太阳」这一普通名词。"},{"word":"-ar","structure":"-aris (Latin adjective suffix)","meaning":"of or belonging to","meaningCN":"……的；属于……的","example":"Solaris was formed with this suffix from sol.","exampleCN":"solaris 就是由 sol 加这个后缀构成。"},{"word":"ek-","structure":"ek- (Greek prefix)","meaning":"out, away from","meaningCN":"向外；离开","example":"The prefix marks departure in ekleipsis.","exampleCN":"这个前缀在 ekleipsis 中标出「离开」。"},{"word":"leipein","structure":"leipein (Greek verb)","meaning":"to leave, to fail","meaningCN":"离开；失守","example":"The root gives the sense of something not being where it should be.","exampleCN":"这个词根给出「某物不在应在之处」的意思。"},{"word":"eclipse","structure":"eclipsis (Latin) < ekleipsis (Greek)","meaning":"a failing; the hiding of one body by another","meaningCN":"失守；一个天体被另一个遮住","example":"English eclipse came through Old French.","exampleCN":"英语 eclipse 经古法语传入。"},{"word":"solar","structure":"sol + -ar","meaning":"of the sun","meaningCN":"太阳的","example":"Solar panels take their name from the same adjective.","exampleCN":"太阳能板的名字就来自这个形容词。"},{"word":"ecliptic","structure":"eclipse + -tic (adjective suffix)","meaning":"the sun's apparent yearly path","meaningCN":"黄道","example":"The ecliptic is the line along which eclipses can occur.","exampleCN":"黄道正是可能发生日食的那条线。"},{"word":"solar eclipse","structure":"solar + eclipse","meaning":"the sun hidden by the moon","meaningCN":"月球遮住太阳的天象","example":"The compound fixes the sun as the body being hidden.","exampleCN":"这个复合词固定了被遮住的天体是太阳。"},{"word":"totality","structure":"total + -ity (state)","meaning":"the state of being complete","meaningCN":"完全的状态","example":"Astronomers use it for the fully covered phase.","exampleCN":"天文学家用它指完全被遮住的阶段。"}],"latinEntries":[{"word":"sol","structure":"sol, solis (m., third declension)","meaning":"the sun","meaningCN":"太阳"},{"word":"solaris","structure":"solaris, solare (adjective, third declension)","meaning":"of the sun","meaningCN":"太阳的"},{"word":"eclipsis","structure":"eclipsis, eclipsis (f., third declension)","meaning":"an eclipse; a failing","meaningCN":"食；失守"}]}},{"word":"lunar eclipse","ipa_uk":"/ˈluːnər ɪˈklɪps/","ipa_us":"/ˈluːnər ɪˈklɪps/","definition_zh":"月食；月蚀（地球运行到太阳与月球之间、地球影子落到月面）","definition_en":"the event in which the earth comes between the sun and the moon and the earth's shadow falls on the moon","core_image":"满月的边缘先缺一小块，缺口慢慢爬满整个月面，最后月亮变成一枚暗铜色的圆盘","scene":"夜里看月亮慢慢缺了一角又转成铜红，你说 A lunar eclipse left the moon copper-red.","sceneCN":"这里 lunar eclipse 指「地球挡住射向月球的光、影子落到月面」（第 5 个义项：全食时月面被折射的红光染成铜色）；句意为一次月食让月亮变成铜红色。图中可辨识物件：满月、地球影子、望远镜、红色月面。","pos":[{"tag":"n.","zh":"月食；月蚀（可数，指一次具体天象；亦作定语，如 lunar eclipse photography）"}],"collocations":[{"phrase":"total lunar eclipse","zh":"月全食"},{"phrase":"partial lunar eclipse","zh":"月偏食"},{"phrase":"penumbral lunar eclipse","zh":"半影月食"},{"phrase":"watch a lunar eclipse","zh":"观看月食"},{"phrase":"the stages of a lunar eclipse","zh":"月食的各阶段"},{"phrase":"a lunar eclipse at totality","zh":"全食时的月食"}],"forms":[{"label":"复数（指多次事件）","form":"lunar eclipses"},{"label":"相关形容词","form":"lunar"},{"label":"相关天象","form":"partial lunar eclipse（月偏食）"},{"label":"相关天象","form":"penumbral lunar eclipse（半影月食）"},{"label":"相关术语","form":"umbra（本影）"},{"label":"相关术语","form":"totality（全食阶段）"}],"derivatives":[{"word":"lunar","pos":"adj.","zh":"luna + -ar：月亮的；由拉丁 lunaris 进入英语"},{"word":"eclipse","pos":"n./v.","zh":"eclipse 加 -ed 构成过去式；词根出自希腊语「缺失」"},{"word":"eclipsed","pos":"adj.","zh":"eclipse + -ed：被遮住的；引申为黯然失色"},{"word":"lunation","pos":"n.","zh":"luna + -ation：一个朔望月周期；同一词根的历法用语"}],"senses":[{"no":"01","title":"The earth's shadow falls on the moon","titleCN":"地球挡住日光，影子落到月面","definition":"the event in which the earth blocks sunlight and casts its shadow on the moon","definitionCN":"地球挡住射向月球的日光、把影子投在月面上的天象","example":"A lunar eclipse is safe to watch without filters.","exampleCN":"月食无需滤镜即可安全观看。","why":"the phrase is literal: luna is the moon, and eclipse is the Greek word for a body failing to appear; here it is the moon that loses its light.","whyCN":"这个短语是字面组合：luna 指月亮，eclipse 是希腊语「天体缺席」；此处失去光的是月亮。"},{"no":"02","title":"The moon fully in shadow","titleCN":"月全食：月面完全进入本影","definition":"the phase in which the whole visible disc of the moon lies inside the earth's dark umbra","definitionCN":"整个可见月面都进入地球本影的阶段","example":"Totality lasted over an hour during the total lunar eclipse.","exampleCN":"这次月全食的全食阶段持续了一小时以上。","why":"totality names the interval when no direct sunlight reaches the moon, and the phrase borrows that noun unchanged.","whyCN":"totality 指没有直射阳光照到月面的那段时间，短语直接借用了这个名词。"},{"no":"03","title":"Only part of the moon shadowed","titleCN":"月偏食：只有一部分月面进入本影","definition":"the phase in which only part of the moon enters the dark umbra","definitionCN":"只有一部分月面进入暗黑本影的阶段","example":"A partial lunar eclipse left the upper edge still bright.","exampleCN":"一次月偏食让月亮的上缘仍然明亮。","why":"partial describes where the observer's line of sight cuts the geometry, so it marks a stage of the same event rather than a new one.","whyCN":"partial 描述观察视线切过几何体的位置，因此它标出的是同一事件的一个阶段，而非新事件。"},{"no":"04","title":"A faint shading in the outer shadow","titleCN":"半影月食：只有外层淡影扫过","definition":"the faint dimming seen when the moon passes only through the outer penumbra","definitionCN":"月球只穿过外层半影时看到的轻微变暗","example":"A penumbral lunar eclipse is easy to miss with the naked eye.","exampleCN":"半影月食肉眼很容易错过。","why":"penumbra is Latin paene 'almost' plus umbra 'shadow', so the word already says the shade is almost-shadow, barely visible.","whyCN":"penumbra 是拉丁 paene「几乎」加 umbra「影子」，词本身就说明这层影「几乎是影」，几乎看不见。"},{"no":"05","title":"The copper-red blood moon","titleCN":"铜红色：全食时月面被折射的红光染红","definition":"the reddish colour of the moon during totality, caused by sunlight bent through the earth's atmosphere","definitionCN":"全食时因阳光穿过地球大气折射而使月面呈现的红铜色","example":"The lunar eclipse turned the moon a deep copper red.","exampleCN":"这次月食把月亮染成深铜红色。","why":"the colour is not a separate event but the visible signature of totality: red light is what survives the long slant through the atmosphere.","whyCN":"这颜色不是另一件事，而是全食的可见标记：只有红光能在长长的斜穿大气后留下。"},{"no":"06","title":"The timed stages of the event","titleCN":"月食的分阶段过程与持续时间","definition":"the sequence of contact points and durations by which the event is timed and predicted","definitionCN":"用各接触时刻与持续时间来记录与预报的过程","example":"Observers logged every stage of the lunar eclipse in a table.","exampleCN":"观测者用表格记录了这次月食的每一个阶段。","why":"because the shadow is wide and the event slow, it can be clocked stage by stage, and the phrase covers that timed reading.","whyCN":"由于影子很宽、过程缓慢，可以逐阶段计时，短语也覆盖这一计时读法。"},{"no":"07","title":"A calendar event in older astronomy","titleCN":"古代历法与天象记录中的一个事件","definition":"a dated event recorded in calendars and chronicles, used to order reigns and to test prediction","definitionCN":"被记入历法与编年史、用来排定年代并检验预报的带日期事件","example":"Chronicles used the lunar eclipse to fix the year of the battle.","exampleCN":"编年史用这次月食确定战役发生之年。","why":"an eclipse is one of the few ancient events with an exact date, so it became a peg for chronology and for testing cycles.","whyCN":"月食是古代少数有确切日期的事件之一，因此成了年代学的挂钉，也用来检验周期。"},{"no":"08","title":"Figurative: a temporary dimming","titleCN":"比喻义：光彩被暂时掩住","definition":"a figurative use for a period in which someone's brilliance is temporarily obscured","definitionCN":"比喻某人的光彩被暂时遮住的一段时间","example":"The scandal was a lunar eclipse for a career otherwise full of light.","exampleCN":"那场丑闻对一段本来光亮的职业生涯而言是一场月食。","why":"the metaphor works because a lunar eclipse hides but does not destroy the moon: the light returns.","whyCN":"这个比喻成立，是因为月食只是遮住月亮而非毁掉它：光会回来。"}],"etymology":{"intro":{"en":"Lunar eclipse pairs Latin luna 'moon' (through lunaris 'of the moon') with eclipse, from Greek ekleipsis 'a failing, an abandonment'. Both halves are borrowings, and the compound is a modern English astronomical term. Dates are approximate.","cn":"lunar eclipse 把拉丁 luna「月亮」（经 lunaris「月亮的」）与 eclipse 并置，后者出自希腊 ekleipsis「失守、缺席」。两半都是借词，复合词是英语近代天文学用语。年代均为约数。"},"items":[{"era":"LATIN LUNA","en":"Luna was the Latin noun for the moon and also the name of the moon goddess. Its deeper origin is disputed: a link with lucere 'to shine' is a hypothesis, not a demonstrated derivation.","cn":"luna 是拉丁语「月亮」的名词，也是月神之名。它的更深来源有争议：与 lucere「发光」的联系只是假说，并非已证实的派生。"},{"era":"GREEK EKLEIPSIS","en":"Greek ekleipsis 'abandonment, failing' came from ek- 'out' plus leipein 'to leave'. The moon was said to leave its light behind.","cn":"希腊 ekleipsis「弃置、失守」来自 ek-「出」加 leipein「离开」。月亮被说成把光留在了身后。"},{"era":"LATIN ECLIPSIS TO ENGLISH","en":"Latin eclipsis and Old French eclipse carried the noun into English in the fourteenth century; the astronomical event was among its earliest senses.","cn":"拉丁 eclipsis 与古法语 eclipse 在 14 世纪把这个名词带进英语，天文事件是其最早的义项之一。"},{"era":"LATIN LUNARIS","en":"Lunaris 'of the moon' gave English lunar in the sixteenth century, supplying the qualifying adjective for the compound.","cn":"lunaris「月亮的」在 16 世纪给出英语 lunar，为复合词提供限定形容词。"},{"era":"THE PAIR WITH SOLAR","en":"Lunar and solar eclipses were distinguished routinely once eclipse became a general astronomical term, and the pair fixed the naming pattern used today.","cn":"eclipse 成为通用天文术语后，月食与日食被习惯性区分，这一对词固定了今日的命名方式。"},{"era":"UNCERTAIN DETAILS","en":"Root uncertainty: the origin of luna itself is unsettled, and the lucere connection is only a hypothesis; the pre-Greek source of leipein is a reconstruction. First-date uncertainty only: the earliest printed use of the exact phrase lunar eclipse is not recorded.","cn":"词根存疑：luna 本身的来源无定论，与 lucere 的联系仅为假说；leipein 在希腊语之前的来源属重构形式。仅首见年代存疑：lunar eclipse 这一确切短语的最早印刷记录不明。"}]},"similar":{"note":{"en":"Group one holds the eclipse terms most often swapped with this one; group two holds the parts of the shadow and the popular name for the red phase.","cn":"第一组是最容易与本词互换的「食」类术语；第二组是影子各部分与红色阶段的俗称。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"solar eclipse","ipa":"/ˌsəʊlər ɪˈklɪps/","tag":"the sun is hidden","definition":"The sun is covered and the moon casts the shadow; here the earth is the caster and the moon the covered body, so the two names are mirror images.","definitionCN":"被遮的是太阳、投影的是月球；本词则是地球投影、月球被遮，两个名称正好互为镜像。"},{"word":"eclipse","ipa":"/ɪˈklɪps/","tag":"the general event","definition":"The general noun for either hiding; lunar eclipse is the specific member, so the bare word alone does not say which body is covered.","definitionCN":"泛指任一种遮蔽；lunar eclipse 是其中的具体一方，单说 eclipse 不能表明被遮的是哪个天体。"},{"word":"ecliptic","ipa":"/ɪˈklɪptɪk/","tag":"the sun's yearly path","definition":"A noun of the same Greek family naming a path in the sky, not an event; eclipses can occur only near it.","definitionCN":"同一希腊词族的名词，指天上的路径而非事件；食只能发生在它附近。"}]},{"heading":"NEAR MEANING","entries":[{"word":"umbra","ipa":"/ˈʌmbrə/","tag":"the dark inner shadow","definition":"The fully dark part of the earth's shadow; the moon must enter it for a total eclipse, so umbra names the cause, not the event.","definitionCN":"地球影子里全黑的部分；月球须进入其中才有全食，因此 umbra 指成因，不指事件。"},{"word":"penumbra","ipa":"/pɪˈnʌmbrə/","tag":"the faint outer shadow","definition":"The half-lit outer shadow; passing through it gives only a slight dimming, which is why a penumbral eclipse looks unremarkable.","definitionCN":"半明的外层影子；只穿过它时仅有轻微变暗，因此半影月食看起来并不显眼。"},{"word":"blood moon","ipa":"/blʌd muːn/","tag":"popular name for the red phase","definition":"A popular, non-technical name for the moon during totality; it describes the colour, while lunar eclipse names the event.","definitionCN":"全食时月亮的通俗非术语名称；它描述颜色，而 lunar eclipse 指事件。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"luna 'moon' + eclipse 'failing': the moon's light fails.","cn":"luna「月亮」+ eclipse「失守」：月亮的光失守了。"},{"en":"Three fixed types: total, partial, penumbral.","cn":"三种固定类型：全食、偏食、半影食。"},{"en":"The shadow has two parts: umbra and penumbra.","cn":"影子分两部分：本影与半影。"},{"en":"The red phase is popularly the blood moon.","cn":"红色阶段俗称血月。"},{"en":"The family runs lunar, lunation, eclipse, ecliptic.","cn":"同族词包括 lunar、lunation、eclipse、ecliptic。"}],"abstract":[{"en":"Picture a lamp behind a chair throwing a round shadow onto a white wall.","cn":"想象椅子后面的灯把一圈影子投在白墙上。"},{"en":"Picture a coin sliding into a wide soft shadow and turning copper.","cn":"想象一枚硬币滑进一片宽而柔的影子里，变成铜色。"},{"en":"Picture a stage light dimming for one act and then coming back up.","cn":"想象舞台灯在某一幕暗下去，随后又亮起来。"}]},"examples":[{"en":"A lunar eclipse can be seen from anywhere on the night side of the earth.","cn":"地球夜半球的任何地方都能看到月食。"},{"en":"The moon entered the umbra and the lunar eclipse began.","cn":"月亮进入本影，月食开始了。"},{"en":"Photographers waited all night for the lunar eclipse to reach totality.","cn":"摄影师整夜等待月食进入全食。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「luna（月亮）+ eclipse（缺席）」——月亮的光「缺席」了 → 月食","word":"lunar eclipse"},"root":"拉丁 luna「月亮」（更深来源有争议，与 lucere「发光」的联系仅为假说）+ 希腊 ekleipsis「失守、缺席」← ek-「出」+ leipein「离开」；经拉丁 eclipsis 与古法语 eclipse 借入，再与 lunaris→lunar 组合。","sensesIntro":{"en":"Eight senses follow one shadow: the earth stands in the light and throws it onto the moon, and the same event is then read as total cover, partial cover, faint shade, red colour, timed stages, a calendar peg and finally as a metaphor for light that returns.","cn":"八个义项沿同一片影子展开：地球挡在光里，把影子投到月面；同一事件随后被读成全遮、部分遮、淡影、红色、分段计时、历法挂钉，最后读成「光会回来」的比喻。"},"semanticMap":{"core":{"en":"CORE IMAGE: the earth's round shadow sliding across a full moon until the disc turns copper.","cn":"核心意象：地球的圆影滑过一轮满月，直到月面变成铜色。"},"chain":["SHADOW FALLS","FULL COVER","PART COVER","FAINT SHADE","RED GLOW","TIMED CYCLE"],"branches":[{"senses":"S1","en":"THE EVENT: the earth intercepts the sunlight and the moon is left in shadow.","cn":"事件本身：地球截住日光，月亮被留在影中。"},{"senses":"S2 · S5","en":"FULL COVER AND COLOUR: the red disc is what complete shadow looks like.","cn":"全遮与颜色：红色圆盘就是完全入影后的样子。"},{"senses":"S3 · S4","en":"PARTIAL AND FAINT: part of the disc in the umbra, or the whole disc in the pale penumbra.","cn":"部分与淡影：或一部分进入本影，或整个月面只在外层半影。"},{"senses":"S6 · S7","en":"TIMED AND DATED: the stages can be clocked, and the dated event anchors calendars.","cn":"计时与纪年：阶段可逐一刻表，带日期的事件又成为历法的锚点。"},{"senses":"S8","en":"THE METAPHOR: a hiding that ends, because the moon keeps its light.","cn":"比喻：一次会结束的遮蔽，因为月亮仍保有它的光。"}]},"affixes":{"intro":{"en":"The phrase joins a Latin moon noun and adjective suffix to a Greek-derived noun of failing; each element still lives in other English words.","cn":"这个短语把拉丁的「月亮」名词与形容词后缀，接到一个希腊来源的「失守」名词上；每个成分都还活在别的英语词里。"},"latinIntro":{"en":"Latin luna and lunaris supply lunar and lunation; Greek ekleipsis through Latin eclipsis supplies eclipse, and Latin umbra supplies the shadow words.","cn":"拉丁 luna 与 lunaris 提供 lunar 与 lunation；希腊 ekleipsis 经拉丁 eclipsis 提供 eclipse；拉丁 umbra 提供影子的相关词。"},"items":[{"word":"luna","structure":"luna, lunae (Latin noun, first declension)","meaning":"the moon","meaningCN":"月亮","example":"Luna also named the moon goddess.","exampleCN":"luna 也是月神之名。"},{"word":"-ar","structure":"-aris (Latin adjective suffix)","meaning":"of or belonging to","meaningCN":"……的；属于……的","example":"Lunaris was built with this suffix from luna.","exampleCN":"lunaris 由 luna 加这个后缀构成。"},{"word":"ek-","structure":"ek- (Greek prefix)","meaning":"out, away from","meaningCN":"向外；离开","example":"It marks departure in ekleipsis.","exampleCN":"它在 ekleipsis 中标出「离开」。"},{"word":"leipein","structure":"leipein (Greek verb)","meaning":"to leave, to fail","meaningCN":"离开；失守","example":"The root supplies the sense of absence.","exampleCN":"这个词根给出「缺席」的意思。"},{"word":"eclipse","structure":"eclipsis (Latin) < ekleipsis (Greek)","meaning":"a failing; a hiding of one body","meaningCN":"失守；天体被遮","example":"The noun entered English through Old French.","exampleCN":"这个名词经古法语进入英语。"},{"word":"lunar","structure":"luna + -ar","meaning":"of the moon","meaningCN":"月亮的","example":"A lunar eclipse is an eclipse of the moon.","exampleCN":"月食就是发生在月亮上的食。"},{"word":"lunation","structure":"luna + -ation (action or period)","meaning":"one cycle of moon phases","meaningCN":"一个朔望月周期","example":"The word belongs to the same calendar vocabulary.","exampleCN":"这个词属于同一套历法词汇。"},{"word":"umbra","structure":"umbra, umbrae (Latin noun, first declension)","meaning":"shadow","meaningCN":"影子","example":"The umbra is the fully dark part of the shadow.","exampleCN":"本影是影子中全黑的部分。"},{"word":"penumbra","structure":"paene 'almost' + umbra","meaning":"the almost-shadow","meaningCN":"半影","example":"A penumbral eclipse is barely visible.","exampleCN":"半影月食几乎看不出来。"},{"word":"lunar eclipse","structure":"lunar + eclipse","meaning":"the moon hidden by the earth's shadow","meaningCN":"地球影子落到月面","example":"The compound fixes the moon as the hidden body.","exampleCN":"这个复合词固定了被遮住的是月亮。"}],"latinEntries":[{"word":"luna","structure":"luna, lunae (f., first declension)","meaning":"the moon","meaningCN":"月亮"},{"word":"lunaris","structure":"lunaris, lunare (adjective, third declension)","meaning":"of the moon","meaningCN":"月亮的"},{"word":"eclipsis","structure":"eclipsis, eclipsis (f., third declension)","meaning":"an eclipse; a failing","meaningCN":"食；失守"},{"word":"umbra","structure":"umbra, umbrae (f., first declension)","meaning":"shadow","meaningCN":"影子"}]}},{"word":"star","ipa_uk":"/stɑː/","ipa_us":"/stɑːr/","definition_zh":"星；恒星；夜空中的光点；星形符号；明星；主演","definition_en":"a self-luminous ball of gas in space, or any bright point in the night sky, or a famous performer, or a star-shaped mark","core_image":"深蓝夜空里一点稳定的亮光，周围其他光点都在轻轻闪烁，只有它像钉子一样钉住","scene":"夜里抬头指着最亮的那一点，你说 That star is brighter than the others.","sceneCN":"这里 star 指「夜空中可见的一个发光点」（第 2 个义项：肉眼所见的天上光点，未必是真恒星）；句意为那颗星比别的都亮。图中可辨识物件：深蓝夜空、一个明显更亮的光点、周围较暗的星点、望远镜。","pos":[{"tag":"n.","zh":"星；恒星；光点；星形符号；明星；星级"},{"tag":"v.","zh":"主演；以……为主角"}],"collocations":[{"phrase":"a bright star","zh":"一颗明亮的星"},{"phrase":"the North Star","zh":"北极星"},{"phrase":"star in a film","zh":"主演一部电影"},{"phrase":"five-star hotel","zh":"五星级酒店"},{"phrase":"star rating","zh":"星级评定"},{"phrase":"written in the stars","zh":"命中注定"},{"phrase":"a star athlete","zh":"明星运动员"}],"forms":[{"label":"复数","form":"stars"},{"label":"三单（he/she/it）","form":"stars"},{"label":"过去式","form":"starred"},{"label":"过去分词","form":"starred"},{"label":"现在分词","form":"starring"},{"label":"形容词（多星的）","form":"starry"}],"derivatives":[{"word":"starry","pos":"adj.","zh":"star + -y：多星的；星状的；由本词加形容词后缀"},{"word":"stardom","pos":"n.","zh":"star + -dom：明星地位；后缀表身份或领域"},{"word":"starlight","pos":"n.","zh":"star + light：复合名词，指星光"},{"word":"starless","pos":"adj.","zh":"star + -less：无星的；后缀表缺乏"},{"word":"starring","pos":"adj./n.","zh":"star + -ing：领衔主演的；动词分词作定语"}],"senses":[{"no":"01","title":"A self-luminous ball of gas","titleCN":"自身发光的巨大气体球：恒星","definition":"a massive ball of gas that shines by nuclear fusion, such as the sun","definitionCN":"靠核聚变发光的大型气体球，如太阳","example":"The sun is an ordinary star in an ordinary galaxy.","exampleCN":"太阳只是普通星系中一颗普通的恒星。","why":"the modern astronomical sense is narrow: only a body that makes its own light counts, which is why the sun is a star and the moon is not.","whyCN":"现代天文学义很窄：只有自己发光的才算法，因此太阳是恒星而月亮不是。"},{"no":"02","title":"A bright point in the night sky","titleCN":"夜空中肉眼可见的光点","definition":"any luminous point seen in the night sky, whether a true star, a planet or a distant sun","definitionCN":"夜空中任何可见的亮点，无论真恒星、行星还是遥远的太阳","example":"That star is brighter than the others.","exampleCN":"那颗星比别的都亮。","why":"before telescopes, every point of light looked alike, so the everyday sense keeps the older, wider meaning that includes planets.","whyCN":"在望远镜之前，所有光点看起来都一样，因此日常义保留了包含行星的较宽旧义。"},{"no":"03","title":"A star-shaped mark","titleCN":"星形符号；星号状的记号","definition":"a mark or symbol with radiating points, used in printing, grading or decoration","definitionCN":"带放射状尖角的符号，用于印刷、评级或装饰","example":"A star beside the title marks a revised edition.","exampleCN":"标题旁的星号表示修订版。","why":"the shape sense is very old: a drawn star is a simplified picture of the radiating light, and the mark keeps that picture.","whyCN":"形状义很古老：画出来的星是对放射光芒的简化图示，符号保留的正是这幅图。"},{"no":"04","title":"A famous performer","titleCN":"明星：出名的演员或表演者","definition":"a very famous actor, singer or athlete","definitionCN":"非常出名的演员、歌手或运动员","example":"She became a star before she turned twenty.","exampleCN":"她二十岁前就成了明星。","why":"theatre slang of the nineteenth century borrowed the sky image: the star is the one point everyone in the audience looks at.","whyCN":"19 世纪的剧场俚语借用了天上的意象：明星就是全场观众都看的那一点。"},{"no":"05","title":"To play the leading role","titleCN":"主演；担任主角","definition":"to appear as the leading performer in a film or play","definitionCN":"在电影或戏剧中担任主要表演者","example":"He starred in three films that year.","exampleCN":"那年他主演了三部电影。","why":"the verb is the celebrity noun turned into an action: to star is to be the point the production is built around.","whyCN":"动词是明星名词的动作化：to star 就是成为整部作品围绕的那一点。"},{"no":"06","title":"A rating symbol","titleCN":"星级：用星数表示质量的记号","definition":"a symbol used in sets to grade quality, as in a five-star rating","definitionCN":"成组使用、以星数表示质量等级的符号","example":"The restaurant earned a third star this year.","exampleCN":"这家餐厅今年拿到了第三颗星。","why":"a countable mark makes quality countable, so hotels and restaurants were ranked in stars rather than in words.","whyCN":"可数的符号让质量也可数，于是旅馆与餐厅用星数而非文字来分级。"},{"no":"07","title":"Destiny fixed in the sky","titleCN":"命数：被认为写在天上的命运","definition":"a person's fate, imagined as determined by the position of the stars at birth","definitionCN":"被认为由出生时星位决定的个人命运","example":"Their meeting seemed written in the stars.","exampleCN":"他们的相遇像是命中注定。","why":"astrology read the sky as a text, so the plural the stars came to mean the written fate rather than the bodies themselves.","whyCN":"占星把天空当作文本，于是复数 the stars 转而指写好的命数，而非天体本身。"},{"no":"08","title":"The main attraction","titleCN":"展览或演出中最吸引人的那一个","definition":"the person or object that a show or exhibition is built around","definitionCN":"演出或展览围绕其展开的人或物","example":"The manuscript is the star of the collection.","exampleCN":"这份手稿是整批藏品中的明星。","why":"the metaphor extends from people to objects: whatever the crowd comes for is the star, even if it is a fossil.","whyCN":"这个比喻从人扩展到物：人群为之而来的那一个就是明星，哪怕它是一块化石。"}],"etymology":{"intro":{"en":"Star is native English, from Old English steorra, and has no Latin source; its Latin and Greek relatives are cognates from the same reconstructed Indo-European root. Dates are approximate.","cn":"star 是英语本族词，来自古英语 steorra，并非拉丁来源；它的拉丁与希腊同族词出自同一印欧重构词根，属同源而非派生。年代均为约数。"},"items":[{"era":"OLD ENGLISH STEORRA","en":"Steorra is the Old English noun for a star, recorded before the Norman conquest and unchanged in meaning.","cn":"steorra 是古英语的「星」，诺曼征服之前已有记录，意义未变。"},{"era":"GERMANIC COGNATES","en":"The word belongs to a Germanic set that includes Old High German sterro and Gothic stairno, all pointing to a common Germanic form.","cn":"这个词属于一个日耳曼词集，包括古高地德语 sterro 与哥特语 stairno，都指向一个共同的日耳曼形式。"},{"era":"LATIN AND GREEK COGNATES","en":"Latin stella and Greek aster are cognates, not sources: all these forms descend from a reconstructed Indo-European root commonly written *ster-, a reconstruction rather than an attested word.","cn":"拉丁 stella 与希腊 aster 是同源词，而非来源：这些形式都出自一个通常写作 *ster- 的印欧重构词根，那是重构而非有书证的原词。"},{"era":"THE ASTRONOMICAL NARROWING","en":"Once it was shown that the sun is itself a star, the technical sense narrowed to a self-luminous body, while everyday speech kept the wider sense of any point of light.","cn":"在确认太阳本身是一颗恒星之后，术语义收窄为自身发光的天体，而日常说法仍保留「任何光点」的宽义。"},{"era":"THE CELEBRITY SENSE","en":"The theatrical use of star for the leading performer is generally dated to the nineteenth century, when playbills began to set the favourite's name in large type.","cn":"一般认为，star 指领衔演员的剧场用法始于 19 世纪，当时海报开始把最受欢迎者的名字排成大号字。"},{"era":"UNCERTAIN DETAILS","en":"Root uncertainty: the Indo-European root *ster- is a reconstruction, and its deeper shape is debated. First-date uncertainty only: the first use of star for a celebrity is not exactly dated and is usually placed somewhere in the nineteenth century.","cn":"词根存疑：印欧词根 *ster- 属重构形式，其更早形态仍有争论。仅首见年代存疑：star 指明星的最早用例没有确切年代，通常笼统定在 19 世纪。"}]},"similar":{"note":{"en":"Group one holds sky objects and words that look like relatives; group two holds the everyday near-equivalents of the fame and mark senses.","cn":"第一组是天体以及看起来像同族的词；第二组是「名声」与「符号」两个义项的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"planet","ipa":"/ˈplænɪt/","tag":"a body that does not shine by itself","definition":"A planet orbits a star and shines only by reflected light; Greek planētēs meant 'wanderer', because planets drift against the fixed stars.","definitionCN":"行星绕恒星运行，只反射光；希腊 planētēs 意为「漫游者」，因为行星在恒星间移动。"},{"word":"stellar","ipa":"/ˈstelər/","tag":"the adjective","definition":"The adjective meaning 'of stars', borrowed from Latin stella; it never replaces the noun star in ordinary use.","definitionCN":"意为「恒星的」形容词，借自拉丁 stella；日常使用中不能替代名词 star。"},{"word":"asterisk","ipa":"/ˈæstərɪsk/","tag":"the small star mark","definition":"From Greek asteriskos 'little star', a diminutive of aster; it names the typed symbol rather than a celestial body.","definitionCN":"出自希腊 asteriskos「小星」，是 aster 的指小形式；它指打字符号而非天体。"}]},{"heading":"NEAR MEANING","entries":[{"word":"celebrity","ipa":"/səˈlebrəti/","tag":"fame itself or a famous person","definition":"A neutral, often journalistic word for fame and the famous; star adds the image of being the point everyone watches.","definitionCN":"对名声与名人的中性、常为新闻体的说法；star 多了「众人目光汇聚之点」的意象。"},{"word":"sun","ipa":"/sʌn/","tag":"our own star","definition":"The proper name of the star nearest to us; astronomy says the sun is a star, but the two words are not interchangeable in idiom.","definitionCN":"离我们最近的恒星的名字；天文学说太阳是恒星，但两个词在惯用语中不能互换。"},{"word":"asteroid","ipa":"/ˈæstərɔɪd/","tag":"a rocky body, star-like in shape","definition":"Greek astēr 'star' plus -oeidēs 'like': it means star-like in appearance, not a star, and names a small rocky body.","definitionCN":"希腊 astēr「星」加 -oeidēs「像」：意为外形像星，并非恒星，指小岩石天体。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"One sky word, three lives: a sun, a famous face, a typed mark.","cn":"一个天空词，三种活法：恒星、名人、打出的符号。"},{"en":"The family runs starry, stardom, starlight, starless.","cn":"同族词包括 starry、stardom、starlight、starless。"},{"en":"Stars are graded: a five-star hotel.","cn":"星级可以计数：五星级旅馆。"},{"en":"The verb takes the same form: he stars in the film.","cn":"动词同形：他主演这部电影。"},{"en":"Latin stella and Greek aster are cousins, not parents.","cn":"拉丁 stella 与希腊 aster 是表亲，不是父母。"}],"abstract":[{"en":"Picture one nail holding a whole map of glittering pins in place.","cn":"想象一枚钉子把满图闪亮的针都固定在原位。"},{"en":"Picture a theatre where every light is turned off except one.","cn":"想象一座剧院，所有灯都关掉，只剩一盏。"},{"en":"Picture a small drawn star stamped on a page to mean quality.","cn":"想象纸页上盖着一枚手绘小星，用来表示品质。"}]},"examples":[{"en":"The brightest star in the sky is Sirius.","cn":"夜空中最亮的恒星是天狼星。"},{"en":"She starred in a documentary about the reef.","cn":"她主演了一部关于珊瑚礁的纪录片。"},{"en":"The guide gave the trail a two-star difficulty rating.","cn":"指南把这条步道评为两星难度。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「star」读音像「是他」——夜空中最亮的那点「就是他」 → 星；引申为明星","word":"star"},"root":"古英语 steorra「星」，属日耳曼本族词；与拉丁 stella、希腊 aster 同出印欧重构词根 *ster-（重构形式，非派生关系）；「明星」义一般认为始于 19 世纪剧场用语。","sensesIntro":{"en":"Eight senses follow one image: a single point that everyone can see, and that point is then a burning sun, a night light, a drawn mark, a famous face, a leading role, a quality grade, a written fate and the main attraction.","cn":"八个义项沿同一个意象展开：一个所有人都看得见的点；这个点依次是燃烧的太阳、夜空的光、画出的符号、成名的面孔、领衔的角色、质量的等级、写好的命数、最吸引人的展品。"},"semanticMap":{"core":{"en":"CORE IMAGE: one steady point of light among many flickering ones.","cn":"核心意象：许多闪烁光点中一个稳定的亮点。"},"chain":["POINT OF LIGHT","SUN AMONG SUNS","MARK OF RAYS","STAR OF THE STAGE","GRADE IN STARS","WRITTEN FATE"],"branches":[{"senses":"S1 · S2","en":"LIGHT IN THE SKY: the astronomical body and the everyday point of light.","cn":"天上的光：天文学上的恒星与日常所见的光点。"},{"senses":"S3 · S6","en":"DRAWN MARKS: the radiating shape and the countable grade.","cn":"画出的记号：放射状图形与可数的等级。"},{"senses":"S4 · S5","en":"THE WATCHED PERSON: fame and the leading role it brings.","cn":"被注视的人：名声与随之而来的主角位置。"},{"senses":"S7","en":"THE WRITTEN SKY: fate read in the positions of stars.","cn":"写好的天空：从星位读出的命数。"},{"senses":"S8","en":"THE MAIN THING: any object a whole exhibition is built around.","cn":"最主要的那一个：整场展览围绕的任何物件。"}]},"affixes":{"intro":{"en":"Star is a free native English root that takes ordinary Germanic suffixes; its Latin and Greek cousins are stella and aster, which supply the borrowed adjectives.","cn":"star 是英语本族的自由词根，接普通日耳曼后缀；它的拉丁与希腊表亲 stella、aster 提供借入的形容词。"},"latinIntro":{"en":"Latin stella supplies stellar, constellation and stellify; Greek aster supplies asterisk, asteroid and asterism. None of them derives from English star.","cn":"拉丁 stella 提供 stellar、constellation、stellify；希腊 aster 提供 asterisk、asteroid、asterism。它们都不是由英语 star 派生。"},"items":[{"word":"star","structure":"Old English steorra (native noun)","meaning":"a luminous point or body","meaningCN":"星；恒星","example":"The root is free and takes native suffixes.","exampleCN":"这个词根是自由的，可接本族后缀。"},{"word":"-y","structure":"-y (Old English adjective suffix)","meaning":"having the quality of","meaningCN":"具有……性质的","example":"Starry means full of stars.","exampleCN":"starry 意为满天星的。"},{"word":"-dom","structure":"-dom (Old English noun suffix)","meaning":"state or domain","meaningCN":"状态；领域","example":"Stardom is the state of being a star.","exampleCN":"stardom 是明星的身份状态。"},{"word":"-less","structure":"-less (Old English suffix)","meaning":"without","meaningCN":"没有……的","example":"A starless night has no visible stars.","exampleCN":"starless night 指看不见星的夜。"},{"word":"-ing","structure":"-ing (participial suffix)","meaning":"doing or being","meaningCN":"正在……的","example":"Starring names the leading performer.","exampleCN":"starring 指领衔主演。"},{"word":"stella","structure":"stella, stellae (Latin noun, first declension)","meaning":"star","meaningCN":"星","example":"A Latin cognate, not the source of star.","exampleCN":"这是拉丁同源词，不是 star 的来源。"},{"word":"aster","structure":"aster (Greek noun)","meaning":"star","meaningCN":"星","example":"Greek aster feeds asterisk and asteroid.","exampleCN":"希腊 aster 衍生 asterisk 与 asteroid。"},{"word":"constellation","structure":"com- + stella","meaning":"a gathering of stars","meaningCN":"星群；星座","example":"Latin built the noun from stella.","exampleCN":"拉丁语用 stella 造出这个名词。"}],"latinEntries":[{"word":"stella","structure":"stella, stellae (f., first declension)","meaning":"star","meaningCN":"星"},{"word":"astrum","structure":"astrum, astri (n., second declension; from Greek astron)","meaning":"star; heavenly body","meaningCN":"星；天体"}]}},{"word":"stellar","ipa_uk":"/ˈstelə/","ipa_us":"/ˈstelər/","definition_zh":"恒星的；星体的；极好的；明星级的；星形的","definition_en":"relating to stars, or (informally) outstanding and excellent","core_image":"一台望远镜对准一小片天区，屏幕上的光点被拆成温度、质量与年龄三条曲线","scene":"评价一场几乎无懈可击的演出，你说 Her performance was stellar.","sceneCN":"这里 stellar 是引申义「极好的、出色的」（第 3 个义项：由「恒星般明亮」转为对质量的评价）；句意为她的演出极为出色。图中可辨识物件：舞台、聚光灯、评分表、满格星标。","pos":[{"tag":"adj.","zh":"恒星的；星体的；（口语）极好的；星形的"}],"collocations":[{"phrase":"stellar evolution","zh":"恒星演化"},{"phrase":"stellar mass","zh":"恒星质量"},{"phrase":"a stellar performance","zh":"极为出色的演出"},{"phrase":"stellar wind","zh":"星风"},{"phrase":"a stellar cast","zh":"明星云集的阵容"},{"phrase":"stellar nursery","zh":"恒星诞生区"},{"phrase":"stellar parallax","zh":"恒星视差"}],"forms":[{"label":"比较级","form":"more stellar"},{"label":"最高级","form":"most stellar"},{"label":"名词（恒星；星）","form":"star"},{"label":"相关名词（星群）","form":"constellation"},{"label":"相关形容词（星形的）","form":"stellate"},{"label":"相关形容词（非恒星的）","form":"nonstellar"}],"derivatives":[{"word":"interstellar","pos":"adj.","zh":"inter- + stellar：星际的；前缀表「在……之间」"},{"word":"nonstellar","pos":"adj.","zh":"non- + stellar：非恒星的；前缀表否定"},{"word":"stellate","pos":"adj.","zh":"stella + -ate：星形的；后缀表「具有……形状」"},{"word":"stellarator","pos":"n.","zh":"-tor 表装置：仿星器，一种受控核聚变装置；词干取 stellar 的「恒星」义"}],"senses":[{"no":"01","title":"Of or relating to stars","titleCN":"与恒星有关的","definition":"relating to stars in general","definitionCN":"泛指与恒星有关的","example":"Stellar astronomy studies how stars are born and die.","exampleCN":"恒星天文学研究恒星如何诞生与死亡。","why":"stellar is simply the Latin adjective of stella, so its first duty is to stand beside any noun about stars.","whyCN":"stellar 就是 stella 的拉丁形容词，因此它的首要职责是为任何与恒星有关的名词作定语。"},{"no":"02","title":"Of a star's physical nature","titleCN":"恒星自身的物理性质与演化","definition":"describing the measurable properties of a star, such as its mass, temperature or evolutionary stage","definitionCN":"描述恒星可测的性质，如质量、温度或演化阶段","example":"Stellar mass decides how a star will end.","exampleCN":"恒星质量决定一颗恒星将如何终结。","why":"once astronomers could measure stars, the adjective attached itself to the quantities that define them.","whyCN":"当天文学家能测量恒星之后，这个形容词就附着在定义恒星的那些量上。"},{"no":"03","title":"Outstanding, excellent","titleCN":"极好的；出色的","definition":"extremely good; excellent, especially in performance or quality","definitionCN":"极好的；尤指表现或质量出色","example":"Her performance was stellar.","exampleCN":"她的演出极为出色。","why":"the praise sense is figurative: something stellar shines like a star compared with everything around it.","whyCN":"这层赞美义是比喻：某物与周围相比，亮得像一颗星。"},{"no":"04","title":"Of a star-studded cast","titleCN":"明星云集的；由明星组成的","definition":"featuring famous performers; used of a cast or lineup","definitionCN":"由著名表演者组成的；用于阵容","example":"The film drew a stellar cast of stage actors.","exampleCN":"这部影片召集了一批明星级的舞台演员。","why":"the sky image slides from real stars to stage stars, and the adjective follows the same path as the noun star.","whyCN":"天空的意象从真星滑向舞台明星，形容词与名词 star 走的是同一条路。"},{"no":"05","title":"Star-shaped","titleCN":"星形的；放射状的","definition":"shaped like a star, with radiating points, as some hairs or crystals","definitionCN":"形状像星、带放射状尖角的，如某些毛发或晶体","example":"The leaf surface is covered with stellar hairs.","exampleCN":"叶面覆盖着星状毛。","why":"this sense keeps the oldest visual meaning of stella, the drawn or natural shape with rays.","whyCN":"这个义项保留了 stella 最古老的视觉含义：带放射线的画成或天然形状。"},{"no":"06","title":"Of a star's emitted material","titleCN":"恒星喷出的物质与辐射","definition":"describing matter or radiation flowing out from a star, as in stellar wind","definitionCN":"描述从恒星流出的物质或辐射，如星风","example":"The stellar wind strips the planet of its atmosphere.","exampleCN":"星风把行星的大气剥走。","why":"wind and radiation are properties of the star in action, so the adjective marks them as coming from the star rather than from elsewhere.","whyCN":"风与辐射是恒星在活动时的表现，因此这个形容词标明它们来自恒星而非别处。"},{"no":"07","title":"Of a star-forming region","titleCN":"恒星诞生区的","definition":"describing the clouds and regions where new stars are forming","definitionCN":"描述正在形成新恒星的云气与区域","example":"Dust hides the young stars inside the stellar nursery.","exampleCN":"尘埃遮住了恒星育婴室里年轻的恒星。","why":"a nursery is where new lives begin, so astronomers borrowed the domestic word and kept the adjective to mark what is being born.","whyCN":"育婴室是新生命开始之处，天文学家借来这个日常词，并保留形容词以标明诞生的是恒星。"},{"no":"08","title":"Radiant, shining (literary)","titleCN":"文学用法：光辉四射的","definition":"shining or radiant in a literary description, often of light or a smile","definitionCN":"文学描写中光辉四射的，常用于光或笑容","example":"A stellar glow filled the hall as the lamps were lit.","exampleCN":"灯点亮时，一片星光般的光辉充满大厅。","why":"the literal shine and the figurative praise meet here: what shines is praised for shining.","whyCN":"字面的「发光」与比喻的「赞美」在此会合：发光者因发光而被称赞。"}],"etymology":{"intro":{"en":"Stellar is Latin stellaris 'of stars', built on stella 'star' with the adjective suffix -aris. It entered English as an astronomical adjective and later acquired a colloquial sense of excellence. Dates are approximate.","cn":"stellar 是拉丁 stellaris「恒星的」，由 stella「星」加形容词后缀 -aris 构成。它作为天文学形容词进入英语，后来又获得「出色」的口语义。年代均为约数。"},"items":[{"era":"LATIN STELLA","en":"Stella 'star' is the Latin noun, a cognate of English star and Greek aster rather than their source; all go back to a reconstructed Indo-European root.","cn":"stella 是拉丁语「星」，与英语 star、希腊 aster 属同源，而非它们的来源；三者都出自一个印欧重构词根。"},{"era":"LATIN STELLARIS","en":"Stella plus -aris produced stellaris 'of stars', the ordinary adjective used with such nouns as stellarum motus 'motion of the stars'.","cn":"stella 加 -aris 构成 stellaris「恒星的」，是与「星的运动」等短语搭配的普通形容词。"},{"era":"ENGLISH STELLAR","en":"The adjective is generally believed to have entered English astronomical writing in the seventeenth century, alongside other Latin scientific adjectives.","cn":"一般认为，这个形容词在 17 世纪随其他拉丁科学形容词一起进入英语天文写作。"},{"era":"THE PRAISE SENSE","en":"The informal sense 'outstanding' is nineteenth-century and later; it extends the literal shine of a star to any performance that seems to outshine its surroundings.","cn":"「出色」的口语义出现于 19 世纪及以后；它把恒星字面的光亮扩展到任何看似盖过周围的表现。"},{"era":"THE BOTANICAL SENSE","en":"The star-shaped sense is also nineteenth-century, when descriptive botany borrowed stellar for radiating hairs and crystals.","cn":"星形义同样出现于 19 世纪，当时描述性植物学借 stellar 指放射状的毛与晶体。"},{"era":"UNCERTAIN DETAILS","en":"Root uncertainty: the Indo-European form behind stella is a reconstruction. First-date uncertainty only: the earliest use of the praise sense is not exactly dated and is usually placed in the nineteenth century.","cn":"词根存疑：stella 背后的印欧形式属重构。仅首见年代存疑：赞美义的最早用例没有确切年代，通常定在 19 世纪。"}]},"similar":{"note":{"en":"Group one holds adjectives and nouns of the same star stock that are easily confused; group two holds the ordinary words that compete with the praise sense.","cn":"第一组是同出「星」词干、容易混淆的形容词与名词；第二组是与「出色」义竞争的普通词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"stellate","ipa":"/ˈstelət/","tag":"star-shaped","definition":"From Latin stellatus 'set with stars', it means shaped like a star and is used in botany; it does not mean 'of stars'.","definitionCN":"出自拉丁 stellatus「布满星」，意为星形的，用于植物学；它不表示「恒星的」。"},{"word":"interstellar","ipa":"/ˌɪntəˈstelə/","tag":"between stars","definition":"Inter- 'between' plus stellar: it names the space or matter between stars, not a quality of a single star.","definitionCN":"inter-「在……之间」加 stellar：指恒星之间的空间或物质，而非单颗恒星的性质。"},{"word":"star","ipa":"/stɑː/","tag":"the noun","definition":"The noun names the body itself; stellar is only the adjective, so a sentence needs star where a thing is meant.","definitionCN":"名词指天体本身；stellar 只是形容词，指「东西」时须用 star。"}]},{"heading":"NEAR MEANING","entries":[{"word":"excellent","ipa":"/ɪkˈselənt/","tag":"plain strong praise","definition":"The neutral, everyday word for very good; stellar is informal and adds the image of shining.","definitionCN":"中性、日常的「很好」；stellar 属口语并多了「发光」的意象。"},{"word":"outstanding","ipa":"/ˌaʊtˈstændɪŋ/","tag":"standing out from the rest","definition":"Praise for being clearly above others; it stresses comparison, while stellar stresses brightness.","definitionCN":"赞扬明显高于其余；它强调比较，而 stellar 强调光亮。"},{"word":"astral","ipa":"/ˈæstrəl/","tag":"of the stars, often occult","definition":"From Greek astron 'star'; it belongs to astrology and esoteric writing, where stellar belongs to physics and praise.","definitionCN":"出自希腊 astron「星」；多用于占星与秘学文本，而 stellar 用于物理与赞美。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"stella 'star' + -ar 'of': of a star.","cn":"stella「星」+ -ar「……的」：星的。"},{"en":"Physics collocations: stellar mass, stellar wind, stellar evolution.","cn":"物理搭配：恒星质量、星风、恒星演化。"},{"en":"Praise collocations: a stellar performance, a stellar cast.","cn":"赞美搭配：出色的演出、明星阵容。"},{"en":"The same stock gives constellation and interstellar.","cn":"同一词干还给出 constellation 与 interstellar。"},{"en":"Stellate means star-shaped, not of stars.","cn":"stellate 意为星形，不是「恒星的」。"}],"abstract":[{"en":"Picture a single lamp so bright that everything else in the room looks grey.","cn":"想象一盏灯亮到房间里其他东西都显得灰暗。"},{"en":"Picture a scoreboard where one name is printed larger than the rest.","cn":"想象一块记分牌，其中一个名字印得比别的大。"},{"en":"Picture a crystal cut into rays around a centre.","cn":"想象一块晶体围绕中心被切成放射状。"}]},"examples":[{"en":"Stellar evolution depends on how much gas the cloud contains.","cn":"恒星演化取决于云气含有多少物质。"},{"en":"The orchestra gave a stellar performance on opening night.","cn":"乐团在首演夜献上极为出色的演出。"},{"en":"Stellar parallax is the tiny shift seen as the earth moves.","cn":"恒星视差是地球移动时看到的微小位移。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「stellar」听着像「是他了」——全场最亮的那颗星「是他了」 → 恒星的；出色的","word":"stellar"},"root":"拉丁 stella「星」+ -aris「……的」→ stellaris「恒星的」；stella 与英语 star、希腊 aster 同源，印欧词根属重构形式；「出色」义一般认为始于 19 世纪。","sensesIntro":{"en":"Eight senses follow one adjective: the literal 'of a star' is applied to a star's physics, its wind, its nursery and its shape, and then the same brightness is borrowed for a great performance, a famous cast and even a literary glow.","cn":"八个义项沿一个形容词展开：字面的「恒星的」依次用于恒星的物理、星风、育婴区与形状；随后同样的「亮」被借去形容出色的演出、明星阵容，乃至文学描写中的光辉。"},"semanticMap":{"core":{"en":"CORE IMAGE: one lamp so bright that the rest of the room falls into grey.","cn":"核心意象：一盏灯亮到房间里其余一切都落进灰色。"},"chain":["OF A STAR","STAR'S PHYSICS","STAR'S OUTFLOW","STAR'S BIRTHPLACE","STAR-SHAPED","SHINING EXCELLENCE"],"branches":[{"senses":"S1","en":"THE PLAIN ADJECTIVE: it belongs to any noun about stars.","cn":"普通定语：可与任何关于恒星的名词搭配。"},{"senses":"S2 · S6 · S7","en":"THE STAR AT WORK: what it is made of, what it blows out, where it is born.","cn":"工作中的恒星：由什么构成、吹出什么、在哪里诞生。"},{"senses":"S5","en":"THE DRAWN SHAPE: rays around a centre, not a body in space.","cn":"画出的形状：围绕中心的射线，而非天上的天体。"},{"senses":"S3","en":"PRAISE: a performance that outshines its surroundings.","cn":"赞美：盖过周围的表现。"},{"senses":"S4 · S8","en":"BORROWED BRIGHTNESS: famous faces and literary glow.","cn":"借来的光：明星面孔与文学中的光辉。"}]},"affixes":{"intro":{"en":"Stellar is a Latin root plus adjective suffix; the root also builds several nouns and verbs through the same stella.","cn":"stellar 是拉丁词根加形容词后缀；这个词根还经同一个 stella 构成若干名词与动词。"},"latinIntro":{"en":"Latin stella gives stellar, stellate, constellation and stellify; Greek aster gives astral and asteroid, a parallel family rather than the same one.","cn":"拉丁 stella 给出 stellar、stellate、constellation、stellify；希腊 aster 给出 astral 与 asteroid，是并行词族而非同一族。"},"items":[{"word":"stella","structure":"stella, stellae (Latin noun, first declension)","meaning":"star","meaningCN":"星","example":"Stella is a cognate, not the source, of English star.","exampleCN":"stella 是英语 star 的同源词，不是来源。"},{"word":"-ar","structure":"-aris (Latin adjective suffix)","meaning":"of or belonging to","meaningCN":"……的；属于……的","example":"Stellaris is stella plus this suffix.","exampleCN":"stellaris 就是 stella 加这个后缀。"},{"word":"stellar","structure":"stella + -aris","meaning":"of stars","meaningCN":"恒星的","example":"The adjective entered English through scientific Latin.","exampleCN":"这个形容词经科学拉丁语进入英语。"},{"word":"stellate","structure":"stella + -atus (provided with)","meaning":"star-shaped","meaningCN":"星形的","example":"Botany uses it for radiating hairs.","exampleCN":"植物学用它指放射状毛。"},{"word":"constellation","structure":"com- 'together' + stella","meaning":"a gathering of stars","meaningCN":"星群；星座","example":"The noun names a group, not a quality.","exampleCN":"这个名词指一群，而非一种性质。"},{"word":"interstellar","structure":"inter- 'between' + stellar","meaning":"between stars","meaningCN":"星际的","example":"It names the space between stars.","exampleCN":"它指恒星之间的空间。"},{"word":"nonstellar","structure":"non- 'not' + stellar","meaning":"not of stars","meaningCN":"非恒星的","example":"The prefix reverses the adjective.","exampleCN":"这个前缀反转了形容词。"},{"word":"stellify","structure":"stella + -fy (to make)","meaning":"to turn into a star","meaningCN":"使变成星","example":"Rare, but built on the same root.","exampleCN":"罕见，但同出这一词根。"},{"word":"stellarator","structure":"stellar + -ator (device)","meaning":"a fusion device","meaningCN":"仿星器","example":"The device is named for the stellar plasma it mimics.","exampleCN":"这种装置因模仿恒星等离子体而得名。"}],"latinEntries":[{"word":"stella","structure":"stella, stellae (f., first declension)","meaning":"star","meaningCN":"星"},{"word":"stellaris","structure":"stellaris, stellare (adjective, third declension)","meaning":"of the stars","meaningCN":"恒星的"},{"word":"stellatus","structure":"stellatus, stellata, stellatum (adjective)","meaning":"set with stars; star-shaped","meaningCN":"布满星的；星形的"}]}},{"word":"constellation","ipa_uk":"/kənˈsteləʃn/","ipa_us":"/kənˈsteləʃn/","definition_zh":"星座；星群；（相关的）一组事物；群星般的一批人物；卫星星座","definition_en":"a group of stars forming a recognized pattern, or a group of related things or people","core_image":"几张亮星之间被想象出的细线连起来，夜空上浮出一幅猎人的轮廓","scene":"夜里辨认天上连成图案的一组星，你说 Those seven bright points form a constellation.","sceneCN":"这里 constellation 指「被认作一个图案的一组星」（第 1 个义项：肉眼连成的星群图形）；句意为那七个亮点构成一个星座。图中可辨识物件：七颗亮星、连线的想象轮廓、星图、指星的手。","pos":[{"tag":"n.","zh":"星座；星群；一组相关事物；一批人物；卫星星座"}],"collocations":[{"phrase":"the constellation Orion","zh":"猎户座"},{"phrase":"a constellation of symptoms","zh":"一组症状"},{"phrase":"a constellation of talent","zh":"一批人才"},{"phrase":"satellite constellation","zh":"卫星星座"},{"phrase":"map a constellation","zh":"绘制星座图"},{"phrase":"the constellation of Cassiopeia","zh":"仙后座"}],"forms":[{"label":"复数","form":"constellations"},{"label":"相关动词（使聚成星群，少用）","form":"constellate"},{"label":"相关形容词（恒星的）","form":"stellar"},{"label":"相关天文术语（星群）","form":"asterism"},{"label":"相关术语（黄道十二宫）","form":"zodiac"},{"label":"相关复合词（卫星星座）","form":"satellite constellation"}],"derivatives":[{"word":"constellate","pos":"v.","zh":"constellation 同出拉丁 constellare：使聚成星群；非由本词加后缀，而是同一词族的动词"},{"word":"constellatory","pos":"adj.","zh":"constellation + -ory：星座的（罕用）"},{"word":"stellar","pos":"adj.","zh":"stella + -ar：恒星的；与本词共享 stella 词根"},{"word":"asterism","pos":"n.","zh":"希腊 aster + -ism：较小的星群图形；与本词并列的天文术语"}],"senses":[{"no":"01","title":"A pattern of stars","titleCN":"天上被认作一个图案的一组星","definition":"a group of stars that observers join into a recognizable pattern","definitionCN":"观测者连成一个可辨认图案的一组恒星","example":"Those seven bright points form a constellation.","exampleCN":"那七个亮点构成一个星座。","why":"the word is built from com- 'together' and stella 'star', so its plain sense is simply stars gathered into one figure.","whyCN":"这个词由 com-「共同」与 stella「星」构成，本义就是被聚成同一个图形的一群星。"},{"no":"02","title":"A bounded region of the sky","titleCN":"天文学上划定的天区","definition":"one of the eighty-eight regions into which modern astronomy divides the whole sky","definitionCN":"现代天文学把全天划成的八十八个区域之一","example":"Every star lies inside exactly one constellation.","exampleCN":"每颗恒星都恰好落在一个星座的边界内。","why":"once star charts needed unambiguous addresses, the drawn figure was replaced by a region with borders, and the old word kept the new job.","whyCN":"当星图需要没有歧义的地址时，画出的图形被换成有边界的区域，旧词承担了新任务。"},{"no":"03","title":"A sign of the zodiac","titleCN":"黄道十二宫中的一个宫","definition":"one of the twelve traditional star groups through which the sun appears to pass","definitionCN":"太阳视运动所经的十二个传统星群之一","example":"In astrology a constellation names a sign, not a region.","exampleCN":"在占星里，constellation 指一个宫，而非天区。","why":"astrology froze twelve of the old figures into a system of signs, so the word carries a second, non-astronomical sense.","whyCN":"占星把其中十二个旧图形冻结成宫位体系，因此这个词带有第二个非天文的义项。"},{"no":"04","title":"A group of related things","titleCN":"一组彼此关联的事物（如症状）","definition":"a set of related things that appear together, such as symptoms or factors","definitionCN":"一同出现的一组相关事物，如症状或因素","example":"The doctor recognized a constellation of symptoms.","exampleCN":"医生认出这是一组相关症状。","why":"the sky image is reused whenever separate items are seen as one figure, because the mind joins them the way it joins stars.","whyCN":"只要彼此分开的事物被看成一个图形，这个天空意象就会被重用，因为心智连线的方式与连星一样。"},{"no":"05","title":"A gathering of eminent people","titleCN":"一批杰出人物","definition":"a group of famous or talented people gathered in one place or field","definitionCN":"聚集在同一场合或领域的一批有名或才华出众的人","example":"The gala drew a constellation of scientists.","exampleCN":"这场盛会聚集了一批科学家。","why":"the metaphor is social: a room full of distinguished people looks like a sky full of bright stars.","whyCN":"这是社交比喻：一屋子显赫的人物，看起来就像满天亮星。"},{"no":"06","title":"A network of satellites","titleCN":"卫星星座：一组协同工作的卫星","definition":"a group of satellites working together in coordinated orbits","definitionCN":"在协调轨道上协同工作的一组卫星","example":"A low-orbit constellation can cover the whole planet.","exampleCN":"低轨卫星星座可以覆盖整个行星。","why":"engineers borrowed the word because the satellites, like stars, are many separate points that only make sense as one pattern.","whyCN":"工程师借用这个词，因为卫星正如星星：许多分开的点，只有作为一个图形才有意义。"},{"no":"07","title":"The naming grid of the sky","titleCN":"天文命名法：星座名作恒星名的属格部分","definition":"the naming system in which a star is labelled by a letter or number plus the genitive of its constellation","definitionCN":"用一个字母或数字加星座名的属格来标记恒星的命名体系","example":"Alpha Centauri is the brightest star of the constellation Centaurus.","exampleCN":"南门二是半人马座中最亮的星。","why":"because a star needed an address before it had a name, the constellation became the surname in the label.","whyCN":"因为恒星在有名之前先需要一个地址，星座就成了标签里的姓。"},{"no":"08","title":"A fixed configuration of circumstances","titleCN":"比喻义：一组固定的因素组合","definition":"a particular arrangement of circumstances or forces seen as a single pattern","definitionCN":"被视为一个整体图形的一组境况或力量","example":"A rare constellation of interests made the treaty possible.","exampleCN":"各种利益罕见地凑成一种组合，使条约成为可能。","why":"the abstract sense generalizes the visual one: any set of elements that only works when arranged together is a constellation.","whyCN":"抽象义把视觉义一般化：任何只有在这样排列时才成立的一组要素，都是一个星座。"}],"etymology":{"intro":{"en":"Constellation comes from Late Latin constellatio 'a gathering of stars', built on com- 'together' and stella 'star'. It reached English through Old French and later split into an astronomical and an astrological sense. Dates are approximate.","cn":"constellation 出自晚期拉丁 constellatio「聚在一起的星」，由 com-「共同」与 stella「星」构成。它经古法语进入英语，后来分成天文学与占星两个义项。年代均为约数。"},"items":[{"era":"LATIN STELLA","en":"Stella 'star' is the Latin noun behind the whole family; it is a cognate of English star, not its source, and both go back to a reconstructed Indo-European root.","cn":"stella 是「星」的拉丁名词，是整个词族的根基；它与英语 star 同源而非其来源，两者都出自一个印欧重构词根。"},{"era":"LATIN COM-","en":"The prefix com- 'together, with' turns a single star into a set of stars seen as one thing.","cn":"前缀 com-「共同、一起」把单颗星变成被看成一体的一个星集。"},{"era":"LATE LATIN CONSTELLATIO","en":"Constellatio named a set of stars, and the related adjective constellatus 'set with stars' shows the same image of stars studding a field.","cn":"constellatio 指一组星，相关形容词 constellatus「布满星的」显示同一意象：星点布满一片区域。"},{"era":"OLD FRENCH AND ENGLISH","en":"Old French constellation carried the noun into English in the thirteenth century, when it still covered both the pattern and its astrological use.","cn":"古法语 constellation 在 13 世纪把这个名词带进英语，当时它同时涵盖图形与占星用途。"},{"era":"THE MODERN BOUNDARIES","en":"In 1922 the International Astronomical Union adopted a list of eighty-eight constellations, and in 1930 formal boundaries were published, turning figures into regions.","cn":"1922 年国际天文联合会通过八十八个星座的名单，1930 年公布了正式边界，把图形变成了区域。"},{"era":"UNCERTAIN DETAILS","en":"Root uncertainty: the derivation through a hypothetical verb constellare is generally believed but that verb is sparsely attested, so the intermediate step is a reconstruction. First-date uncertainty only: the earliest English use of the noun is not precisely dated.","cn":"词根存疑：经假想动词 constellare 的派生一般认为成立，但该动词书证稀少，因此中间环节属重构。仅首见年代存疑：这个名词最早的英语用例没有确切年代。"}]},"similar":{"note":{"en":"Group one holds the sky terms most often confused with constellation; group two holds the borrowed uses for groups of things and people.","cn":"第一组是最容易与 constellation 混淆的天空术语；第二组是借用来说「一组事物、一批人」的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"asterism","ipa":"/ˈæstərɪzəm/","tag":"a smaller star pattern","definition":"A recognized pattern that is not one of the eighty-eight official regions, such as the Big Dipper; astronomers keep the two terms apart.","definitionCN":"不属于八十八个正式区域的可辨图形，如北斗七星；天文学家把这两个词分开用。"},{"word":"galaxy","ipa":"/ˈɡæləksi/","tag":"a system of stars","definition":"Greek gala 'milk' gave the name of our own star system; a galaxy contains many constellations, so the words work at different scales.","definitionCN":"希腊 gala「奶」给出我们所在星系的名称；一个星系包含许多星座，两词尺度不同。"},{"word":"zodiac","ipa":"/ˈzəʊdiæk/","tag":"the ring of twelve signs","definition":"The belt of twelve traditional signs; it is a system built from constellations, not a synonym for one of them.","definitionCN":"十二个传统宫位构成的带；它是由星座构成的体系，并非某一个星座的同义词。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cluster","ipa":"/ˈklʌstə/","tag":"a group close together","definition":"A general word for things grouped closely; it says nothing about a pattern, which is what constellation adds.","definitionCN":"泛指聚在一起的一组；它不含「图案」之意，而这正是 constellation 增添的。"},{"word":"assemblage","ipa":"/əˈsemblɪdʒ/","tag":"a collected set","definition":"A formal word for a collection of items; constellation is more figurative and suggests the items form a figure.","definitionCN":"指收集成组之物的正式用语；constellation 更偏比喻，暗示这些事物构成一个图形。"},{"word":"array","ipa":"/əˈreɪ/","tag":"an ordered display","definition":"A set arranged for a purpose, as in an array of sensors; it stresses arrangement, not the picture the arrangement makes.","definitionCN":"为某一目的排布的一组，如传感器阵列；它强调排列，而非排列造成的图像。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"com- 'together' + stella 'star': stars gathered into one figure.","cn":"com-「共同」+ stella「星」：被聚成一个图形的星。"},{"en":"Modern astronomy counts eighty-eight constellations.","cn":"现代天文学把全天划成八十八个星座。"},{"en":"A star's label uses the constellation as a surname: Alpha Centauri.","cn":"恒星的名字把星座当姓：南门二。"},{"en":"Borrowed collocations: a constellation of symptoms, of talent.","cn":"借用搭配：一组症状、一批人才。"},{"en":"The family runs stellar, constellate, asterism.","cn":"同族词包括 stellar、constellate、asterism。"}],"abstract":[{"en":"Picture separate lamps in a dark room joined by an imaginary line.","cn":"想象暗室里几盏分开的灯被一条想象中的线连起来。"},{"en":"Picture a party where every guest is a small light and the room becomes a sky.","cn":"想象一场聚会，每位客人都是一个小光点，房间成了天空。"},{"en":"Picture a map with borders drawn around a shape that used to be just a picture.","cn":"想象一张地图，围绕一个原本只是图形的轮廓画上了边界。"}]},"examples":[{"en":"The constellation Orion is visible on winter evenings.","cn":"猎户座在冬季夜晚可见。"},{"en":"Doctors look for a constellation of signs before diagnosing.","cn":"医生在确诊前会寻找一组相关体征。"},{"en":"The company plans a constellation of small satellites.","cn":"该公司计划建一个小卫星星座。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「con（共同）+ stell（星）+ ation」——许多星被聚在一起 → 星座；引申为一组相关事物","word":"constellation"},"root":"晚期拉丁 constellatio「聚在一起的星」= com-「共同」+ stella「星」+ -atio（名词后缀）；stella 与英语 star、希腊 aster 同源。经古法语进入英语。","sensesIntro":{"en":"Eight senses follow one act of joining: separate stars are drawn into a figure, that figure becomes a bounded region, a sign, a set of symptoms, a crowd of notables, a satellite network, a naming grid and finally any arrangement of circumstances.","cn":"八个义项沿同一个「连合」动作展开：分开的星被连成一个图形；这个图形再变成有边界的区域、一个宫、一组症状、一批名人、一张卫星网、一套命名格，最后变成任何境况的组合。"},"semanticMap":{"core":{"en":"CORE IMAGE: bright points joined by imagined lines until a figure appears in the sky.","cn":"核心意象：亮着的点被想象中的线连起来，天空浮出一个图形。"},"chain":["STARS JOINED","SKY REGION","ZODIAC SIGN","SET OF THINGS","CROWD OF NOTABLES","ORBITING NETWORK"],"branches":[{"senses":"S1 · S7","en":"THE FIGURE AND ITS USE AS A NAME: the pattern, and the surname it gives to stars.","cn":"图形及其命名用途：图案本身，以及它给恒星的姓。"},{"senses":"S2 · S3","en":"TWO OFFICIAL SYSTEMS: the bordered region of astronomy and the sign of astrology.","cn":"两套正式体系：天文的有界区域与占星的宫。"},{"senses":"S4 · S8","en":"A SET SEEN AS ONE: symptoms, interests, any arrangement that only works together.","cn":"被看成一体的集合：症状、利益，任何只有凑在一起才成立的排列。"},{"senses":"S5","en":"THE SOCIAL SKY: a room of distinguished people read as stars.","cn":"社交的天空：一屋子显赫人物被读成星星。"},{"senses":"S6","en":"THE ENGINEERED SKY: satellites coordinated into one pattern.","cn":"工程化的天空：卫星被协调成一个图形。"}]},"affixes":{"intro":{"en":"Constellation is a Latin compound of a prefix, a star root and a noun suffix; each piece is still productive in English.","cn":"constellation 是拉丁复合词，由前缀、星词根与名词后缀构成；每一部分在英语中仍有构词力。"},"latinIntro":{"en":"Latin stella also gives stellar and constellate, while Greek aster supplies the parallel set asterisk, asteroid and asterism.","cn":"拉丁 stella 还给出 stellar 与 constellate，而希腊 aster 提供平行的一组：asterisk、asteroid、asterism。"},"items":[{"word":"com-","structure":"com- (Latin prefix)","meaning":"together, with","meaningCN":"共同；一起","example":"The prefix gathers the stars into one set.","exampleCN":"这个前缀把星聚成一组。"},{"word":"stella","structure":"stella, stellae (Latin noun, first declension)","meaning":"star","meaningCN":"星","example":"The root is shared with stellar.","exampleCN":"这个词根与 stellar 共享。"},{"word":"-ation","structure":"-atio, -ationis (Latin noun suffix)","meaning":"action or result","meaningCN":"动作或结果","example":"Constellatio is the result of being set with stars.","exampleCN":"constellatio 指被布满星之后的状态。"},{"word":"constellatio","structure":"com- + stella + -atio","meaning":"a gathering of stars","meaningCN":"聚在一起的星","example":"Late Latin formed the noun.","exampleCN":"晚期拉丁语造出这个名词。"},{"word":"constellation","structure":"constellatio (Latin) through Old French","meaning":"a star pattern","meaningCN":"星座","example":"English keeps the Latin shape almost unchanged.","exampleCN":"英语几乎原样保留了拉丁词形。"},{"word":"constellate","structure":"constellare (Latin verb)","meaning":"to set with stars; to gather","meaningCN":"使布满星；使聚集","example":"Rare in English but alive in the family.","exampleCN":"英语中罕见，但词族仍在。"},{"word":"stellar","structure":"stella + -aris","meaning":"of stars","meaningCN":"恒星的","example":"Same root, different suffix.","exampleCN":"同一词根，不同后缀。"},{"word":"asterism","structure":"aster (Greek) + -ism","meaning":"a small star pattern","meaningCN":"星群；星状图形","example":"Greek aster is a cousin, not a parent.","exampleCN":"希腊 aster 是表亲，不是父母。"},{"word":"satellite","structure":"satelles (Latin) + -ite","meaning":"an attendant body","meaningCN":"卫星","example":"The modern compound satellite constellation uses the borrowed sense.","exampleCN":"现代复合词 satellite constellation 用的正是这层借义。"}],"latinEntries":[{"word":"stella","structure":"stella, stellae (f., first declension)","meaning":"star","meaningCN":"星"},{"word":"constellatio","structure":"constellatio, constellationis (f., third declension)","meaning":"a gathering of stars","meaningCN":"聚在一起的星"},{"word":"constellatus","structure":"constellatus, constellata, constellatum (adjective)","meaning":"set with stars","meaningCN":"布满星的"}]}},{"word":"nebula","ipa_uk":"/ˈnebjələ/","ipa_us":"/ˈnebjələ/","definition_zh":"星云；（星际的）气体尘埃云；旧时也指任何模糊的云雾状天体","definition_en":"a cloud of gas and dust in interstellar space, or historically any fuzzy patch in the sky","core_image":"望远镜里一团发着淡红与青色的雾，星点像被纱布隔在后面","scene":"在望远镜里看到一团发光的雾，你说 That nebula is lit by a young star.","sceneCN":"这里 nebula 指「星际空间中的气体尘埃云」（第 2 个义项：被附近年轻恒星电离而发光的发射星云）；句意为那团星云被一颗年轻恒星照亮。图中可辨识物件：望远镜、淡红与青色的云气、藏在雾后的星点、目镜。","pos":[{"tag":"n.","zh":"星云；气体尘埃云（复数 nebulae 或 nebulas）"}],"collocations":[{"phrase":"emission nebula","zh":"发射星云"},{"phrase":"reflection nebula","zh":"反射星云"},{"phrase":"planetary nebula","zh":"行星状星云"},{"phrase":"dark nebula","zh":"暗星云"},{"phrase":"the Orion Nebula","zh":"猎户座大星云"},{"phrase":"a cloud of nebula","zh":"一团星云"}],"forms":[{"label":"复数（拉丁式）","form":"nebulae"},{"label":"复数（英语式）","form":"nebulas"},{"label":"相关形容词","form":"nebular"},{"label":"相关形容词（云雾状的）","form":"nebulous"},{"label":"相关名词（云雾状）","form":"nebulosity"},{"label":"相关天象（超新星遗迹）","form":"supernova remnant"}],"derivatives":[{"word":"nebulous","pos":"adj.","zh":"nebula + -ous：云雾状的；后转指模糊不清的"},{"word":"nebulosity","pos":"n.","zh":"nebulous + -ity：云雾状；模糊"},{"word":"nebular","pos":"adj.","zh":"nebula + -ar：星云的；如「星云假说」这一旧理论所用的形容词"},{"word":"nebulose","pos":"adj.","zh":"nebula + -ose：云雾状的（少用）"}],"senses":[{"no":"01","title":"A cloud between the stars","titleCN":"星际空间中的气体尘埃云","definition":"a cloud of gas and dust occupying space between stars","definitionCN":"占据恒星之间空间的气体与尘埃云","example":"A cold nebula can hold enough gas to make thousands of stars.","exampleCN":"一团冷星云所含的气体足以造出成千上万颗恒星。","why":"Latin nebula meant 'mist, cloud', and astronomy applied the word to the cloudy patches that would not resolve into points.","whyCN":"拉丁 nebula 意为「雾、云」，天文学把这个词用于那些无法分解成星点的雾状斑块。"},{"no":"02","title":"A nebula glowing by ionization","titleCN":"被电离而自身发光的发射星云","definition":"a cloud that shines because nearby young stars ionize its gas","definitionCN":"因附近年轻恒星把气体电离而发光的云","example":"That nebula is lit by a young star.","exampleCN":"那团星云被一颗年轻恒星照亮。","why":"the glow is not reflected light but the gas itself answering the star's ultraviolet radiation, which is why this type is called emission.","whyCN":"这光不是反射来的，而是气体本身回应恒星的紫外辐射，因此这一类叫发射星云。"},{"no":"03","title":"A nebula shining by reflected light","titleCN":"靠反射邻近星光而发亮的反射星云","definition":"a cloud that shines only because dust in it reflects the light of nearby stars","definitionCN":"仅因内部尘埃反射附近星光而发亮的云","example":"The reflection nebula looks blue because dust scatters short wavelengths.","exampleCN":"反射星云呈蓝色，因为尘埃散射短波。","why":"reflection names the mechanism: the cloud has no energy of its own and merely returns borrowed light.","whyCN":"reflection 标出机制：这团云没有自己的能量，只是把借来的光送回来。"},{"no":"04","title":"A shell shed by a dying star","titleCN":"死亡恒星抛出的壳层：行星状星云","definition":"the expanding shell of gas thrown off by a low-mass star near the end of its life","definitionCN":"低质量恒星临近死亡时抛出的膨胀气体壳","example":"A planetary nebula has nothing to do with planets.","exampleCN":"行星状星云与行星毫无关系。","why":"the name is a historical mistake: early telescopes showed a round disc like a planet, and the misleading label stuck.","whyCN":"这个名字是历史误会：早期望远镜看到的圆盘像行星，这个误导性的名称就此留下。"},{"no":"05","title":"A dark cloud blocking the light","titleCN":"遮住背后星光的暗星云","definition":"a dense cloud that absorbs light and appears as a dark patch against a brighter background","definitionCN":"吸收光线、在更亮背景上呈现为暗斑的浓密云","example":"The dark nebula cut a lane through the Milky Way.","exampleCN":"暗星云在银河中划出一条暗带。","why":"a dark nebula is seen by absence: dust hides the stars behind it, so the cloud is visible as a hole in the light.","whyCN":"暗星云靠「缺席」而被看见：尘埃遮住后面的星，于是云表现为光中的一个洞。"},{"no":"06","title":"Debris of an exploded star","titleCN":"爆炸恒星留下的膨胀碎片：超新星遗迹","definition":"the expanding debris and shock-heated gas left by a supernova","definitionCN":"超新星爆发后留下的膨胀碎片与被冲击波加热的气体","example":"The Crab Nebula is the remnant of a star seen to explode in 1054.","exampleCN":"蟹状星云是一颗在 1054 年被看到爆发的恒星留下的遗迹。","why":"the same word covers the cloud that the explosion leaves behind, because it too is a fuzzy patch before it is understood.","whyCN":"同一个词也覆盖爆炸留下的云，因为它在被理解之前同样只是一团模糊的斑。"},{"no":"07","title":"A cloudy spot in old medicine","titleCN":"旧医学中的「云雾」：眼或尿的浑浊","definition":"a historical medical use for a cloudy spot in the eye or a cloudy specimen","definitionCN":"旧医学中指眼内或标本中的浑浊斑点","example":"Old medical texts described a nebula on the cornea.","exampleCN":"旧医学文献描述角膜上有一处云雾状浑浊。","why":"the medical sense is the literal Latin sense surviving in technical prose: any small cloud, including one inside the body.","whyCN":"医学义是拉丁本义在技术文献中的延续：任何小片云状物，包括体内的。"},{"no":"08","title":"Figurative: a haze of vagueness","titleCN":"比喻义：模糊不清的一团","definition":"a literary or figurative use for something vague and unformed, like a haze","definitionCN":"文学或比喻用法，指模糊、未成形、如雾一般的事物","example":"The plan remained a nebula of intentions.","exampleCN":"这个计划仍是一团模糊的意图。","why":"the abstract sense keeps the original mist: what is nebular cannot be focused into separate points.","whyCN":"抽象义保留了本义的「雾」：星云状的东西无法对焦成一个个分开的点。"}],"etymology":{"intro":{"en":"Nebula is Latin for 'mist, cloud', a diminutive of an older cloud word; astronomy borrowed it for fuzzy sky patches in the seventeenth century. Dates are approximate.","cn":"nebula 是拉丁语「雾、云」，是更早的云字眼的指小形式；天文学在 17 世纪借它指天空中模糊的斑块。年代均为约数。"},"items":[{"era":"LATIN NEBULA","en":"Nebula meant 'mist, fog, cloud', and also named a cloudy spot in the eye or in a liquid; the diminutive suffix -ula gives the sense of a small cloud.","cn":"nebula 意为「雾、云」，也指眼内或液体中的浑浊斑点；指小后缀 -ula 给出「小片云」的意思。"},{"era":"GREEK AND INDO-EUROPEAN KIN","en":"Greek nephele 'cloud' is a cognate; both point to a reconstructed Indo-European root for cloud or mist, a reconstruction rather than an attested form.","cn":"希腊 nephele「云」是同源词；两者都指向一个表示云或雾的印欧重构词根，那是重构而非有书证的形式。"},{"era":"THE ASTRONOMICAL USE","en":"From the seventeenth century nebula was applied to any fuzzy patch that a telescope could not resolve into stars; only later were such patches split into gas clouds and distant galaxies.","cn":"从 17 世纪起，nebula 被用于望远镜无法分解成星点的任何模糊斑块；后来这些斑块才被分成气体云与遥远星系。"},{"era":"THE MODERN NARROWING","en":"Once galaxies were recognized as separate systems, nebula was restricted to clouds inside our own galaxy, and the older wide sense survives mainly in historical writing.","cn":"在星系被认作独立系统之后，nebula 收窄为银河系内部的云，较宽的旧义主要留在历史文献中。"},{"era":"THE PLANETARY MISNOMER","en":"Planetary nebula was named in the eighteenth century because the round shell resembled a planet's disc; the label is generally recognized as a misnomer kept by tradition.","cn":"行星状星云在 18 世纪得名，因为圆形壳层像行星圆盘；一般认为这是被传统保留下来的误称。"},{"era":"UNCERTAIN DETAILS","en":"Root uncertainty: the Indo-European form behind nebula and nephele is a reconstruction. First-date uncertainty only: the earliest English astronomical use is not precisely dated and is placed in the seventeenth century.","cn":"词根存疑：nebula 与 nephele 背后的印欧形式属重构。仅首见年代存疑：最早的英语天文用例没有确切年代，通常定在 17 世纪。"}]},"similar":{"note":{"en":"Group one holds words of the same cloud stock that are easily confused; group two holds the neighbouring astronomical objects.","cn":"第一组是同出「云」词干、容易混淆的词；第二组是邻近的天体类别。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nebulous","ipa":"/ˈnebjələs/","tag":"vague, cloud-like","definition":"The adjective of nebula, now used mostly for ideas that are vague; it describes a quality, not an object in space.","definitionCN":"nebula 的形容词，如今多指想法模糊；它描述性质，不指太空中的物体。"},{"word":"nebular","ipa":"/ˈnebjələ/","tag":"of a nebula","definition":"The technical adjective used in nebular hypothesis and nebular line; it names a relation to nebulae, not their vagueness.","definitionCN":"用于星云假说、星云谱线的技术形容词；它表示与星云的关系，而非模糊。"},{"word":"galaxy","ipa":"/ˈɡæləksi/","tag":"a system of stars","definition":"Once called nebulae because they looked fuzzy; now a separate category, and a galaxy contains many nebulae.","definitionCN":"曾因外观模糊而被称为星云；如今是另一类别，一个星系包含许多星云。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cloud","ipa":"/klaʊd/","tag":"water droplets in air","definition":"The everyday word for a mass of droplets in the atmosphere; nebula is its Latin cousin used for space or for haze.","definitionCN":"日常词，指大气中的水滴团；nebula 是它的拉丁表亲，用于太空或雾状物。"},{"word":"haze","ipa":"/heɪz/","tag":"thin obscuring mist","definition":"A thin mist that blurs a view; the figurative sense of nebula borrows exactly this blurring.","definitionCN":"使视线模糊的薄雾；nebula 的比喻义借的正是这种模糊。"},{"word":"gas cloud","ipa":"/ɡæs klaʊd/","tag":"a descriptive term","definition":"A plain descriptive phrase for the same object; nebula is the traditional name, gas cloud the modern explanatory one.","definitionCN":"对同一物体的朴素描述；nebula 是传统名称，gas cloud 是现代解释性说法。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin nebula 'mist': a cloud in space, not in the air.","cn":"拉丁 nebula「雾」：在太空里而不在空气里的云。"},{"en":"Four named types: emission, reflection, planetary, dark.","cn":"四种常见类型：发射、反射、行星状、暗。"},{"en":"The plural keeps the Latin: nebulae.","cn":"复数保留拉丁式：nebulae。"},{"en":"The adjective nebulous drifted to 'vague'.","cn":"形容词 nebulous 漂移为「模糊」。"},{"en":"The family runs nebular, nebulosity, nebulose.","cn":"同族词包括 nebular、nebulosity、nebulose。"}],"abstract":[{"en":"Picture breath on a cold window hiding the street behind it.","cn":"想象冷窗上的一层呼气，把后面的街遮住。"},{"en":"Picture a lamp behind gauze, glowing without a clear edge.","cn":"想象纱布后面的一盏灯，亮着却没有清楚的边缘。"},{"en":"Picture an idea with no outline yet, only a coloured blur.","cn":"想象一个还没有轮廓的想法，只有一团带颜色的模糊。"}]},"examples":[{"en":"The Orion Nebula is visible to the naked eye as a fuzzy star.","cn":"猎户座大星云肉眼看去像一颗模糊的星。"},{"en":"Dust in the nebula hides the newborn stars from view.","cn":"星云中的尘埃把新生恒星遮住。"},{"en":"A planetary nebula forms when a sun-like star sheds its outer layers.","cn":"类太阳恒星抛出外层时形成行星状星云。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「nebula」近「neb（雾）」——天上的一团雾 → 星云","word":"nebula"},"root":"拉丁 nebula「雾、云」（-ula 为指小后缀），与希腊 nephele「云」同源，印欧词根属重构形式；17 世纪起用于指望远镜下无法分解的模糊天体。","sensesIntro":{"en":"Eight senses follow one cloud: a mist in space, then the same cloud glowing, reflecting, shed by a dying star, blocking light, left by an explosion, appearing in old medicine and finally serving as an image of vagueness.","cn":"八个义项沿同一团云展开：太空中的雾；这团云再依次被电离发光、反射他光、由垂死恒星抛出、遮住星光、由爆炸留下、出现在旧医学中，最后成为「模糊」的意象。"},"semanticMap":{"core":{"en":"CORE IMAGE: a coloured mist in a telescope, with stars faintly behind it.","cn":"核心意象：望远镜里一团带颜色的雾，后面隐约有星。"},"chain":["MIST IN SPACE","GLOWING GAS","BORROWED LIGHT","SHED SHELL","DARK SILHOUETTE","EXPLOSION DEBRIS"],"branches":[{"senses":"S1","en":"THE OBJECT: gas and dust occupying the space between stars.","cn":"物体本身：占据恒星之间空间的气体与尘埃。"},{"senses":"S2 · S3","en":"TWO WAYS TO SHINE: its own ionized glow, or reflected borrowed light.","cn":"两种发亮方式：自身电离发光，或反射借来的光。"},{"senses":"S4","en":"A DYING STAR'S SHELL: the round planetary nebula, misnamed for its disc.","cn":"垂死恒星的壳：圆盘状的行星状星云，因圆盘而被误称。"},{"senses":"S5","en":"SEEN BY ABSENCE: dust hides the stars and appears as a dark lane.","cn":"靠缺席被看见：尘埃遮住星，显现为暗带。"},{"senses":"S6 · S7 · S8","en":"AFTERMATH, MEDICINE AND METAPHOR: explosion debris, a cloudy spot, and the haze of a vague idea.","cn":"余烬、医学与比喻：爆炸碎片、浑浊斑点，以及模糊想法的雾。"}]},"affixes":{"intro":{"en":"Nebula is a Latin noun with a diminutive suffix; its English family is built almost entirely from Latin adjectives and further suffixes.","cn":"nebula 是带指小后缀的拉丁名词；它的英语词族几乎全由拉丁形容词与进一步的后缀构成。"},"latinIntro":{"en":"Latin nebula gives nebular, nebulous and nebulosity; Greek nephele is a cognate that supplies nephology, the study of clouds, through a different route.","cn":"拉丁 nebula 给出 nebular、nebulous、nebulosity；希腊 nephele 是同源词，经另一条路径给出 nephology（云学）。"},"items":[{"word":"nebula","structure":"nebula, nebulae (Latin noun, first declension)","meaning":"mist, cloud","meaningCN":"雾；云","example":"The Latin noun is the source of all the English forms.","exampleCN":"这个拉丁名词是全部英语形式的来源。"},{"word":"-ula","structure":"-ula (Latin diminutive suffix)","meaning":"small","meaningCN":"小的","example":"The suffix makes nebula a little cloud.","exampleCN":"这个后缀使 nebula 成为「小片云」。"},{"word":"-ar","structure":"-aris (Latin adjective suffix)","meaning":"of or relating to","meaningCN":"……的","example":"Nebular means of a nebula.","exampleCN":"nebular 意为星云的。"},{"word":"-ous","structure":"-osus (Latin adjective suffix)","meaning":"full of, having","meaningCN":"充满……的；有……性质的","example":"Nebulous means full of cloud.","exampleCN":"nebulous 意为充满云雾的。"},{"word":"-ity","structure":"-itas (Latin noun suffix)","meaning":"state or quality","meaningCN":"状态；性质","example":"Nebulosity is the state of being cloudy.","exampleCN":"nebulosity 是云雾状的状态。"},{"word":"nebular","structure":"nebula + -ar","meaning":"of a nebula","meaningCN":"星云的","example":"Nebular hypothesis is the older theory of star formation.","exampleCN":"星云假说是一种较早的恒星形成理论。"},{"word":"nebulous","structure":"nebula + -ous","meaning":"cloud-like; vague","meaningCN":"云雾状的；模糊的","example":"The word moved from sky to ideas.","exampleCN":"这个词从天空移到了想法。"},{"word":"nebulosity","structure":"nebulous + -ity","meaning":"cloudiness","meaningCN":"云雾状；模糊","example":"It also names a cloudy patch.","exampleCN":"它也可指一团云雾状物。"},{"word":"emission nebula","structure":"emission + nebula","meaning":"a self-glowing cloud","meaningCN":"发射星云","example":"The compound names the mechanism of the glow.","exampleCN":"这个复合词标出发光机制。"}],"latinEntries":[{"word":"nebula","structure":"nebula, nebulae (f., first declension)","meaning":"mist, cloud","meaningCN":"雾；云"},{"word":"nebulosus","structure":"nebulosus, nebulosa, nebulosum (adjective)","meaning":"cloudy, misty","meaningCN":"云雾状的"}]}},{"word":"interstellar","ipa_uk":"/ˌɪntəˈstelə/","ipa_us":"/ˌɪntərˈstelər/","definition_zh":"星际的；恒星之间的；穿越恒星之间的","definition_en":"located between or travelling between the stars","core_image":"两枚亮星之间是一段几乎空无一物、却漂着细尘与气体的黑色长路","scene":"看着两枚亮星之间那片看不见尽头的黑，你说 Interstellar space is not entirely empty.","sceneCN":"这里 interstellar 指「位于恒星之间的」（第 1 个义项：两星之间的空间区域）；句意为星际空间并非完全空无一物。图中可辨识物件：两枚亮星、中间的黑色空间、漂着的细尘、远处的微光。","pos":[{"tag":"adj.","zh":"星际的；恒星之间的"}],"collocations":[{"phrase":"interstellar space","zh":"星际空间"},{"phrase":"interstellar medium","zh":"星际介质"},{"phrase":"interstellar dust","zh":"星际尘埃"},{"phrase":"interstellar travel","zh":"星际旅行"},{"phrase":"interstellar object","zh":"星际天体"},{"phrase":"interstellar communication","zh":"星际通讯"},{"phrase":"interstellar extinction","zh":"星际消光"}],"forms":[{"label":"比较级","form":"more interstellar"},{"label":"最高级","form":"most interstellar"},{"label":"基础形容词（恒星的）","form":"stellar"},{"label":"相关名词短语（星际介质）","form":"interstellar medium"},{"label":"相关名词短语（星际空间）","form":"interstellar space"},{"label":"平行形容词（行星际的）","form":"interplanetary"}],"derivatives":[{"word":"stellar","pos":"adj.","zh":"stella + -ar：恒星的；本词去掉 inter- 后的基础形容词"},{"word":"interstellar medium","pos":"n.","zh":"inter- + stellar + medium：星际介质；由本词构成的复合名词"},{"word":"interstellar space","pos":"n.","zh":"inter- + stellar + space：星际空间；由本词构成的复合名词"},{"word":"interplanetary","pos":"adj.","zh":"inter- + planetary：行星际的；同一前缀的平行构词，用于说明 inter- 的可产性"}],"senses":[{"no":"01","title":"Between the stars","titleCN":"位于恒星之间的","definition":"located in the space between stars","definitionCN":"位于恒星之间的空间","example":"Interstellar space is not entirely empty.","exampleCN":"星际空间并非完全空无一物。","why":"the adjective is literal: inter- 'between' plus stellar 'of stars', so it marks the region that belongs to no single star.","whyCN":"这个形容词是字面组合：inter-「在……之间」加 stellar「恒星的」，标出不属于任何单颗恒星的那片区域。"},{"no":"02","title":"The matter between stars","titleCN":"恒星之间的物质：星际介质","definition":"the gas, dust, radiation and magnetic fields filling the space between stars","definitionCN":"填满恒星之间空间的气体、尘埃、辐射与磁场","example":"The interstellar medium is thinner than any laboratory vacuum.","exampleCN":"星际介质比任何实验室真空都稀薄。","why":"once the space was found not to be empty, a noun was needed for its contents, and medium supplied that neutral word.","whyCN":"在发现空间并不空之后，需要给其中的内容一个名词，medium 提供了这个中性的词。"},{"no":"03","title":"Travel from star to star","titleCN":"穿越恒星之间的航行","definition":"relating to journeys or missions that cross the space between stars","definitionCN":"与穿越恒星之间空间的航行或任务有关","example":"Interstellar travel remains far beyond current engineering.","exampleCN":"星际旅行仍远超现有工程能力。","why":"the adjective extends from place to motion: what lies between stars also describes the trip across them.","whyCN":"这个形容词从「地点」扩展到「运动」：位于恒星之间的空间也用来描述穿越它的旅程。"},{"no":"04","title":"An object from another star system","titleCN":"来自另一个恒星系统的天体","definition":"describing a comet or asteroid that entered our system from another star","definitionCN":"描述从另一颗恒星系统进入我们系统的彗星或小行星","example":"The first known interstellar object passed through in 2017.","exampleCN":"已知的第一个星际天体在 2017 年穿过太阳系。","why":"if an object came from between the stars, the adjective marks its origin rather than its position.","whyCN":"若某天体来自恒星之间，这个形容词标的是它的来源，而非当前位置。"},{"no":"05","title":"Dust that dims starlight","titleCN":"使星光变暗的星际尘埃","definition":"describing the absorption and reddening of starlight by dust between stars","definitionCN":"描述星光被恒星之间的尘埃吸收与变红","example":"Interstellar extinction makes distant stars look redder.","exampleCN":"星际消光让遥远的恒星看起来更红。","why":"the dust is in the way, so the adjective names the medium that interferes with the light rather than the light itself.","whyCN":"尘埃挡在光路上，因此这个形容词指的是干扰光的介质，而非光本身。"},{"no":"06","title":"Chemistry in the space between stars","titleCN":"星际空间中的分子与化学","definition":"describing molecules, reactions or chemistry occurring in interstellar clouds","definitionCN":"描述发生在星际云中的分子、反应或化学过程","example":"Astronomers have found interstellar molecules in cold clouds.","exampleCN":"天文学家在冷云中发现了星际分子。","why":"chemistry needs a vessel, and the cold clouds between stars turned out to be that vessel.","whyCN":"化学反应需要一个容器，而恒星之间的冷云正是这个容器。"},{"no":"07","title":"Signals across the gap","titleCN":"跨越星际距离的通讯","definition":"relating to radio or other signals sent across interstellar distances","definitionCN":"与跨越星际距离发送的无线电或其他信号有关","example":"Interstellar communication raises questions no treaty answers.","exampleCN":"星际通讯提出了一些条约无法回答的问题。","why":"communication is the human use of the same gap, so the adjective also qualifies the messages sent across it.","whyCN":"通讯是人类对同一段空隙的利用，因此这个形容词也修饰跨越其间的讯息。"},{"no":"08","title":"Figurative: a gap too wide to cross","titleCN":"比喻义：宽到跨不过去的间隔","definition":"a figurative use for a distance or difference so large that it seems to separate two worlds","definitionCN":"比喻过大、几乎像隔开两个世界的距离或差异","example":"An interstellar gap opened between the two departments.","exampleCN":"两个部门之间裂开了一道星际般的鸿沟。","why":"the metaphor borrows the scale of the sky: a gap measured in light-years is beyond ordinary reach.","whyCN":"这个比喻借用了天空的尺度：以光年计的空隙，超出日常可达的范围。"}],"etymology":{"intro":{"en":"Interstellar is Latin inter 'between' plus stellar 'of stars', a scientific compound formed in English rather than inherited whole. Dates are approximate.","cn":"interstellar 是拉丁 inter「在……之间」加 stellar「恒星的」，属英语中形成的科学复合词，而非整体承继而来。年代均为约数。"},"items":[{"era":"LATIN INTER","en":"Inter is the Latin preposition 'between, among'; it survives in many English compounds such as international and interval.","cn":"inter 是拉丁介词「在……之间、在……之中」；它活在许多英语复合词中，如 international 与 interval。"},{"era":"LATIN STELLA AND STELLARIS","en":"Stella 'star' and its adjective stellaris 'of stars' supply the second half; stellar entered English through scientific Latin.","cn":"stella「星」及其形容词 stellaris「恒星的」提供后半；stellar 经科学拉丁语进入英语。"},{"era":"THE ENGLISH COMPOUND","en":"Interstellar is generally believed to have been formed in English scientific writing in the seventeenth century, once the space between stars became an object of study.","cn":"一般认为，interstellar 在 17 世纪的英语科学写作中形成，当时恒星之间的空间开始成为研究对象。"},{"era":"THE MODERN EXTENSIONS","en":"In the twentieth century the adjective attached itself to medium, dust, travel and communication as those fields developed.","cn":"20 世纪，随着相关领域的发展，这个形容词依次附着在 medium、dust、travel、communication 之前。"},{"era":"UNCERTAIN DETAILS","en":"Root uncertainty: the Indo-European form behind stella is a reconstruction. First-date uncertainty only: the earliest printed use of interstellar is not exactly dated and is usually placed in the seventeenth century.","cn":"词根存疑：stella 背后的印欧形式属重构。仅首见年代存疑：interstellar 的最早印刷用例没有确切年代，通常定在 17 世纪。"}]},"similar":{"note":{"en":"Group one holds compounds built on the same inter- prefix; group two holds the near adjectives that describe neighbouring kinds of space.","cn":"第一组是同用 inter- 前缀的复合词；第二组是描述相邻空间类别的近义形容词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"interplanetary","ipa":"/ˌɪntəˈplænətri/","tag":"between planets","definition":"Inter- plus planetary: it covers the space inside a solar system, a much smaller scale than interstellar.","definitionCN":"inter- 加 planetary：指太阳系内的空间，尺度远小于星际。"},{"word":"intergalactic","ipa":"/ˌɪntəɡəˈlæktɪk/","tag":"between galaxies","definition":"Inter- plus galactic: it covers the space between whole galaxies, one scale larger than interstellar.","definitionCN":"inter- 加 galactic：指整个星系之间的空间，比星际大一个尺度。"},{"word":"stellar","ipa":"/ˈstelə/","tag":"of a star","definition":"Without the prefix it describes a single star's properties; interstellar is about the space that belongs to no star.","definitionCN":"去掉前缀后它描述单颗恒星的性质；interstellar 说的是不属于任何恒星的空间。"}]},{"heading":"NEAR MEANING","entries":[{"word":"interplanetary medium","ipa":"/ˌɪntəˈplænətri ˈmiːdiəm/","tag":"matter inside a solar system","definition":"The gas and dust within a planetary system; the interstellar medium begins where the solar wind stops.","definitionCN":"行星系统内部的气体与尘埃；星际介质从太阳风终止之处开始。"},{"word":"deep space","ipa":"/diːp speɪs/","tag":"far space, loosely defined","definition":"An informal term for space far from earth; it is not a precise scale and does not name what lies between stars.","definitionCN":"指远离地球的太空的非正式说法；它不是精确尺度，也不特指恒星之间。"},{"word":"outer space","ipa":"/ˈaʊtə speɪs/","tag":"everything beyond the atmosphere","definition":"The general term for space beyond the atmosphere, including but not limited to interstellar regions.","definitionCN":"指大气层外太空的通用词，包含但不限于星际区域。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"inter- 'between' + stellar 'of stars': between stars.","cn":"inter-「之间」+ stellar「恒星的」：恒星之间的。"},{"en":"Three scales: interplanetary, interstellar, intergalactic.","cn":"三个尺度：行星际、星际、星系际。"},{"en":"Fixed phrases: interstellar medium, dust, travel.","cn":"固定短语：星际介质、星际尘埃、星际旅行。"},{"en":"The base adjective is stellar.","cn":"基础形容词是 stellar。"},{"en":"The prefix inter- also builds international and interval.","cn":"前缀 inter- 还构成 international 与 interval。"}],"abstract":[{"en":"Picture two lamps at opposite ends of a dark hall with dust in the air between them.","cn":"想象暗厅两端各有一盏灯，中间空气里浮着尘。"},{"en":"Picture a message that must cross a void no rope can span.","cn":"想象一条必须穿过无绳可系的虚空才能送达的消息。"},{"en":"Picture two neighbours so far apart that they never hear each other.","cn":"想象两个邻居相隔太远，永远听不见对方。"}]},"examples":[{"en":"Interstellar dust reddens the light of distant stars.","cn":"星际尘埃使遥远星光变红。"},{"en":"No spacecraft has yet achieved interstellar travel.","cn":"尚无航天器实现星际旅行。"},{"en":"The interstellar medium is mostly hydrogen and helium.","cn":"星际介质主要是氢与氦。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「inter（之间）+ stellar（星）」——星与星之间的 → 星际的","word":"interstellar"},"root":"拉丁 inter「在……之间」+ 拉丁 stella「星」的形容词 stellaris→stellar；17 世纪英语科学复合词。","sensesIntro":{"en":"Eight senses follow one gap: the space between stars, the matter in it, the journey across it, an object arriving from it, the dust that dims light, the chemistry inside it, the signals sent through it and finally any gap too wide to cross.","cn":"八个义项沿同一段空隙展开：恒星之间的空间；其中的物质、穿越它的航行、从它而来的天体、使光变暗的尘埃、其中的化学、穿它而过的讯号，最后是任何宽到跨不过的间隔。"},"semanticMap":{"core":{"en":"CORE IMAGE: a long dark road between two lamps, with fine dust drifting along it.","cn":"核心意象：两盏灯之间一条很长的暗路，细尘沿路飘着。"},"chain":["BETWEEN STARS","MATTER THERE","CROSSING IT","ARRIVING FROM IT","DUST IN THE WAY","SIGNALS ACROSS"],"branches":[{"senses":"S1 · S2","en":"PLACE AND CONTENTS: the region, and the gas and dust that fill it.","cn":"地点与内容：那片区域，以及填满它的气体与尘埃。"},{"senses":"S3 · S7","en":"MOVEMENT AND MESSAGES: journeys and signals that cross the gap.","cn":"运动与讯息：穿越空隙的航行与信号。"},{"senses":"S4","en":"FOREIGN ORIGIN: an object whose address is another star system.","cn":"外来来源：地址在另一个恒星系统的天体。"},{"senses":"S5 · S6","en":"WHAT LIES IN THE WAY: dust that dims light and clouds where molecules form.","cn":"挡在路上的东西：使光变暗的尘埃，以及形成分子的云。"},{"senses":"S8","en":"THE METAPHOR: any distance that separates two worlds.","cn":"比喻：任何把两个世界隔开的距离。"}]},"affixes":{"intro":{"en":"Interstellar is prefix plus adjective, and both halves belong to Latin; the prefix is highly productive in English.","cn":"interstellar 是前缀加形容词，两半都属拉丁语；这个前缀在英语中构词力很强。"},"latinIntro":{"en":"Latin inter 'between' gives interplanetary and intergalactic; Latin stella gives stellar, constellation and stellate.","cn":"拉丁 inter「之间」给出 interplanetary 与 intergalactic；拉丁 stella 给出 stellar、constellation、stellate。"},"items":[{"word":"inter-","structure":"inter (Latin preposition)","meaning":"between, among","meaningCN":"在……之间","example":"The prefix marks position between two things.","exampleCN":"这个前缀标出位于两物之间。"},{"word":"stella","structure":"stella, stellae (Latin noun, first declension)","meaning":"star","meaningCN":"星","example":"The root supplies the second half.","exampleCN":"这个词根提供后半。"},{"word":"stellar","structure":"stella + -aris","meaning":"of stars","meaningCN":"恒星的","example":"Stellar is the free adjective used here.","exampleCN":"stellar 是此处使用的自由形容词。"},{"word":"interstellar","structure":"inter- + stellar","meaning":"between stars","meaningCN":"星际的","example":"The compound is formed in English from Latin parts.","exampleCN":"这个复合词由拉丁部件在英语中构成。"},{"word":"interstellar medium","structure":"interstellar + medium","meaning":"the matter between stars","meaningCN":"星际介质","example":"Medium is the Latin word for the middle or a substance.","exampleCN":"medium 是拉丁语中「中间」或「物质」的词。"},{"word":"interstellar space","structure":"interstellar + space","meaning":"the region between stars","meaningCN":"星际空间","example":"Space is a native English noun.","exampleCN":"space 是英语本族名词。"},{"word":"interplanetary","structure":"inter- + planetary","meaning":"between planets","meaningCN":"行星际的","example":"The same prefix at a smaller scale.","exampleCN":"同一前缀，较小尺度。"},{"word":"intergalactic","structure":"inter- + galactic","meaning":"between galaxies","meaningCN":"星系际的","example":"The same prefix at a larger scale.","exampleCN":"同一前缀，较大尺度。"},{"word":"interval","structure":"inter- + vallum (Latin 'rampart')","meaning":"a gap between points","meaningCN":"间隔","example":"The prefix also appears in older Latin compounds.","exampleCN":"这个前缀也出现在更早的拉丁复合词中。"}],"latinEntries":[{"word":"inter","structure":"inter (preposition with accusative)","meaning":"between, among","meaningCN":"在……之间"},{"word":"stella","structure":"stella, stellae (f., first declension)","meaning":"star","meaningCN":"星"},{"word":"stellaris","structure":"stellaris, stellare (adjective, third declension)","meaning":"of the stars","meaningCN":"恒星的"}]}},{"word":"star cluster","ipa_uk":"/stɑː ˈklʌstə/","ipa_us":"/stɑːr ˈklʌstər/","definition_zh":"星团；由引力束缚、一起运动的一群恒星","definition_en":"a group of stars that are bound together by gravity and move as one system","core_image":"一小片天区里挤着几百个亮点，边缘的星像被一根看不见的绳拴住，绕着同一个中心转","scene":"望远镜里一小片天区挤着许多亮点，你说 That star cluster is bound by gravity.","sceneCN":"这里 star cluster 指「由引力束缚、共同运动的一群恒星」（第 1 个义项：受引力约束的恒星集团）；句意为那个星团被引力束缚。图中可辨识物件：密集亮点、共同的中心、引力示意弧线、望远镜视场。","pos":[{"tag":"n.","zh":"星团（可数；常见类型有疏散星团与球状星团）"}],"collocations":[{"phrase":"open star cluster","zh":"疏散星团"},{"phrase":"globular star cluster","zh":"球状星团"},{"phrase":"a young star cluster","zh":"年轻的星团"},{"phrase":"members of a star cluster","zh":"星团成员"},{"phrase":"the age of a star cluster","zh":"星团的年龄"}],"forms":[{"label":"复数","form":"star clusters"},{"label":"相关类型","form":"open cluster（疏散星团）"},{"label":"相关类型","form":"globular cluster（球状星团）"},{"label":"相关名词","form":"cluster（群；簇）"},{"label":"相关形容词","form":"clustered（聚成一团的）"},{"label":"相关术语","form":"asterism（星群图形）"}],"derivatives":[{"word":"cluster","pos":"n./v.","zh":"cluster 为英语本族名词，指一簇；star cluster 由它构成复合名词"},{"word":"clustered","pos":"adj.","zh":"cluster + -ed：聚集成团的"},{"word":"clustering","pos":"n./adj.","zh":"cluster + -ing：聚簇；成团分布"},{"word":"starry","pos":"adj.","zh":"star + -y：多星的；星状的"},{"word":"stellar","pos":"adj.","zh":"stella + -ar：恒星的；与本词前半同源"}],"senses":[{"no":"01","title":"A group bound by gravity","titleCN":"由引力束缚、共同运动的一群恒星","definition":"a group of stars held together by mutual gravity and moving as one system","definitionCN":"一群被相互引力维系、作为同一系统运动的恒星","example":"That star cluster is bound by gravity.","exampleCN":"那个星团被引力束缚。","why":"the phrase joins the object to its binding: a cluster is not merely a pattern on the sky but a physical group that stays together.","whyCN":"这个短语把天体与其束缚方式并置：星团不只是天上的图案，而是真正待在一起的一群。"},{"no":"02","title":"An open cluster","titleCN":"疏散星团：年轻、松散、多在银盘","definition":"a loose, relatively young group of stars, usually found in the disk of a galaxy","definitionCN":"松散、相对年轻、通常位于星系盘面的恒星群","example":"The Pleiades is a well-known open star cluster.","exampleCN":"昴星团是著名的疏散星团。","why":"open refers to the loose spacing: the members are bound but far apart, unlike the tight ball of a globular cluster.","whyCN":"open 指间距松散：成员虽受束缚却彼此相隔很远，不像球状星团那样紧成一球。"},{"no":"03","title":"A globular cluster","titleCN":"球状星团：年老、密集、多在星系晕","definition":"a dense, roughly spherical group of very old stars, usually in a galaxy's halo","definitionCN":"密集、近似球形、由非常古老恒星组成、通常位于星系晕中的星团","example":"Globular clusters orbit the galaxy far above its disk.","exampleCN":"球状星团在远离盘面的高处绕星系运行。","why":"globular comes from Latin globulus 'little ball', and the name describes the shape seen through a telescope.","whyCN":"globular 出自拉丁 globulus「小球」，名字描述的是望远镜里看到的形状。"},{"no":"04","title":"Stars born together","titleCN":"同一批诞生的成员星","definition":"the members of such a group, which formed from the same cloud at about the same time","definitionCN":"在同一片云中、几乎同时形成的成员星","example":"Every star in the cluster has nearly the same age.","exampleCN":"星团中每颗星的年龄几乎相同。","why":"because the members share a birth cloud, the cluster becomes a set of siblings with a common starting point.","whyCN":"由于成员共享同一片诞生云，星团就成了一批起点相同的兄弟姐妹。"},{"no":"05","title":"A laboratory for stellar evolution","titleCN":"研究恒星演化的天然实验室","definition":"a group used by astronomers as a controlled sample for studying how stars age","definitionCN":"被天文学家当作研究恒星如何老去的对照样本","example":"A star cluster lets astronomers compare stars of one age but different masses.","exampleCN":"星团让天文学家比较同龄而质量不同的恒星。","why":"same age and same chemistry, different mass: that is exactly the controlled comparison a laboratory would build.","whyCN":"同年龄、同成分、不同质量，正是实验室会刻意构造的对照条件。"},{"no":"06","title":"A building block of the galaxy","titleCN":"星系的组成单元与分布标记","definition":"a population of stars used to trace the structure and history of a galaxy","definitionCN":"用来追踪星系结构与历史的一批恒星","example":"Old star clusters mark the halo of the Milky Way.","exampleCN":"古老星团标出银河系的晕。","why":"clusters are bright enough to be seen far away, so they serve as tracers of a galaxy's shape.","whyCN":"星团足够亮，能在远处被看见，因此可作星系形状的示踪物。"},{"no":"07","title":"A grouping visible to the eye","titleCN":"肉眼可见的成团星群","definition":"a group of stars that appears as a knot of light to the naked eye or in binoculars","definitionCN":"肉眼或双筒望远镜中呈现为一团光的星群","example":"To the naked eye the star cluster looks like a fuzzy patch.","exampleCN":"肉眼看去，这个星团像一小片模糊的光。","why":"before photography, the visible knot was the only evidence, so the everyday sense names what an observer actually sees.","whyCN":"在摄影之前，可见的那团光就是唯一证据，因此日常义指观测者真正看到的东西。"},{"no":"08","title":"Figurative: a dense group","titleCN":"比喻义：密集聚在一起的一群","definition":"a figurative use for a dense gathering of similar people or things","definitionCN":"比喻同类的人或物密集聚在一起","example":"A star cluster of start-ups grew around the old port.","exampleCN":"旧港周围长出了一片「星团」般的初创企业。","why":"the metaphor keeps the two features that matter: many separate points, and one centre they all orbit.","whyCN":"这个比喻保留两个关键特征：许多分开的点，以及它们共同绕行的中心。"}],"etymology":{"intro":{"en":"Star cluster is a compound of native English star and cluster, a word for a bunch; the astronomical sense is a nineteenth-century specialization. Dates are approximate.","cn":"star cluster 由英语本族的 star「星」与 cluster「一簇」构成复合词；天文义是 19 世纪的专业化用法。年代均为约数。"},"items":[{"era":"OLD ENGLISH STEORRA","en":"Star descends from Old English steorra and belongs to the Germanic stock; Latin stella is a cognate, not its source.","cn":"star 承自古英语 steorra，属日耳曼词集；拉丁 stella 是同源词，并非其来源。"},{"era":"OLD ENGLISH CLUSTER","en":"Cluster is recorded in Old English in the sense of a bunch or mass, related to clot and to the idea of things sticking together.","cn":"cluster 在古英语中已有「一束、一团」之义，与 clot 相关，带「粘在一起」的意思。"},{"era":"THE COMPOUND","en":"Star cluster is generally believed to have settled as an astronomical term in the nineteenth century, when catalogues began listing groups separately from single stars.","cn":"一般认为，star cluster 在 19 世纪定型为天文术语，当时星表开始把星群与单颗恒星分开著录。"},{"era":"THE TWO TYPES","en":"Open and globular clusters were distinguished in the same period, as the shape and spacing of the two kinds became measurable.","cn":"同一时期，疏散星团与球状星团被区分开来，因为这两类的形状与间距变得可测量。"},{"era":"UNCERTAIN DETAILS","en":"Root uncertainty: the deeper origin of cluster is a reconstruction, and its link to clot is generally accepted but not proven. First-date uncertainty only: the earliest printed use of the exact phrase star cluster is not recorded.","cn":"词根存疑：cluster 的更深来源属重构，它与 clot 的联系一般认为成立但未获证明。仅首见年代存疑：star cluster 这一确切短语的最早印刷记录不明。"}]},"similar":{"note":{"en":"Group one holds astronomical groupings that are often mistaken for a cluster; group two holds the everyday words for groups that the figurative sense borrows.","cn":"第一组是常被误认为星团的天文分组；第二组是比喻义借用的日常「群」词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"constellation","ipa":"/kənˈsteləʃn/","tag":"a pattern, not a physical group","definition":"Its stars may lie at wildly different distances; a constellation is a line of sight, while a cluster is a real group bound by gravity.","definitionCN":"其中各星距离可能相差极大；星座只是视线方向，星团才是真正被引力束缚的一群。"},{"word":"asterism","ipa":"/ˈæstərɪzəm/","tag":"a naked-eye pattern","definition":"A recognized shape such as the Big Dipper, not necessarily bound; the Pleiades is both an asterism and a cluster, which is why the terms are confused.","definitionCN":"如北斗七星那样被认出的形状，未必受束缚；昴星团既是星群也是星团，因此两者常被混淆。"},{"word":"galaxy","ipa":"/ˈɡæləksi/","tag":"a system of many clusters","definition":"A galaxy contains thousands of clusters; the words differ by scale, not by kind.","definitionCN":"一个星系包含成千上万个星团；两词差别在尺度，而非种类。"}]},{"heading":"NEAR MEANING","entries":[{"word":"cluster","ipa":"/ˈklʌstə/","tag":"a bunch of anything","definition":"The general noun for things gathered closely; star cluster specifies what is gathered.","definitionCN":"泛指聚在一起之物；star cluster 指明所聚的是恒星。"},{"word":"group","ipa":"/ɡruːp/","tag":"the loosest term","definition":"Any set of objects treated together, with no claim of gravity or common origin.","definitionCN":"任何被一起看待的一组，不承诺引力或共同来源。"},{"word":"association","ipa":"/əˌsəʊsiˈeɪʃn/","tag":"a loose stellar grouping","definition":"In astronomy, a very loose group of young stars not tightly bound; looser than a cluster.","definitionCN":"天文学中指束缚很松的年轻恒星群，比星团更松散。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"star + cluster: stars bunched together.","cn":"star + cluster：星被束成一团。"},{"en":"Two main types: open and globular.","cn":"两大类型：疏散与球状。"},{"en":"Same birth cloud, same age: siblings.","cn":"同一诞生云、同一年龄：一群兄弟姐妹。"},{"en":"The family runs cluster, clustered, clustering, starry, stellar.","cn":"同族词包括 cluster、clustered、clustering、starry、stellar。"},{"en":"Not every pattern is a cluster: constellations may be far apart.","cn":"不是每个图案都是星团：星座各星可能相距极远。"}],"abstract":[{"en":"Picture fireflies tied to one another by invisible threads, circling a lamp.","cn":"想象萤火虫被看不见的线相互拴住，绕着一盏灯转。"},{"en":"Picture a crowd on a square all walking around the same fountain.","cn":"想象广场上的人群都绕着同一座喷泉走。"},{"en":"Picture a family album where every photo was taken on the same day.","cn":"想象一本家庭相册，每张照片都摄于同一天。"}]},"examples":[{"en":"The star cluster contains several hundred young stars.","cn":"这个星团包含数百颗年轻恒星。"},{"en":"Globular star clusters are among the oldest objects in the galaxy.","cn":"球状星团是星系中最古老的天体之一。"},{"en":"Astronomers measured the star cluster's distance from its colour.","cn":"天文学家借颜色测出这个星团的距离。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「star（星）+ cluster（一簇）」——聚成一簇的星 → 星团","word":"star cluster"},"root":"古英语 steorra「星」+ 古英语 cluster「一束、一团」（与 clot 相关）；天文义一般认为在 19 世纪定型。拉丁 stella 仅为 star 的同源词。","sensesIntro":{"en":"Eight senses follow one knot: stars held together, then the loose and dense kinds, the shared birthday, the laboratory they provide, their role as galaxy markers, the naked-eye patch and finally any dense gathering with one centre.","cn":"八个义项沿同一团结展开：被束缚在一起的一群星；再分松散与紧密两类、共同的诞生日、它们提供的实验室、作为星系标记的角色、肉眼所见的一团光，最后是任何有共同中心的密集聚集。"},"semanticMap":{"core":{"en":"CORE IMAGE: hundreds of lights packed into one small patch, circling a common centre.","cn":"核心意象：几百个光点挤在一小片天区，绕着共同中心转。"},"chain":["STARS BOUND","LOOSE GROUP","DENSE BALL","SAME BIRTH","AGES COMPARED","GALAXY MARKER"],"branches":[{"senses":"S1","en":"THE BINDING: mutual gravity is what makes a cluster more than a pattern.","cn":"束缚：相互引力才使星团不只是图案。"},{"senses":"S2 · S3 · S7","en":"SHAPE AND SPACING: loose open groups, dense globular balls, and the fuzzy patch seen by eye.","cn":"形状与间距：松散的疏散群、紧密的球状团，以及肉眼所见的一团光。"},{"senses":"S4 · S5","en":"ONE BIRTH, MANY MASSES: shared age turns members into a controlled sample.","cn":"同一次诞生、多种质量：共同年龄使成员成为对照样本。"},{"senses":"S6","en":"TRACERS: bright clusters mark the structure of a whole galaxy.","cn":"示踪物：明亮的星团标出整个星系的结构。"},{"senses":"S8","en":"THE METAPHOR: many points gathered around one centre.","cn":"比喻：许多点围绕一个中心聚拢。"}]},"affixes":{"intro":{"en":"The phrase joins a native star to a native cluster; neither half is Latin, though stellar relatives entered English separately.","cn":"这个短语把本族的 star 与本族的 cluster 并置；两半都不是拉丁语，只是 stellar 一类的同源词另行进入英语。"},"latinIntro":{"en":"Latin stella is a cognate of star and supplies stellar and constellation, but cluster has no Latin source; it is Germanic.","cn":"拉丁 stella 是 star 的同源词，并给出 stellar 与 constellation；cluster 没有拉丁来源，属日耳曼语。"},"items":[{"word":"star","structure":"Old English steorra (native noun)","meaning":"a luminous body","meaningCN":"星","example":"The first half is a free native noun.","exampleCN":"前半是自由的本族名词。"},{"word":"cluster","structure":"Old English cluster (native noun)","meaning":"a bunch, a mass","meaningCN":"一束；一团","example":"The second half is also native.","exampleCN":"后半同样是本族词。"},{"word":"-ed","structure":"-ed (English suffix)","meaning":"having; provided with","meaningCN":"具有……的","example":"Clustered means gathered into clusters.","exampleCN":"clustered 意为聚集成团的。"},{"word":"-ing","structure":"-ing (English suffix)","meaning":"action or state","meaningCN":"动作或状态","example":"Clustering names the process of gathering.","exampleCN":"clustering 指聚集成团的过程。"},{"word":"star cluster","structure":"star + cluster","meaning":"a bound group of stars","meaningCN":"星团","example":"The compound is a modern astronomical label.","exampleCN":"这个复合词是近代天文标签。"},{"word":"open cluster","structure":"open + cluster","meaning":"a loose group","meaningCN":"疏散星团","example":"Open describes the spacing, not openness to view.","exampleCN":"open 描述间距松散，而非「开放观看」。"},{"word":"globular cluster","structure":"globulus 'little ball' + cluster","meaning":"a dense spherical group","meaningCN":"球状星团","example":"The Latin element supplies the shape word.","exampleCN":"拉丁成分提供形状词。"},{"word":"stellar","structure":"stella + -aris","meaning":"of stars","meaningCN":"恒星的","example":"A borrowed relative of star, not a part of this phrase.","exampleCN":"这是 star 的借入同源词，不是本短语的成分。"},{"word":"asterism","structure":"aster (Greek) + -ism","meaning":"a star pattern","meaningCN":"星群图形","example":"A pattern need not be bound, unlike a cluster.","exampleCN":"图形不必受束缚，星团则不然。"}],"latinEntries":[{"word":"stella","structure":"stella, stellae (f., first declension)","meaning":"star","meaningCN":"星"}]}},{"word":"supernova","ipa_uk":"/ˌsuːpəˈnəʊvə/","ipa_us":"/ˌsuːpərˈnoʊvə/","definition_zh":"超新星；恒星生命终结时的剧烈爆发；也指爆发后的天体","definition_en":"the explosive end of a star's life, or the extremely bright object produced by that explosion","core_image":"一颗星在几天里亮到能在白天看见，随后把外壳炸成一圈不断扩散的光环","scene":"记录一颗突然亮到白天可见的星，你说 That supernova outshone its whole galaxy.","sceneCN":"这里 supernova 指「恒星终结时的剧烈爆发」（第 1 个义项：恒星爆发的整体事件）；句意为那颗超新星比整个星系还亮。图中可辨识物件：极亮的星点、被照亮的星系旋臂、扩散的光环、观测记录。","pos":[{"tag":"n.","zh":"超新星（复数 supernovae 或 supernovas）"}],"collocations":[{"phrase":"a Type Ia supernova","zh":"Ia 型超新星"},{"phrase":"a core-collapse supernova","zh":"核心坍缩型超新星"},{"phrase":"supernova remnant","zh":"超新星遗迹"},{"phrase":"observe a supernova","zh":"观测超新星"},{"phrase":"the light curve of a supernova","zh":"超新星的光变曲线"}],"forms":[{"label":"复数（拉丁式）","form":"supernovae"},{"label":"复数（英语式）","form":"supernovas"},{"label":"相关天体（新星）","form":"nova"},{"label":"相关名词短语（遗迹）","form":"supernova remnant"},{"label":"相关形容词","form":"supernova（作定语，如 supernova explosion）"},{"label":"上位概念","form":"stellar explosion（恒星爆发）"}],"derivatives":[{"word":"nova","pos":"n.","zh":"nova 为拉丁「新」，指新星；supernova 是在其前加 super- 形成的复合词"},{"word":"supernova remnant","pos":"n.","zh":"supernova + remnant：超新星遗迹，爆发后残留的膨胀气体"},{"word":"supernovae","pos":"n.","zh":"supernova 的拉丁式复数，见 forms"},{"word":"superluminous","pos":"adj.","zh":"super- + luminous：超亮的；同一前缀的平行构词"}],"senses":[{"no":"01","title":"The explosive death of a star","titleCN":"恒星生命终结时的剧烈爆发","definition":"the catastrophic explosion that ends the life of certain stars","definitionCN":"某些恒星终结生命时的灾难性爆发","example":"That supernova outshone its whole galaxy.","exampleCN":"那颗超新星比整个星系还亮。","why":"the name says what it is: nova is Latin for 'new', and super- marks an event far brighter than an ordinary new star.","whyCN":"名字直说其性质：nova 是拉丁语「新」，super- 标出比普通「新星」亮得多的事件。"},{"no":"02","title":"A thermonuclear runaway","titleCN":"热核失控：白矮星吸积后整体爆炸","definition":"a supernova produced when a white dwarf gains too much mass and detonates","definitionCN":"白矮星吸积过多质量后整体引爆产生的超新星","example":"A Type Ia supernova destroys the white dwarf completely.","exampleCN":"Ia 型超新星把白矮星彻底摧毁。","why":"this type has no collapsing core but a runaway fusion front, which is why its light is so uniform.","whyCN":"这一类没有坍缩的核心，而是失控的聚变前沿，因此亮度异常一致。"},{"no":"03","title":"A collapsing massive star","titleCN":"大质量恒星核心坍缩引发的爆发","definition":"a supernova produced when the core of a massive star collapses and the outer layers rebound","definitionCN":"大质量恒星核心坍缩、外层回弹引发的爆发","example":"A core-collapse supernova leaves a neutron star or a black hole.","exampleCN":"核心坍缩型超新星会留下中子星或黑洞。","why":"the core falls inward in less than a second, and the rebound sends a shock through the envelope.","whyCN":"核心在不到一秒内向内塌陷，回弹把冲击波送过外层。"},{"no":"04","title":"The remnant it leaves","titleCN":"爆发留下的遗迹与膨胀气体","definition":"the expanding shell of gas and dust left behind by the explosion","definitionCN":"爆炸留下的膨胀气体与尘埃壳","example":"The supernova remnant is still expanding after centuries.","exampleCN":"这个超新星遗迹在几百年后仍在膨胀。","why":"remnant is what remains: the star is gone, but the shell keeps moving outward and carries the story.","whyCN":"remnant 即残留：恒星已不在，壳层仍向外运动，带着这段历史。"},{"no":"05","title":"A brightness standard","titleCN":"作为亮度标准的超新星","definition":"a supernova used as a standard candle to measure cosmic distances","definitionCN":"被当作标准烛光来测量宇宙距离的超新星","example":"Type Ia supernovae let astronomers measure far galaxies.","exampleCN":"Ia 型超新星让天文学家测量遥远星系。","why":"because the peak brightness is nearly the same each time, the event becomes a ruler rather than a curiosity.","whyCN":"由于每次峰值亮度几乎相同，这一事件就从奇观变成了量尺。"},{"no":"06","title":"A factory for heavy elements","titleCN":"重元素的锻造场所","definition":"an event in which fusion and explosive burning create elements heavier than iron","definitionCN":"在其中通过聚变与爆炸燃烧生成比铁更重元素的事件","example":"Gold in the earth was forged in supernovae and mergers.","exampleCN":"地球上的金在超新星与并合事件中被锻造。","why":"iron is the end of ordinary fusion, so only an explosion can push nuclei past it.","whyCN":"铁是普通聚变的终点，只有爆炸才能把原子核推向更远处。"},{"no":"07","title":"A recorded historical event","titleCN":"历史上被记录下来的爆发","definition":"a dated supernova recorded by observers, used to date and to test models","definitionCN":"被观测者记录下来的带日期超新星，用于断代与检验模型","example":"Chinese astronomers recorded a supernova in 1054.","exampleCN":"中国天文学家记录了 1054 年的一次超新星爆发。","why":"a supernova can be seen in daylight, so old records exist across cultures and serve as fixed points.","whyCN":"超新星可在白天看见，因此各文化都留有记录，可作固定参照点。"},{"no":"08","title":"Figurative: a spectacular burst","titleCN":"比喻义：惊人的骤然爆发","definition":"a figurative use for a sudden, spectacular rise or outburst","definitionCN":"比喻突然而惊人的上升或爆发","example":"The launch was a supernova of publicity.","exampleCN":"那次发布是宣传上的一次超新星。","why":"the metaphor keeps two features: suddenness and a brilliance that outshines everything around it.","whyCN":"这个比喻保留两个特征：突然，以及盖过周围一切的光亮。"}],"etymology":{"intro":{"en":"Supernova is super- 'above, beyond' plus nova, Latin for 'new', from the phrase stella nova 'new star'. The term was coined in twentieth-century astrophysics. Dates are approximate.","cn":"supernova 是 super-「在上、超出」加 nova「新的」，后者出自短语 stella nova「新星」。这个术语产生于 20 世纪天体物理学。年代均为约数。"},"items":[{"era":"LATIN NOVUS","en":"Novus 'new' gave the adjective nova in stella nova 'new star', the label early observers used for a star that suddenly appeared.","cn":"novus「新的」在短语 stella nova「新星」中给出形容词 nova，那是早期观测者对突然出现的恒星所用的称呼。"},{"era":"LATIN NOVA","en":"Nova became a noun in its own right, naming such an apparition; the plural is novae.","cn":"nova 独立成为名词，指这类突然出现的天体；复数为 novae。"},{"era":"LATIN SUPER","en":"Super is the Latin preposition and prefix 'above, over, beyond', also seen in superior and superimpose.","cn":"super 是拉丁介词与前置成分「在上、超过」，也见于 superior 与 superimpose。"},{"era":"THE COINAGE","en":"Supernova is generally attributed to the 1930s, when Walter Baade and Fritz Zwicky needed a term for explosions far more luminous than ordinary novae.","cn":"一般认为 supernova 于 1930 年代被造出，当时沃尔特·巴德与弗里茨·兹威基需要一个词，指比普通新星亮得多的爆发。"},{"era":"THE MODERN TYPES","en":"The division into thermonuclear and core-collapse supernovae was established later in the twentieth century as spectra and light curves were classified.","cn":"热核型与核心坍缩型的划分在 20 世纪后期随光谱与光变曲线的分类而确立。"},{"era":"UNCERTAIN DETAILS","en":"Root uncertainty: the Indo-European source of novus is a reconstruction. First-date uncertainty only: the exact year of the coinage is not documented, and the 1930s attribution is generally believed rather than proven.","cn":"词根存疑：novus 的印欧来源属重构。仅首见年代存疑：造词的确切年份没有文献记录，1930 年代的说法一般认为成立但未获证明。"}]},"similar":{"note":{"en":"Group one holds the stellar-explosion terms that are routinely confused; group two holds the related objects and the figurative near-equivalents.","cn":"第一组是常被混淆的恒星爆发术语；第二组是相关天体与比喻近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"nova","ipa":"/ˈnəʊvə/","tag":"a smaller eruption","definition":"A nova is a thermonuclear flash on a white dwarf's surface that leaves the star intact; a supernova destroys or collapses the star.","definitionCN":"新星是白矮星表面的热核闪光，恒星仍存；超新星则毁掉或坍缩恒星。"},{"word":"supernova remnant","ipa":"/ˌsuːpəˈnəʊvə ˈremnənt/","tag":"what is left","definition":"The expanding debris after the event; it names the aftermath, not the explosion itself.","definitionCN":"指事件之后膨胀的碎片，是余烬而非爆发本身。"},{"word":"hypernova","ipa":"/ˌhaɪpəˈnəʊvə/","tag":"a very energetic collapse","definition":"An informal term for an especially energetic core collapse, sometimes linked to long gamma-ray bursts; it is not a standard classification.","definitionCN":"对特别高能的核心坍缩的非正式说法，有时与长伽马射线暴相关；不是标准分类。"}]},{"heading":"NEAR MEANING","entries":[{"word":"stellar explosion","ipa":"/ˈstelə ɪkˈspləʊʒn/","tag":"the descriptive phrase","definition":"A plain description covering any explosive stellar event; supernova is the classified term.","definitionCN":"泛指任何恒星爆发事件的朴素说法；supernova 是分类学术语。"},{"word":"black hole","ipa":"/blæk həʊl/","tag":"a possible outcome","definition":"One possible end product of a core-collapse supernova, not the event itself.","definitionCN":"核心坍缩型超新星可能留下的产物之一，并非事件本身。"},{"word":"gamma-ray burst","ipa":"/ˌɡæmə reɪ ˈbɜːst/","tag":"a different phenomenon","definition":"A brief flash of gamma rays from distant sources; some accompany supernovae but the terms are not interchangeable.","definitionCN":"来自遥远源的短暂伽马射线闪；有些与超新星相伴，但两个术语不能互换。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"super- 'beyond' + nova 'new': a new star beyond all others.","cn":"super-「超出」+ nova「新」：超出一切的新星。"},{"en":"Two main types: thermonuclear and core-collapse.","cn":"两大类：热核型与核心坍缩型。"},{"en":"The remnant is the expanding shell left behind.","cn":"遗迹就是留下的膨胀壳层。"},{"en":"The plural keeps the Latin: supernovae.","cn":"复数保留拉丁式：supernovae。"},{"en":"Type Ia works as a standard candle.","cn":"Ia 型可作标准烛光。"}],"abstract":[{"en":"Picture one lamp flaring so brightly that the whole street looks lit for a night.","cn":"想象一盏灯突然亮到整条街像被照亮一夜。"},{"en":"Picture a shell of smoke still expanding long after the fire is out.","cn":"想象火早已熄灭，烟壳仍在向外扩散。"},{"en":"Picture a quiet career that explodes into fame in a single week.","cn":"想象一段平静的事业在一周内炸成名声。"}]},"examples":[{"en":"A supernova can briefly outshine the galaxy that hosts it.","cn":"超新星能短暂地比宿主星系更亮。"},{"en":"The supernova remnant expands into the surrounding gas.","cn":"超新星遗迹向周围气体中膨胀。"},{"en":"Astronomers use Type Ia supernovae to measure cosmic distances.","cn":"天文学家使用 Ia 型超新星测量宇宙距离。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「super（超级）+ nova（新）」——超级新的星 → 超新星","word":"supernova"},"root":"拉丁 super「在上、超出」+ nova「新的」（出自 stella nova「新星」，novus 为「新」）；术语一般认为于 1930 年代由巴德与兹威基提出。","sensesIntro":{"en":"Eight senses follow one explosion: a star dies, then the two mechanisms that cause it, the shell it leaves, the brightness used as a ruler, the elements it forges, the records it leaves in history and finally the image of any spectacular sudden burst.","cn":"八个义项沿同一场爆炸展开：一颗星死去；再分两种机制、留下的壳层、被当作量尺的亮度、被锻造的元素、留在史册的记录，最后是任何惊人骤爆的意象。"},"semanticMap":{"core":{"en":"CORE IMAGE: one point flaring brighter than a whole galaxy, then a shell drifting outward.","cn":"核心意象：一个点亮过整个星系，随后一圈壳层向外漂去。"},"chain":["STAR DIES","WHITE DWARF BLAST","CORE COLLAPSE","EXPANDING SHELL","STANDARD CANDLE","ELEMENTS FORGED"],"branches":[{"senses":"S1","en":"THE EVENT: a star's life ends in a single catastrophic release.","cn":"事件本身：恒星的生命在一次灾难性释放中结束。"},{"senses":"S2 · S3","en":"TWO MECHANISMS: a white dwarf detonates, or a massive core collapses.","cn":"两种机制：白矮星引爆，或大质量核心坍缩。"},{"senses":"S4","en":"THE AFTERMATH: the expanding shell that keeps the record.","cn":"余烬：继续携带记录的膨胀壳层。"},{"senses":"S5 · S7","en":"A MEASURABLE AND DATED LIGHT: a standard candle, and a recorded event.","cn":"可测且有日期的光：标准烛光与被记录的事件。"},{"senses":"S6 · S8","en":"FORGED ELEMENTS AND THE METAPHOR: matter made in the blast, and any brilliant sudden rise.","cn":"锻造的元素与比喻：爆炸中生成物质，以及任何耀眼的骤升。"}]},"affixes":{"intro":{"en":"Supernova is a Latin prefix plus a Latin adjective turned noun, and the whole family stays close to its Latin shapes.","cn":"supernova 是拉丁前缀加一个转为名词的拉丁形容词，整个词族都紧贴拉丁词形。"},"latinIntro":{"en":"Latin super gives superimpose and superior; Latin novus gives novel, innovate and nova itself.","cn":"拉丁 super 给出 superimpose 与 superior；拉丁 novus 给出 novel、innovate 与 nova 本身。"},"items":[{"word":"super-","structure":"super (Latin preposition and prefix)","meaning":"above, beyond","meaningCN":"在上；超出","example":"The prefix marks an event beyond the ordinary class.","exampleCN":"这个前缀标出超出普通类别的事件。"},{"word":"nova","structure":"nova (from Latin novus, 'new')","meaning":"a new star","meaningCN":"新星","example":"Nova began as an adjective in stella nova.","exampleCN":"nova 最初是 stella nova 中的形容词。"},{"word":"novus","structure":"novus, nova, novum (Latin adjective)","meaning":"new","meaningCN":"新的","example":"The root supplies novel and innovate.","exampleCN":"这个词根给出 novel 与 innovate。"},{"word":"supernova","structure":"super- + nova","meaning":"a star exploding beyond nova brightness","meaningCN":"超新星","example":"The compound was coined in astrophysics.","exampleCN":"这个复合词在天体物理学中被造出。"},{"word":"supernovae","structure":"supernova + -ae (Latin plural)","meaning":"the Latin plural","meaningCN":"拉丁式复数","example":"Astronomers often prefer the Latin plural.","exampleCN":"天文学家常用拉丁复数。"},{"word":"supernova remnant","structure":"supernova + remnant","meaning":"the debris left behind","meaningCN":"超新星遗迹","example":"Remnant is a French borrowing meaning 'what remains'.","exampleCN":"remnant 是法语借词，意为「剩余之物」。"},{"word":"superluminous","structure":"super- + luminous","meaning":"beyond bright","meaningCN":"超亮的","example":"A parallel compound with the same prefix.","exampleCN":"同一前缀的平行复合词。"},{"word":"supergiant","structure":"super- + giant","meaning":"an extremely large star","meaningCN":"超巨星","example":"The prefix also marks stellar size classes.","exampleCN":"这个前缀也标记恒星的尺寸等级。"},{"word":"novalike","structure":"nova + -like","meaning":"resembling a nova","meaningCN":"类新星的","example":"A later descriptive compound.","exampleCN":"较晚出现的描述性复合词。"}],"latinEntries":[{"word":"nova","structure":"nova, novae (f., first declension; from novus)","meaning":"a new star","meaningCN":"新星"},{"word":"novus","structure":"novus, nova, novum (adjective)","meaning":"new","meaningCN":"新的"},{"word":"super","structure":"super (preposition and prefix)","meaning":"above, beyond","meaningCN":"在上；超出"}]}},{"word":"explosion","ipa_uk":"/ɪkˈspləʊʒn/","ipa_us":"/ɪkˈsploʊʒn/","definition_zh":"爆炸；爆发；激增；（情绪的）迸发；（辅音的）爆破","definition_en":"a sudden violent release of energy, or a rapid increase, or a sudden outburst","core_image":"一只密闭的铁罐在一声闷响中鼓开，气浪把周围的纸片向外推成一圈","scene":"远处传来一声闷响，窗玻璃跟着震动，你说 The explosion shook every window in the street.","sceneCN":"这里 explosion 指「能量突然剧烈释放的爆炸」（第 1 个义项：伴随热与声响的剧烈膨胀）；句意为那次爆炸震动了整条街的窗户。图中可辨识物件：鼓开的铁罐、向外推的气浪、震动的窗玻璃、纸片。","pos":[{"tag":"n.","zh":"爆炸；爆发；激增；（情绪）迸发；爆破音"}],"collocations":[{"phrase":"a chemical explosion","zh":"化学爆炸"},{"phrase":"a population explosion","zh":"人口激增"},{"phrase":"an explosion of anger","zh":"怒火爆发"},{"phrase":"the explosion of a star","zh":"恒星爆炸"},{"phrase":"an explosion in data","zh":"数据激增"},{"phrase":"a gas explosion","zh":"燃气爆炸"}],"forms":[{"label":"复数","form":"explosions"},{"label":"动词","form":"explode"},{"label":"形容词","form":"explosive"},{"label":"副词","form":"explosively"},{"label":"名词（爆炸性）","form":"explosiveness"},{"label":"施动者名词（引爆器）","form":"exploder"}],"derivatives":[{"word":"explode","pos":"v.","zh":"explosion 去掉名词后缀 -ion 后的动词；拉丁 explodere「以掌声赶下台」"},{"word":"explosive","pos":"adj./n.","zh":"explosion + -ive：爆炸性的；炸药"},{"word":"explosively","pos":"adv.","zh":"explosive + -ly：爆发性地"},{"word":"explosiveness","pos":"n.","zh":"explosive + -ness：爆炸性；易爆程度"}],"senses":[{"no":"01","title":"A violent release of energy","titleCN":"能量突然剧烈释放的爆炸","definition":"a sudden violent release of energy, with heat, light and a loud report","definitionCN":"伴随热、光与巨响的能量突然猛烈释放","example":"The explosion shook every window in the street.","exampleCN":"那次爆炸震动了整条街的窗户。","why":"the core sense is physical: pressure is released faster than the container can yield, so the container gives way.","whyCN":"核心义是物理的：压力释放得比容器能承受的更快，于是容器让位。"},{"no":"02","title":"The detonation of a device","titleCN":"炸弹或装置的引爆","definition":"the detonation of a bomb, mine or other device","definitionCN":"炸弹、地雷或其他装置的引爆","example":"A controlled explosion brought the chimney down.","exampleCN":"一次受控爆破把烟囱放倒。","why":"a device packs the release into a planned moment, so the word shifts from a process to a triggered event.","whyCN":"装置把释放压缩到一个计划好的时刻，于是这个词从过程转为被触发的事件。"},{"no":"03","title":"A rapid increase in number","titleCN":"数量上的激增","definition":"a very rapid increase in number or amount","definitionCN":"数量或规模上极快的增长","example":"The city's population explosion began in the 1950s.","exampleCN":"这座城市的人口激增始于 1950 年代。","why":"the metaphor is quantitative: growth so fast that it looks like a blast rather than a curve.","whyCN":"这是数量比喻：增长快到不像曲线，而像一次爆炸。"},{"no":"04","title":"A sudden outburst of feeling","titleCN":"情绪的突然迸发","definition":"a sudden, loud release of emotion such as anger or laughter","definitionCN":"愤怒、笑声等情绪的突然大声释放","example":"Her explosion of laughter startled the room.","exampleCN":"她突然爆发的大笑惊动了全屋。","why":"feelings held under pressure are imagined as gas under pressure: the same sudden release, without the fire.","whyCN":"被压住的情绪被想象成受压的气体：同样突然释放，只是没有火焰。"},{"no":"05","title":"A natural or cosmic blast","titleCN":"自然或宇宙尺度的爆发","definition":"a violent natural event, such as a volcanic eruption or a stellar explosion","definitionCN":"火山喷发或恒星爆发等自然界的剧烈事件","example":"The explosion of the star was seen in daylight.","exampleCN":"那颗恒星的爆发在白天也能看见。","why":"nature supplies the same physics at a larger scale, so the word covers volcanoes and supernovae alike.","whyCN":"自然在更大尺度上提供同样的物理过程，因此这个词同时覆盖火山与超新星。"},{"no":"06","title":"The release of a stop consonant","titleCN":"语音学中的爆破：塞音的释放","definition":"the release of air that follows a stopped consonant such as p, t or k","definitionCN":"p、t、k 等塞音之后的气流释放","example":"The explosion of the final consonant is audible in careful speech.","exampleCN":"在仔细的发音中能听见末尾辅音的爆破。","why":"phonetics borrowed the word because a stop is air held and then suddenly let go, exactly the same gesture in miniature.","whyCN":"语音学借这个词，因为塞音就是气被挡住后突然放开，正是同一动作的缩小版。"},{"no":"07","title":"A sudden surge of information","titleCN":"信息或数据的突然膨胀","definition":"a rapid expansion in the amount of information, data or options","definitionCN":"信息、数据或选项数量的快速膨胀","example":"An explosion of data changed how the field works.","exampleCN":"数据的爆炸改变了这门学科的工作方式。","why":"when a quantity outgrows every earlier curve, speakers reach for the blast image rather than a word like increase.","whyCN":"当某个量超出以往所有曲线时，说者会取用爆炸意象，而不是「增加」这类词。"},{"no":"08","title":"Figurative: the collapse of a claim","titleCN":"比喻义：某种说法被彻底推翻","definition":"a figurative use for the sudden collapse of a belief, myth or claim","definitionCN":"信念、神话或说法被突然彻底推翻","example":"The paper's explosion of that myth took a decade.","exampleCN":"那篇论文推翻那个神话用了十年。","why":"to explode a myth is to blow it apart, so the noun can name the intellectual demolition rather than a physical blast.","whyCN":"to explode a myth 就是把神话炸开，因此名词可指理智上的拆解，而非物理爆炸。"}],"etymology":{"intro":{"en":"Explosion comes from Latin explodere 'to drive off by clapping, to hiss an actor off the stage', built on ex- 'out' and plaudere 'to clap'. The physical sense is much later. Dates are approximate.","cn":"explosion 出自拉丁 explodere「以掌声赶走、把演员嘘下台」，由 ex-「向外」与 plaudere「拍手」构成。物理「爆炸」义出现得晚得多。年代均为约数。"},"items":[{"era":"LATIN PLAUDERE","en":"Plaudere meant 'to clap, to beat, to strike', and survives in applause and plausible, where the clapping image became 'worthy of approval'.","cn":"plaudere 意为「拍手、击打」，活在 applause 与 plausible 中，后者的掌声意象转为「值得赞许」。"},{"era":"LATIN EXPLODERE","en":"Ex- 'out' plus plaudere gave explodere 'to drive out by clapping', used of an actor hissed off the stage.","cn":"ex-「向外」加 plaudere 构成 explodere「用掌声赶出去」，用于被嘘下台的演员。"},{"era":"THE EARLY ENGLISH SENSE","en":"English explode first meant 'to reject or drive out with scorn', and this sense survives in the phrase to explode a myth.","cn":"英语 explode 最初意为「以轻蔑拒绝或赶走」，这一义项仍活在 to explode a myth 这一短语中。"},{"era":"THE PHYSICAL SENSE","en":"The sense of bursting with a loud report is generally dated to the seventeenth century, when gunpowder made sudden releases familiar.","cn":"伴随巨响的爆裂义一般认为出现于 17 世纪，当时火药让突然释放变得常见。"},{"era":"THE MODERN EXTENSIONS","en":"From the later nineteenth century, and especially in the twentieth, the noun was applied to populations, prices and feelings, all growing or releasing faster than expected.","cn":"从 19 世纪后期、尤其是 20 世纪起，这个名词被用于人口、价格与情绪，指增长或释放快于预期。"},{"era":"UNCERTAIN DETAILS","en":"Root uncertainty: the deeper origin of plaudere is a reconstruction. First-date uncertainty only: the earliest English use of the noun explosion is not precisely dated, and the seventeenth-century dating of the physical sense is generally believed rather than proven.","cn":"词根存疑：plaudere 的更深来源属重构。仅首见年代存疑：名词 explosion 最早的英语用例没有确切年代，物理义定于 17 世纪的说法一般认为成立但未获证明。"}]},"similar":{"note":{"en":"Group one holds the blast words most often swapped with explosion; group two holds the near-synonyms for sudden growth and sudden feeling.","cn":"第一组是最容易与 explosion 互换的「爆」类词；第二组是「骤增」与「骤发」的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"explosive","ipa":"/ɪkˈspləʊsɪv/","tag":"the adjective or the substance","definition":"Either the quality of being able to explode, or a material that does; explosion is the event itself.","definitionCN":"或指能爆炸的性质，或指炸药；explosion 指事件本身。"},{"word":"detonation","ipa":"/ˌdetəˈneɪʃn/","tag":"a supersonic blast","definition":"A technical term for an explosion that travels as a shock wave faster than sound; not every explosion is a detonation.","definitionCN":"指以超音速冲击波传播的爆炸，属技术术语；并非每次爆炸都是爆轰。"},{"word":"deflagration","ipa":"/ˌdefləˈɡreɪʃn/","tag":"a slower burn","definition":"A rapid burning that spreads below supersonic speed; it is a combustion front, not a blast wave.","definitionCN":"以低于音速传播的快速燃烧；是燃烧前沿，而非冲击波。"}]},{"heading":"NEAR MEANING","entries":[{"word":"burst","ipa":"/bɜːst/","tag":"a sudden breaking out","definition":"A sudden release or breaking open, often smaller and less violent; explosion adds energy and noise.","definitionCN":"突然释放或裂开，通常较小、较不剧烈；explosion 多了能量与巨响。"},{"word":"outburst","ipa":"/ˈaʊtbɜːst/","tag":"a sudden show of feeling","definition":"The usual word for a sudden release of emotion or activity, without any physical blast.","definitionCN":"指情绪或活动突然释放的常用词，不含物理爆炸。"},{"word":"surge","ipa":"/sɜːdʒ/","tag":"a strong upward movement","definition":"A sudden large increase, especially in power, demand or numbers; it is smoother than an explosion.","definitionCN":"尤指电力、需求或数量的突然大增；比 explosion 平缓。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"ex- 'out' + plaudere 'clap': clapped out of the room, then blown out.","cn":"ex-「向外」+ plaudere「拍手」：先被拍手赶出房间，再被炸开。"},{"en":"Fixed phrases: population explosion, explosion of anger.","cn":"固定短语：人口激增、怒火爆发。"},{"en":"The family runs explode, explosive, explosively, explosiveness.","cn":"同族词包括 explode、explosive、explosively、explosiveness。"},{"en":"Phonetics uses explosion for releasing a stop.","cn":"语音学用 explosion 指塞音的释放。"},{"en":"To explode a myth is to demolish it, not to detonate it.","cn":"to explode a myth 是拆穿神话，不是引爆它。"}],"abstract":[{"en":"Picture a sealed can giving way all at once instead of slowly leaking.","cn":"想象密封罐不是慢慢漏气，而是一次鼓开。"},{"en":"Picture a room where everyone has been quiet and then all talk at once.","cn":"想象一屋子人一直安静，然后同时开口。"},{"en":"Picture a chart that leaves its paper and goes straight up.","cn":"想象一条曲线离开纸面直冲上去。"}]},"examples":[{"en":"The explosion was heard several kilometres away.","cn":"爆炸在数公里外都能听见。"},{"en":"An explosion of interest followed the discovery.","cn":"发现之后兴趣骤增。"},{"en":"The explosion of the boiler cracked the brickwork.","cn":"锅炉爆炸震裂了砖墙。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「explode（炸开）+ sion」——炸开的那一下 → 爆炸；引申为激增与爆发","word":"explosion"},"root":"拉丁 explodere「以掌声赶下台」= ex-「向外」+ plaudere「拍手」；「爆裂」义一般认为出现于 18 世纪；plaudere 更深来源属重构形式。","sensesIntro":{"en":"Eight senses follow one release: pressure held and then let go, then a device, a population, a feeling, a star, a consonant, a flood of data and finally a demolished claim.","cn":"八个义项沿同一次释放展开：压力被挡住后放开；再依次是装置、人口、情绪、恒星、辅音、数据洪流，最后是被拆穿的说法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a sealed can bulging open in one report, pushing the air outward.","cn":"核心意象：一只密封罐在一声闷响中鼓开，把空气向外推。"},"chain":["PRESSURE RELEASED","DEVICE DETONATES","NUMBERS SURGE","FEELING BURSTS","STAR BLASTS","STOP RELEASED"],"branches":[{"senses":"S1","en":"THE PHYSICAL EVENT: energy released faster than the container can yield.","cn":"物理事件：能量释放快于容器的承受。"},{"senses":"S2 · S5","en":"PLANNED AND NATURAL BLASTS: a bomb, a volcano, a star.","cn":"人为与自然的爆发：炸弹、火山、恒星。"},{"senses":"S3 · S7","en":"QUANTITIES OUTGROWING THEIR CURVES: population and data.","cn":"数量超出原有曲线：人口与数据。"},{"senses":"S4 · S8","en":"PRESSURE THAT IS NOT PHYSICAL: feeling released, and a claim blown apart.","cn":"非物理的压力：情绪释放与被炸开的说法。"},{"senses":"S6","en":"THE MICROSCOPIC VERSION: a stop consonant letting its air go.","cn":"微型版本：塞音放开气流。"}]},"affixes":{"intro":{"en":"Explosion is a Latin verb stem plus the noun suffix -ion; the same stem builds the verb and the adjective in English.","cn":"explosion 是拉丁动词词干加名词后缀 -ion；同一词干在英语中构成动词与形容词。"},"latinIntro":{"en":"Latin explodere gives explode and explosion; Latin plaudere gives applause and plausible, both from the clapping image.","cn":"拉丁 explodere 给出 explode 与 explosion；拉丁 plaudere 给出 applause 与 plausible，都来自掌声的意象。"},"items":[{"word":"ex-","structure":"ex (Latin prefix)","meaning":"out, away","meaningCN":"向外","example":"The prefix marks direction outward.","exampleCN":"这个前缀标出向外的方向。"},{"word":"plaudere","structure":"plaudere (Latin verb, third conjugation)","meaning":"to clap, to strike","meaningCN":"拍手；击打","example":"The root supplies applause.","exampleCN":"这个词根提供 applause。"},{"word":"explodere","structure":"ex- + plaudere","meaning":"to hiss off the stage","meaningCN":"把演员嘘下台","example":"The Latin verb began as a theatrical gesture.","exampleCN":"这个拉丁动词起于剧场动作。"},{"word":"-ion","structure":"-io, -ionis (Latin noun suffix)","meaning":"action or result","meaningCN":"动作或结果","example":"Explosion is the action of exploding.","exampleCN":"explosion 是 exploding 这一动作。"},{"word":"explosion","structure":"explodere + -ion","meaning":"a bursting release","meaningCN":"爆炸；爆发","example":"English formed the noun from the Latin stem.","exampleCN":"英语由拉丁词干构成这个名词。"},{"word":"explode","structure":"explodere (Latin verb)","meaning":"to burst; to reject","meaningCN":"爆炸；推翻","example":"The verb keeps both the old and the new sense.","exampleCN":"动词同时保留旧义与新义。"},{"word":"explosive","structure":"explosion + -ive (tending to)","meaning":"able to explode","meaningCN":"爆炸性的","example":"The adjective adds the sense of capacity.","exampleCN":"形容词增添「能力」之意。"},{"word":"explosively","structure":"explosive + -ly (adverb suffix)","meaning":"in an explosive way","meaningCN":"爆发性地","example":"The adverb marks manner.","exampleCN":"副词标出方式。"},{"word":"explosiveness","structure":"explosive + -ness (quality)","meaning":"the quality of exploding","meaningCN":"爆炸性","example":"The noun names the quality.","exampleCN":"名词指这种性质。"}],"latinEntries":[{"word":"plaudere","structure":"plaudere, plausi, plausum (verb, third conjugation)","meaning":"to clap, to strike","meaningCN":"拍手；击打"},{"word":"explodere","structure":"explodere, explosi, explosum (verb, third conjugation)","meaning":"to drive off by clapping","meaningCN":"以掌声赶走"},{"word":"explosio","structure":"explosio, explosionis (f., third declension)","meaning":"a driving off; a bursting","meaningCN":"赶走；爆裂"}]}},{"word":"black hole","ipa_uk":"/ˌblæk ˈhəʊl/","ipa_us":"/ˌblæk ˈhoʊl/","definition_zh":"黑洞；引力强到连光也无法逃逸的时空区域；也比喻只进不出的消耗处","definition_en":"a region of space where gravity is so strong that nothing, not even light, can escape","core_image":"一张绷紧的黑布中间塌下去一个深不见底的漏斗，连光线走到边缘都拐弯落进去","scene":"讲解引力强到连光也逃不出去的物体，你说 Nothing escapes a black hole.","sceneCN":"这里 black hole 指「引力极强、连光也无法逃逸的时空区域」（第 1 个义项：黑洞这一物理区域）；句意为没有任何东西能逃出黑洞。图中可辨识物件：塌陷的黑色漏斗、弯折的光线、围绕的吸积盘、事件视界虚线。","pos":[{"tag":"n.","zh":"黑洞（可数；天文学术语，亦作定语，如 black hole merger）"}],"collocations":[{"phrase":"a stellar-mass black hole","zh":"恒星级质量黑洞"},{"phrase":"a supermassive black hole","zh":"超大质量黑洞"},{"phrase":"the event horizon of a black hole","zh":"黑洞的事件视界"},{"phrase":"a black hole merger","zh":"黑洞并合"},{"phrase":"fall into a black hole","zh":"落入黑洞"},{"phrase":"the shadow of a black hole","zh":"黑洞的阴影"}],"forms":[{"label":"复数","form":"black holes"},{"label":"相关术语","form":"event horizon（事件视界）"},{"label":"相关术语","form":"singularity（奇点）"},{"label":"相关类型","form":"stellar-mass black hole（恒星级黑洞）"},{"label":"相关类型","form":"supermassive black hole（超大质量黑洞）"},{"label":"相关复合词","form":"black-hole binary（黑洞双星）"}],"derivatives":[{"word":"blacken","pos":"v.","zh":"black + -en：使变黑；由前半 black 加动词后缀构成"},{"word":"blackness","pos":"n.","zh":"black + -ness：黑；黑暗；前半的名词化"},{"word":"holey","pos":"adj.","zh":"hole + -y：多孔的；由后半 hole 加形容词后缀构成"},{"word":"black-hole merger","pos":"n.","zh":"black hole + merger：黑洞并合；由本词构成的复合名词"}],"senses":[{"no":"01","title":"A region no light can leave","titleCN":"连光也无法逃逸的时空区域","definition":"a region of space whose gravity prevents light and matter from escaping","definitionCN":"引力使光与物质都无法逃出的空间区域","example":"Nothing escapes a black hole.","exampleCN":"没有任何东西能逃出黑洞。","why":"the name is a description, not a metaphor: the object is black because no light comes back, and it is a hole because things fall in and do not return.","whyCN":"这个名字是描述而非比喻：天体呈黑色，因为没有光返回；说它是洞，因为东西掉进去就出不来。"},{"no":"02","title":"A collapsed massive star","titleCN":"恒星级黑洞：大质量恒星坍缩后的残留","definition":"a black hole formed when the core of a very massive star collapses at the end of its life","definitionCN":"极大质量恒星生命终结、核心坍缩后形成的黑洞","example":"Cygnus X-1 is a stellar-mass black hole.","exampleCN":"天鹅座 X-1 是一个恒星级黑洞。","why":"stellar-mass marks the origin: the mass came from one star, so the object weighs only a few suns.","whyCN":"stellar-mass 标出来源：质量来自一颗恒星，因此这类黑洞只有几个太阳的质量。"},{"no":"03","title":"The giant at a galaxy's centre","titleCN":"星系中心的超大质量黑洞","definition":"a black hole with millions or billions of solar masses, found at the centre of most large galaxies","definitionCN":"质量达数百万至数十亿个太阳、位于多数大星系中心的黑洞","example":"The supermassive black hole at the centre of our galaxy is quiet now.","exampleCN":"我们星系中心的超大质量黑洞如今很安静。","why":"supermassive is a scale label: it says nothing about origin, only that no single star could supply so much mass.","whyCN":"supermassive 是尺度标签：它不说明起源，只表示单颗恒星无法提供这么多质量。"},{"no":"04","title":"The boundary called the event horizon","titleCN":"事件视界：不归点的边界","definition":"the surface around a black hole beyond which no escape is possible","definitionCN":"黑洞周围、越过之后无法逃逸的界面","example":"The event horizon marks the point of no return.","exampleCN":"事件视界标出不归点。","why":"horizon is borrowed from the line where earth and sky seem to meet, because both are boundaries past which nothing can be seen.","whyCN":"horizon 借自天地相接的那条线，因为两者都是越过之后看不见任何东西的边界。"},{"no":"05","title":"A disk of infalling matter","titleCN":"吸积盘：物质盘旋落入的过程","definition":"the hot disk of matter spiralling inward and emitting radiation before it falls in","definitionCN":"物质在落入前盘旋、发热并发出辐射的盘","example":"The accretion disk outshines the black hole itself.","exampleCN":"吸积盘比黑洞本身亮得多。","why":"accretion means growing by addition: the hole is invisible, so what astronomers see is the meal, not the mouth.","whyCN":"accretion 意为「靠添加而增长」：黑洞本身不可见，天文学家看到的是那顿饭，而非那张嘴。"},{"no":"06","title":"Two black holes merging","titleCN":"黑洞并合与引力波","definition":"the event in which two black holes spiral together, merge and radiate gravitational waves","definitionCN":"两个黑洞相互旋近、并合并辐射引力波的事件","example":"The first detected black hole merger occurred billions of years ago.","exampleCN":"首次探测到的黑洞并合发生在数十亿年前。","why":"the merger is known by its ripples: the collision shakes spacetime, and the signal reaches earth as a wave.","whyCN":"并合是靠涟漪被知道的：碰撞震动时空，信号以波的形式抵达地球。"},{"no":"07","title":"Figurative: an endless drain","titleCN":"比喻义：只进不出的消耗处","definition":"a figurative use for something that absorbs money or resources without ever returning value","definitionCN":"比喻不断吞掉金钱或资源、从不产出价值的事物","example":"The project became a black hole for the budget.","exampleCN":"这个项目成了预算的黑洞。","why":"the metaphor keeps the one-way flow: what goes in does not come out, and nothing about it can be seen.","whyCN":"这个比喻保留单向流动：进去的出不来，而且什么也看不见。"},{"no":"08","title":"Jargon: where data vanishes","titleCN":"行话：数据或消息有去无回之处","definition":"an informal use for a system or mailbox into which messages or data disappear without a trace","definitionCN":"消息或数据进去后毫无踪迹地消失的系统或信箱","example":"My complaint went into a black hole at the agency.","exampleCN":"我的投诉在机构里进了一个黑洞。","why":"the computing use is a joke built on the physics: an address that accepts everything and returns nothing.","whyCN":"计算机行话是建立在物理上的玩笑：一个来者不拒、从不回音的地址。"}],"etymology":{"intro":{"en":"Black hole joins two native English words, black and hole, and was adopted as an astronomical term in the twentieth century. There is no Latin source for either half. Dates are approximate.","cn":"black hole 由两个英语本族词 black 与 hole 组合，20 世纪被采用为天文术语。两半都没有拉丁来源。年代均为约数。"},"items":[{"era":"OLD ENGLISH BLACK","en":"Black descends from Old English blæc 'black, dark' and belongs to the Germanic stock; it has no Latin source.","cn":"black 承自古英语 blæc「黑、暗」，属日耳曼词集，没有拉丁来源。"},{"era":"OLD ENGLISH HOLE","en":"Hole descends from Old English hol, originally an adjective meaning 'hollow', and is also native Germanic.","cn":"hole 承自古英语 hol，原为形容词「中空的」，同样属本族日耳曼语。"},{"era":"THE EARLIER IDEA","en":"In 1783 John Michell reasoned that a body dense enough could trap its own light; the concept existed long before the name.","cn":"1783 年约翰·米歇尔推断，足够致密的天体能困住自己的光；概念远早于名称出现。"},{"era":"THE NAME","en":"The exact phrase black hole is generally attributed to the 1960s, and is often connected with the science writer Ann Ewing; it spread quickly after 1967.","cn":"black hole 这一确切说法一般认为出现于 1960 年代，常与科学作家安·尤因联系在一起；1967 年后迅速传播。"},{"era":"THE MODERN MEANING","en":"The term settled once general relativity described such objects as regions of curved spacetime rather than as dark stars.","cn":"当广义相对论把这类天体描述为弯曲时空的区域、而非暗星之后，这个术语才定型。"},{"era":"UNCERTAIN DETAILS","en":"Root uncertainty: neither half has a disputed root, and no Latin entry applies. First-date uncertainty only: the earliest printed use of the exact phrase is not fully documented, and the 1960s attribution is generally believed rather than proven.","cn":"词根存疑：两半都没有争议性词根，不涉及重构形式，故不列拉丁条目。仅首见年代存疑：这一确切短语的最早印刷用例没有完整记录，1960 年代的说法一般认为成立但未获证明。"}]},"similar":{"note":{"en":"Group one holds the exotic objects and boundaries that look like a black hole; group two holds its neighbouring remnants and its figurative equivalents.","cn":"第一组是看起来像黑洞的奇异天体与边界；第二组是邻近的遗骸与比喻近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"white hole","ipa":"/waɪt həʊl/","tag":"the hypothetical reverse","definition":"A mathematical opposite in which nothing can enter; no such object has been observed, so it is a theoretical construct.","definitionCN":"数学上的相反物，任何东西都进不去；尚无观测，属理论构造。"},{"word":"wormhole","ipa":"/ˈwɜːmhəʊl/","tag":"a hypothetical shortcut","definition":"A hypothetical tunnel through spacetime; it is a passage, not a region that traps light.","definitionCN":"假设中的时空隧道；是通道，而非困住光的区域。"},{"word":"event horizon","ipa":"/ɪˈvent həˈraɪzən/","tag":"the boundary, not the object","definition":"The surface of no return around a black hole; the phrase names the edge, while black hole names the whole region.","definitionCN":"黑洞周围的不归界面；短语指边缘，black hole 指整个区域。"}]},{"heading":"NEAR MEANING","entries":[{"word":"neutron star","ipa":"/ˈnjuːtrɒn stɑː/","tag":"a dense remnant","definition":"The collapsed core left by some supernovae; it is extremely dense but still lets light escape.","definitionCN":"某些超新星留下的坍缩核心；极其致密，但光仍能逃出。"},{"word":"singularity","ipa":"/ˌsɪŋɡjuˈlærəti/","tag":"the centre","definition":"The point where the mathematics breaks down, at the centre of a black hole; it is not the whole object.","definitionCN":"黑洞中心数学失效的那一点；不是整个天体。"},{"word":"money pit","ipa":"/ˈmʌni pɪt/","tag":"the figurative equivalent","definition":"An informal phrase for something that absorbs money endlessly; it carries the same sense as the figurative black hole.","definitionCN":"指不断吞钱之物的非正式说法；与黑洞的比喻义相同。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"black + hole: a hole that returns no light.","cn":"black + hole：一个不返回光的洞。"},{"en":"Three sizes: stellar-mass, intermediate, supermassive.","cn":"三种尺度：恒星级、中等质量、超大质量。"},{"en":"The boundary is the event horizon.","cn":"边界叫事件视界。"},{"en":"The visible part is the accretion disk.","cn":"看得见的部分是吸积盘。"},{"en":"Mergers are detected through gravitational waves.","cn":"并合通过引力波被探测到。"}],"abstract":[{"en":"Picture a funnel in a tight sheet, so steep that a marble can never climb back.","cn":"想象绷紧的布上有个漏斗，陡到弹珠再也爬不回来。"},{"en":"Picture a drain that takes every coin in the house and gives none back.","cn":"想象一个下水口吞掉家里所有硬币，一枚也不还。"},{"en":"Picture a mailbox that accepts letters forever and answers none.","cn":"想象一个永远收信却从不回信的信箱。"}]},"examples":[{"en":"The black hole at the centre of the galaxy has about four million solar masses.","cn":"这个星系中心的黑洞约有四百万个太阳质量。"},{"en":"Matter falling toward a black hole forms a bright accretion disk.","cn":"落向黑洞的物质形成明亮的吸积盘。"},{"en":"The 2019 image showed the shadow of a supermassive black hole.","cn":"2019 年的图像显示了超大质量黑洞的阴影。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「black（黑）+ hole（洞）」——连光都出不来的黑洞口 → 黑洞","word":"black hole"},"root":"古英语 blæc「黑」+ 古英语 hol「中空的、洞」，均为本族日耳曼词，无拉丁来源；术语 black hole 一般认为出现于 1960 年代。","sensesIntro":{"en":"Eight senses follow one trap: a region that keeps its light, the two ways such regions form, the edge and the meal around them, the collision of two of them, and finally the money pit and the mailbox that also never give back.","cn":"八个义项沿同一个「陷阱」展开：一片扣住光的区域；这种区域的形成方式、边界与周围的「餐盘」、两个这样的区域相撞，最后是同样只进不出的钱坑与信箱。"},"semanticMap":{"core":{"en":"CORE IMAGE: a deep funnel in a taut sheet, with light bending into it.","cn":"核心意象：绷紧布面上一个很深的漏斗，光弯着落进去。"},"chain":["LIGHT TRAPPED","STAR COLLAPSE","GIANT CENTRE","POINT OF NO RETURN","DISK FEEDS","MERGER RIPPLES"],"branches":[{"senses":"S1 · S4","en":"THE TRAP AND ITS EDGE: the region that keeps light, and the surface where escape ends.","cn":"陷阱与边缘：扣住光的区域，以及逃逸终止的界面。"},{"senses":"S2 · S6","en":"BORN FROM STARS, FOUND BY RIPPLES: collapse makes one, merger announces two.","cn":"由恒星而生、由涟漪而被发现：坍缩造出一个，并合宣告两个。"},{"senses":"S3","en":"THE GIANT AT THE CENTRE: a scale no single star could supply.","cn":"中心的巨物：单颗恒星无法提供的尺度。"},{"senses":"S5","en":"THE MEAL: the bright disk is what can actually be seen.","cn":"那顿饭：真正能被看见的是明亮的盘。"},{"senses":"S7 · S8","en":"THE METAPHORS: money and messages that go in and never come out.","cn":"比喻：进去后永不出来的金钱与消息。"}]},"affixes":{"intro":{"en":"The phrase is built from two native English free forms; there is no Latin root to split, and the words combine without a suffix.","cn":"这个短语由两个英语本族自由词形构成；没有可拆分的拉丁词根，两词直接组合，不加后缀。"},"latinIntro":{"en":"No Latin entry applies to either half: black and hole are Germanic, so the Latin list is intentionally empty. The technical vocabulary around the term is Latin-derived, as in event horizon and accretion.","cn":"两半都不适用拉丁条目：black 与 hole 属日耳曼语，故拉丁条目有意留空。围绕该术语的技术词汇则来自拉丁语，如 event horizon 与 accretion。"},"items":[{"word":"black","structure":"Old English blæc (native adjective)","meaning":"black, dark","meaningCN":"黑的；暗的","example":"The first half is a free native adjective.","exampleCN":"前半是自由的本族形容词。"},{"word":"hole","structure":"Old English hol (native noun)","meaning":"a hollow place","meaningCN":"洞；孔","example":"The second half is a free native noun.","exampleCN":"后半是自由的本族名词。"},{"word":"black hole","structure":"black + hole","meaning":"a region that traps light","meaningCN":"黑洞","example":"The compound is fixed as a technical term.","exampleCN":"这个复合词固定为术语。"},{"word":"event horizon","structure":"event + horizon","meaning":"the boundary of no return","meaningCN":"事件视界","example":"Horizon came through Latin and Greek.","exampleCN":"horizon 经拉丁与希腊语传入。"},{"word":"singularity","structure":"singular + -ity","meaning":"the centre point","meaningCN":"奇点","example":"The suffix marks a state or quality.","exampleCN":"后缀标出状态或性质。"},{"word":"accretion","structure":"accretio (Latin)","meaning":"growth by addition","meaningCN":"吸积；增生","example":"The disk grows by adding matter.","exampleCN":"盘靠添加物质而增长。"},{"word":"supermassive","structure":"super- + massive","meaning":"beyond massive","meaningCN":"超大质量的","example":"The prefix marks a scale class.","exampleCN":"这个前缀标出尺度等级。"},{"word":"blacken","structure":"black + -en","meaning":"to make black","meaningCN":"使变黑","example":"The suffix turns the adjective into a verb.","exampleCN":"后缀把形容词变为动词。"},{"word":"blackness","structure":"black + -ness","meaning":"the state of being black","meaningCN":"黑；黑暗","example":"The suffix names the quality.","exampleCN":"后缀指这种性质。"}],"latinEntries":[]}},{"word":"gravitation","ipa_uk":"/ˌɡrævɪˈteɪʃn/","ipa_us":"/ˌɡrævɪˈteɪʃn/","definition_zh":"引力；万有引力；被吸引而趋近的作用或趋势","definition_en":"the force by which bodies attract one another, or the tendency to move toward something","core_image":"两只铁球之间那根看不见的绳把彼此慢慢拉近，桌上散落的碎屑也跟着滚向它们","scene":"把苹果落地说成万物互相吸引，你说 Gravitation holds the planets in their orbits.","sceneCN":"这里 gravitation 指「物体之间相互吸引的作用」（第 2 个义项：支配天体运动的万有引力）；句意为引力使行星保持在轨道上。图中可辨识物件：行星轨道、中心恒星、看不见的拉力线、苹果。","pos":[{"tag":"n.","zh":"引力；万有引力；吸引趋势（不可数）"}],"collocations":[{"phrase":"universal gravitation","zh":"万有引力"},{"phrase":"Newton's law of gravitation","zh":"牛顿引力定律"},{"phrase":"the gravitation of bodies","zh":"物体之间的引力"},{"phrase":"gravitation toward a career","zh":"对某种职业的吸引"},{"phrase":"the gravitation of public opinion","zh":"舆论的趋向"}],"forms":[{"label":"形容词","form":"gravitational"},{"label":"相关名词（重力）","form":"gravity"},{"label":"动词","form":"gravitate"},{"label":"相关粒子（理论）","form":"graviton"},{"label":"反义概念（斥力）","form":"repulsion"},{"label":"相关短语（万有引力）","form":"universal gravitation"}],"derivatives":[{"word":"gravitational","pos":"adj.","zh":"gravitation + -al：引力的"},{"word":"gravitate","pos":"v.","zh":"gravitas 同族 + -ate：被吸引；趋向"},{"word":"gravity","pos":"n.","zh":"gravis + -ity：重力；严重性"},{"word":"graviton","pos":"n.","zh":"gravity + -on（粒子后缀）：引力子（理论假设粒子）"}],"senses":[{"no":"01","title":"The attraction between bodies","titleCN":"物体之间相互吸引的作用","definition":"the force by which any two bodies with mass attract each other","definitionCN":"任何两个有质量的物体相互吸引的作用力","example":"Gravitation pulls the two spheres together.","exampleCN":"引力把两个球体拉近。","why":"the noun comes from Latin gravitas 'weight', because the most familiar sign of this attraction is that things have weight.","whyCN":"这个名词出自拉丁 gravitas「重量」，因为这种吸引最常见的表现就是物体有重量。"},{"no":"02","title":"Universal gravitation","titleCN":"万有引力：支配天体运动的普遍规律","definition":"the principle that every mass attracts every other mass, which governs orbits","definitionCN":"每个质量都吸引其他质量、并支配轨道的原理","example":"Gravitation holds the planets in their orbits.","exampleCN":"引力使行星保持在轨道上。","why":"universal marks the leap from falling apples to moving planets: the same rule was found to work at both scales.","whyCN":"universal 标出从落下的苹果到运行的行星这一跃迁：同一条规则被发现在两个尺度上都成立。"},{"no":"03","title":"Curved spacetime","titleCN":"广义相对论中的时空弯曲","definition":"the modern description in which gravitation is the curvature of spacetime rather than a pull","definitionCN":"现代描述：引力是时空的弯曲，而非一种拉力","example":"In general relativity, gravitation is geometry.","exampleCN":"在广义相对论中，引力就是几何。","why":"the modern sense replaces the pull with a shape: bodies follow the straightest path through curved spacetime.","whyCN":"现代义用形状取代拉力：天体在弯曲时空中走最直的路径。"},{"no":"04","title":"The act of being drawn down","titleCN":"被吸引而落下的过程","definition":"the process of moving toward a mass under its attraction","definitionCN":"在吸引作用下朝某个质量运动的过程","example":"The gravitation of the cloud collapsed it into a disk.","exampleCN":"云气的引力坍缩把它压成一个盘。","why":"the noun can name the process as well as the force, which is why astronomers speak of gravitation acting on a cloud.","whyCN":"这个名词既可指力，也可指过程，因此天文学家会说引力作用于云气。"},{"no":"05","title":"Mutual attraction between people","titleCN":"人与人之间的相互吸引","definition":"a figurative use for the mutual draw between people","definitionCN":"比喻人与人之间相互吸引","example":"There was a strange gravitation between the two strangers.","exampleCN":"两个陌生人之间有一种奇怪的吸引。","why":"the physical pull becomes social: two people move toward each other without any visible force.","whyCN":"物理的拉力转为社交义：两个人没有任何可见的力也彼此靠近。"},{"no":"06","title":"A drift of opinion","titleCN":"舆论或趋势的倾向","definition":"a tendency of opinion or activity to move toward a particular point","definitionCN":"意见或活动朝某一特定方向移动的倾向","example":"The gravitation of voters toward the centre changed the race.","exampleCN":"选民向中间靠拢的趋势改变了选情。","why":"once a group is imagined as masses, its drift is described with the same word as a falling body.","whyCN":"一旦把群体想象成许多质量，它的漂移就用与落体相同的词来描述。"},{"no":"07","title":"Gravitational collapse","titleCN":"引力坍缩与束缚","definition":"the process by which gravity causes a cloud or a star to collapse and bind matter","definitionCN":"引力使云气或恒星坍缩并把物质束缚起来的过程","example":"Gravitation overcame the pressure and the core collapsed.","exampleCN":"引力压过了压力，核心坍缩了。","why":"collapse is gravitation winning: the inward pull exceeds every outward push, and the object shrinks.","whyCN":"坍缩就是引力获胜：向内的拉力超过一切向外的推力，天体于是缩小。"},{"no":"08","title":"The older sense of weighing","titleCN":"旧义：称重或有重量","definition":"an older physical use for the act of weighing or the state of having weight","definitionCN":"旧物理用法：称重的动作或有重量的状态","example":"Early texts used gravitation for the act of weighing a body.","exampleCN":"早期文献用 gravitation 指称量物体的动作。","why":"the oldest sense is literal: gravitas is weight, so gravitation first named the business of weighing.","whyCN":"最古老的义项是字面的：gravitas 就是重量，因此 gravitation 最初指称重这件事。"}],"etymology":{"intro":{"en":"Gravitation comes from Latin gravitas 'weight, heaviness', from gravis 'heavy', with the noun suffix -ation. Newton made it the name of a universal force in the seventeenth century. Dates are approximate.","cn":"gravitation 出自拉丁 gravitas「重量、沉重」，源于 gravis「重的」，加名词后缀 -ation。牛顿在 17 世纪使它成为普遍力的名称。年代均为约数。"},"items":[{"era":"LATIN GRAVIS","en":"Gravis meant 'heavy, weighty, serious', and also 'burdensome'; its deeper Indo-European origin is a reconstruction rather than an attested form.","cn":"gravis 意为「重的、有分量的、严肃的」，也指「令人负担的」；其更深的印欧来源属重构，而非有书证的形式。"},{"era":"LATIN GRAVITAS","en":"Gravitas 'weight, heaviness, seriousness' supplied English gravity and gave the stem for gravitation.","cn":"gravitas「重量、沉重、严肃」提供英语 gravity，并给出 gravitation 的词干。"},{"era":"NEWTON","en":"The noun is recorded before Newton, but his Principia of 1687 set out universal gravitation and made gravitation the standard English name for the force acting between all masses.","cn":"这个名词在牛顿之前已有记录，但他 1687 年的《原理》阐述了万有引力，并使 gravitation 成为英语中指所有质量间作用力的标准名称。"},{"era":"THE RELATIVISTIC SENSE","en":"After 1915 general relativity reinterpreted gravitation as the curvature of spacetime, and the older noun was kept for the same set of phenomena.","cn":"1915 年广义相对论把引力重新解释为时空弯曲，旧名词仍用于同一组现象。"},{"era":"THE FIGURATIVE SPREAD","en":"From the nineteenth century the word was applied to social and psychological attraction, where bodies are replaced by people and opinions.","cn":"从 19 世纪起，这个词被用于社会与心理层面的吸引，其中的物体被换成人与意见。"},{"era":"UNCERTAIN DETAILS","en":"Root uncertainty: the Indo-European shape behind gravis is a reconstruction. First-date uncertainty only: the earliest English use of gravitation in the physical sense is not precisely dated, and the seventeenth-century attribution follows Newton's publication rather than a printed first use.","cn":"词根存疑：gravis 背后的印欧形态属重构。仅首见年代存疑：gravitation 物理义最早的英语用例没有确切年代，17 世纪之说依据的是牛顿的出版而非某个最早印刷用例。"}]},"similar":{"note":{"en":"Group one holds the words of the same weight stock that are routinely confused; group two holds the neighbouring terms for the force and its effects.","cn":"第一组是同出「重」词干、常被混淆的词；第二组是邻近的力与效应术语。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gravity","ipa":"/ˈɡrævəti/","tag":"the force, or seriousness","definition":"The everyday noun for the force, and also for seriousness; gravitation is the formal term for the universal relation between masses.","definitionCN":"日常指这种力的名词，也指严肃；gravitation 是质量之间普遍关系的正式术语。"},{"word":"gravitational","ipa":"/ˌɡrævɪˈteɪʃənl/","tag":"the adjective","definition":"The adjective formed from gravitation, as in gravitational waves; it cannot stand alone as a noun.","definitionCN":"由 gravitation 构成的形容词，如引力波；不能单独作名词。"},{"word":"gravitate","ipa":"/ˈɡrævɪteɪt/","tag":"to be drawn toward","definition":"The verb meaning to move toward something by attraction, used mostly of people and preferences.","definitionCN":"指受吸引而趋向某物的动词，多用于人与偏好。"}]},{"heading":"NEAR MEANING","entries":[{"word":"attraction","ipa":"/əˈtrækʃn/","tag":"a general pull","definition":"Any force or tendency that draws things together, including magnetism and liking; gravitation is the specific mass-to-mass case.","definitionCN":"任何使事物靠近的力或倾向，包括磁力与好感；gravitation 专指质量之间的情形。"},{"word":"gravitational force","ipa":"/ˌɡrævɪˈteɪʃənl fɔːs/","tag":"the force phrase","definition":"The explicit phrase naming the force; gravitation can name the phenomenon or the theory, so the two overlap but are not identical.","definitionCN":"明确指该力的短语；gravitation 可指现象或理论，两者重叠但不完全相同。"},{"word":"weight","ipa":"/weɪt/","tag":"the local effect","definition":"The force a body feels in a particular gravitational field; it is a measurement, not the universal relation.","definitionCN":"物体在特定引力场中受到的力；它是一种测量值，不是那条普遍关系。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Latin gravis 'heavy' + -ation: the business of heaviness.","cn":"拉丁 gravis「重」+ -ation：关于「重」的事。"},{"en":"Fixed phrases: universal gravitation, Newton's law of gravitation.","cn":"固定短语：万有引力、牛顿引力定律。"},{"en":"The family runs gravity, gravitational, gravitate, graviton.","cn":"同族词包括 gravity、gravitational、gravitate、graviton。"},{"en":"Every mass attracts every other mass.","cn":"每个质量都吸引其他质量。"},{"en":"General relativity turns the pull into curvature.","cn":"广义相对论把拉力变成弯曲。"}],"abstract":[{"en":"Picture crumbs on a table all drifting toward one heavy bowl.","cn":"想象桌上的碎屑都朝一个沉重的碗漂去。"},{"en":"Picture two strangers crossing a room without deciding to.","cn":"想象两个陌生人没打定主意却相互走近。"},{"en":"Picture a crowd slowly leaning toward one side of a square.","cn":"想象人群慢慢朝广场的一侧倾靠。"}]},"examples":[{"en":"Universal gravitation explains both the fall of an apple and the orbit of the moon.","cn":"万有引力既能解释苹果落地，也能解释月球的轨道。"},{"en":"Gravitation caused the gas cloud to collapse into a disk.","cn":"引力使气体云坍缩成一个盘。"},{"en":"Under general relativity, gravitation is described as curved spacetime.","cn":"在广义相对论下，引力被描述为弯曲的时空。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「gravity（重力）+ ation」——重的东西彼此拉近 → 引力","word":"gravitation"},"root":"拉丁 gravitas「重量」← gravis「重的」+ -ation；牛顿 1687 年《原理》确立万有引力之名；gravis 的印欧来源属重构形式。","sensesIntro":{"en":"Eight senses follow one pull: masses attract, the rule becomes universal, spacetime curves, matter falls and collapses, people and opinions drift, and an older sense still remembers that the word first meant weighing.","cn":"八个义项沿同一种拉力展开：质量相互吸引；规则变得普遍、时空弯曲、物质下落与坍缩、人与意见漂移，最后一个旧义仍记得这个词最初指称重。"},"semanticMap":{"core":{"en":"CORE IMAGE: an invisible cord between two heavy balls, drawing crumbs along the table toward them.","cn":"核心意象：两个重球之间一根看不见的绳，把桌上的碎屑也拉向它们。"},"chain":["MASS ATTRACTS","UNIVERSAL RULE","CURVED SPACE","FALLING INWARD","COLLAPSE","SOCIAL DRIFT"],"branches":[{"senses":"S1","en":"THE PLAIN FORCE: masses attract one another.","cn":"朴素的力：质量相互吸引。"},{"senses":"S2 · S3","en":"FROM LAW TO GEOMETRY: the universal rule, then curvature.","cn":"从定律到几何：普遍规律，再到时空弯曲。"},{"senses":"S4 · S7","en":"MOVEMENT AND COLLAPSE: falling toward a mass, and the inward win that shrinks a cloud.","cn":"运动与坍缩：朝质量下落，以及使云气缩小的向内胜利。"},{"senses":"S5 · S6","en":"DRAWN WITHOUT A FORCE: people and opinions drift together.","cn":"没有力也被吸引：人与意见一起漂移。"},{"senses":"S8","en":"THE OLD WEIGHING: the word once named the act of weighing.","cn":"旧日的称重：这个词曾指称重的动作。"}]},"affixes":{"intro":{"en":"Gravitation is a Latin adjective stem plus a noun suffix; the same gravis family supplies gravity and gravitate, and the suffix -ation is highly productive.","cn":"gravitation 是拉丁形容词词干加名词后缀；同一 gravis 词族给出 gravity 与 gravitate，后缀 -ation 构词力很强。"},"latinIntro":{"en":"Latin gravis and gravitas give gravity, gravitation and gravitate; the particle name graviton adds a Greek-style -on suffix.","cn":"拉丁 gravis 与 gravitas 给出 gravity、gravitation、gravitate；粒子名 graviton 加的是希腊式的 -on 后缀。"},"items":[{"word":"gravis","structure":"gravis, gravis, grave (Latin adjective)","meaning":"heavy, weighty","meaningCN":"重的；有分量的","example":"The root also gives grave in the sense of serious.","exampleCN":"这个词根也给出 grave「严肃的」一义。"},{"word":"gravitas","structure":"gravitas, gravitatis (Latin noun, third declension)","meaning":"weight, seriousness","meaningCN":"重量；严肃","example":"The noun supplies the stem of gravitation.","exampleCN":"这个名词提供 gravitation 的词干。"},{"word":"-ation","structure":"-atio, -ationis (Latin noun suffix)","meaning":"action or process","meaningCN":"动作或过程","example":"The suffix turns the noun into the name of a process.","exampleCN":"这个后缀把名词变为过程之名。"},{"word":"gravitation","structure":"gravitas + -ation","meaning":"the process of being heavy or drawn","meaningCN":"引力；吸引过程","example":"English built the noun on the Latin stem.","exampleCN":"英语在拉丁词干上构成这个名词。"},{"word":"gravity","structure":"gravis + -ity","meaning":"heaviness; the force","meaningCN":"重力；严重性","example":"The shorter noun keeps the everyday sense.","exampleCN":"较短的名词保留日常义。"},{"word":"gravitational","structure":"gravitation + -al","meaning":"of gravitation","meaningCN":"引力的","example":"The adjective is formed in English.","exampleCN":"这个形容词在英语中构成。"},{"word":"gravitate","structure":"gravitas + -ate","meaning":"to move toward","meaningCN":"被吸引；趋向","example":"The verb is mostly figurative today.","exampleCN":"这个动词如今多用于比喻。"},{"word":"graviton","structure":"gravity + -on","meaning":"a hypothetical particle","meaningCN":"引力子","example":"The suffix is modelled on electron and photon.","exampleCN":"这个后缀模仿 electron 与 photon。"},{"word":"repulsion","structure":"re- + pulsio (Latin)","meaning":"a pushing apart","meaningCN":"排斥","example":"The prefix and root reverse the pull.","exampleCN":"前缀与词根反转了拉力。"}],"latinEntries":[{"word":"gravis","structure":"gravis, gravis, grave (adjective, third declension)","meaning":"heavy, weighty, serious","meaningCN":"重的；有分量的；严肃的"},{"word":"gravitas","structure":"gravitas, gravitatis (f., third declension)","meaning":"weight, heaviness","meaningCN":"重量；沉重"}]}},{"word":"gravitational force","ipa_uk":"/ˌɡrævɪˈteɪʃənl ˈfɔːs/","ipa_us":"/ˌɡrævɪˈteɪʃənl ˈfɔːrs/","definition_zh":"引力；万有引力作用力；（口语）不可抗拒的吸引力","definition_en":"the attractive force between bodies with mass, or a figurative irresistible pull","core_image":"月亮被一根看不见的力线牵在地球旁边，力线的箭头指向地心","scene":"讲解月亮为何绕地球转，你说 Gravitational force keeps the moon in orbit.","sceneCN":"这里 gravitational force 指「有质量的物体之间的吸引力」（第 1 个义项：两质量之间的引力）；句意为引力使月球保持在轨道上。图中可辨识物件：地球、月球、指向地心的力箭头、轨道弧线。","pos":[{"tag":"n.","zh":"引力；万有引力作用力；（口语）不可抗拒的吸引力"}],"collocations":[{"phrase":"the gravitational force of the earth","zh":"地球的引力"},{"phrase":"a weak gravitational force","zh":"微弱的引力"},{"phrase":"balance the gravitational force","zh":"平衡引力"},{"phrase":"the gravitational force between two masses","zh":"两个质量之间的引力"},{"phrase":"feel the gravitational force","zh":"感受到引力"}],"forms":[{"label":"复数","form":"gravitational forces"},{"label":"形容词","form":"gravitational"},{"label":"相关名词","form":"gravitation"},{"label":"相关名词（重力）","form":"gravity"},{"label":"动词","form":"gravitate"},{"label":"相关术语（引力波）","form":"gravitational wave"}],"derivatives":[{"word":"gravitational","pos":"adj.","zh":"gravitation + -al：引力的"},{"word":"gravitation","pos":"n.","zh":"gravitas + -ation：引力；吸引"},{"word":"gravitate","pos":"v.","zh":"gravitas 同族 + -ate：趋向；被吸引"},{"word":"gravity","pos":"n.","zh":"gravis + -ity：重力；严重性"}],"senses":[{"no":"01","title":"The attractive force between masses","titleCN":"有质量物体之间的吸引力","definition":"the force with which any two bodies attract each other because of their mass","definitionCN":"任何两个有质量物体因质量而相互吸引的力","example":"Gravitational force keeps the moon in orbit.","exampleCN":"引力使月球保持在轨道上。","why":"the phrase spells out what gravitation names in the abstract: a force, acting between masses, and always attractive.","whyCN":"这个短语把 gravitation 抽象指称的东西说清楚：一种力，作用于质量之间，且总是吸引。"},{"no":"02","title":"The inverse-square law","titleCN":"平方反比定律：力随距离平方衰减","definition":"the law stating that the force falls with the square of the distance between the bodies","definitionCN":"力随两物体间距离的平方而减小的定律","example":"The gravitational force drops to a quarter when the distance doubles.","exampleCN":"距离加倍时引力减到四分之一。","why":"geometry does the work: the same influence spread over a sphere four times larger is four times weaker.","whyCN":"起作用的是几何：同样的影响摊到四倍大的球面上，就弱了四倍。"},{"no":"03","title":"Weight as a local force","titleCN":"重量：物体在特定引力场中受到的力","definition":"the force a body experiences in a particular gravitational field, measured as its weight","definitionCN":"物体在特定引力场中受到、以重量计量的力","example":"The gravitational force on the probe is weaker far from the sun.","exampleCN":"远离太阳时，探测器受到的引力更弱。","why":"weight is the local reading of the force: the same body feels different gravitational force on different planets.","whyCN":"重量是这种力的局部读数：同一个物体在不同行星上感受到不同的引力。"},{"no":"04","title":"The tidal difference","titleCN":"潮汐力：物体两端受力不均","definition":"the difference in gravitational force across a body, which stretches it","definitionCN":"横跨一个物体两端的引力差异，会把它拉长","example":"The gravitational force of the moon raises two tides a day.","exampleCN":"月球的引力每天造成两次潮汐。","why":"a tide appears because the near side is pulled harder than the far side, so the difference matters as much as the total.","whyCN":"潮汐的出现是因为近侧比远侧被拉得更紧，因此差值跟总量同样重要。"},{"no":"05","title":"The weakest of the four forces","titleCN":"四种基本力中最弱、作用距离最长的一种","definition":"the weakest of the four fundamental interactions, yet the one with unlimited range","definitionCN":"四种基本相互作用中最弱、但作用距离不受限的一种","example":"Gravitational force is weak, but it never cancels out.","exampleCN":"引力很弱，但它从不相互抵消。","why":"it is weak per particle and strong in bulk: mass adds up, and there is no negative mass to cancel it.","whyCN":"就单个粒子而言它很弱，成团时却很强：质量会累加，又没有负质量来抵消。"},{"no":"06","title":"Balancing an orbit","titleCN":"轨道中与运动相平衡的力","definition":"the force that supplies the inward pull needed to keep a body in orbit","definitionCN":"为维持天体在轨道上所需的向内拉力","example":"The gravitational force provides exactly the pull the orbit needs.","exampleCN":"引力恰好提供了轨道所需的拉力。","why":"an orbit is a balance: the inward force bends the path just enough that the body never lands and never leaves.","whyCN":"轨道是一种平衡：向内的力把路径弯得刚好，使天体既不落地也不飞走。"},{"no":"07","title":"Figurative: an irresistible pull","titleCN":"比喻义：不可抗拒的吸引力","definition":"a figurative use for a person or thing that draws others irresistibly","definitionCN":"比喻某人或某物不可抗拒地吸引他人","example":"The old harbour exerts a gravitational force on the whole town.","exampleCN":"旧港对整座城镇有一种引力般的吸引。","why":"the metaphor keeps two features: the pull is invisible and it acts at a distance.","whyCN":"这个比喻保留两个特征：拉力不可见，且能隔空起作用。"},{"no":"08","title":"A force only by approximation","titleCN":"广义相对论中的再解释：力只是近似说法","definition":"the modern note that in general relativity this 'force' is a description of curved paths, not a push or pull","definitionCN":"现代注脚：在广义相对论中，这个「力」只是对弯曲路径的描述，而非推或拉","example":"In general relativity the gravitational force is a bookkeeping device.","exampleCN":"在广义相对论中，引力只是一种记账手段。","why":"the phrase survives because it is convenient, even though the deeper theory replaces the pull with geometry.","whyCN":"这个短语因方便而留存，尽管更深的理论已用几何取代拉力。"}],"etymology":{"intro":{"en":"Gravitational force joins gravitational, from Latin gravitas 'weight', to force, from Latin fortis 'strong' through Old French. The phrase is a modern physics label. Dates are approximate.","cn":"gravitational force 把出自拉丁 gravitas「重量」的 gravitational 与经古法语来自拉丁 fortis「强」的 force 并置。这个短语是近代物理标签。年代均为约数。"},"items":[{"era":"LATIN GRAVIS","en":"Gravis 'heavy, weighty' is the root of gravitas and of the whole gravity family; its Indo-European origin is a reconstruction.","cn":"gravis「重的、有分量的」是 gravitas 与整个 gravity 词族的词根；其印欧来源属重构。"},{"era":"LATIN FORTIS","en":"Fortis meant 'strong, powerful', and gave English force through Old French; the noun force names strength in action.","cn":"fortis 意为「强的、有力的」，经古法语给出英语 force；名词 force 指起作用的力量。"},{"era":"THE PHYSICS PHRASE","en":"Gravitational force became standard once Newtonian mechanics needed an explicit name for the interaction, distinct from gravitation as a phenomenon.","cn":"当牛顿力学需要一个明确的名称来指这种相互作用、并与作为现象的 gravitation 区分时，gravitational force 成为标准说法。"},{"era":"THE TIDAL AND ORBITAL USES","en":"Later work on tides and orbits attached the phrase to local differences and to the balance that keeps a body in orbit.","cn":"后来关于潮汐与轨道的工作把这个短语用于局部差异，以及维持天体在轨道上的平衡。"},{"era":"THE RELATIVISTIC NOTE","en":"General relativity kept the phrase as a convenient label while denying that it names a fundamental push or pull.","cn":"广义相对论保留这个短语作为方便标签，同时否认它指某种基本的推或拉。"},{"era":"UNCERTAIN DETAILS","en":"Root uncertainty: the Indo-European shapes behind gravis and fortis are reconstructions. First-date uncertainty only: the earliest printed use of the exact phrase gravitational force is not recorded.","cn":"词根存疑：gravis 与 fortis 背后的印欧形态均属重构。仅首见年代存疑：gravitational force 这一确切短语的最早印刷记录不明。"}]},"similar":{"note":{"en":"Group one holds the weight-family words that are easily swapped; group two holds the related force terms and the figurative near-equivalents.","cn":"第一组是同出「重」词族、容易互换的词；第二组是相关力的术语与比喻近义词。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"gravitation","ipa":"/ˌɡrævɪˈteɪʃn/","tag":"the phenomenon or theory","definition":"The abstract noun for the phenomenon; gravitational force is the explicit phrase for the interaction itself.","definitionCN":"指现象或理论的抽象名词；gravitational force 是明确指这种相互作用的短语。"},{"word":"gravitational","ipa":"/ˌɡrævɪˈteɪʃənl/","tag":"the adjective","definition":"The adjective alone cannot name the force; it needs a noun such as force, wave or lens.","definitionCN":"这个形容词本身不能指该力，须带 force、wave、lens 等名词。"},{"word":"gravity","ipa":"/ˈɡrævəti/","tag":"the everyday noun","definition":"The common noun for the force, also meaning seriousness; the longer phrase is more precise in physics.","definitionCN":"指该力的常用名词，也指严肃；较长的短语在物理中更精确。"}]},{"heading":"NEAR MEANING","entries":[{"word":"weight","ipa":"/weɪt/","tag":"the measured effect","definition":"The force a body feels in a given field; it is the local value of gravitational force, not the general relation.","definitionCN":"物体在给定场中受到的力；它是引力的局部取值，不是普遍关系。"},{"word":"tidal force","ipa":"/ˈtaɪdl fɔːs/","tag":"the difference across a body","definition":"The difference in gravitational force between two points, which stretches an object; it is a special case, not a synonym.","definitionCN":"两点之间引力的差值，会拉长物体；是特例，非同义词。"},{"word":"pull","ipa":"/pʊl/","tag":"the plain verb and noun","definition":"The everyday word for an attracting action; the physics phrase is its technical counterpart.","definitionCN":"指吸引动作的日常词；物理短语是其技术对应语。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"gravitational 'of weight' + force 'strength': the strength that comes with mass.","cn":"gravitational「关于重的」+ force「力」：随质量而来的力。"},{"en":"Fixed collocations: the gravitational force of the earth, between two masses.","cn":"固定搭配：地球的引力、两个质量之间的引力。"},{"en":"It falls off as the square of the distance.","cn":"它随距离的平方衰减。"},{"en":"The family runs gravitation, gravity, gravitate, gravitational wave.","cn":"同族词包括 gravitation、gravity、gravitate、gravitational wave。"},{"en":"Weight is the local reading of the force.","cn":"重量是这种力的局部读数。"}],"abstract":[{"en":"Picture a cord tied from the moon to the centre of the earth.","cn":"想象一根绳把月亮系在地心。"},{"en":"Picture two dancers turning around each other without touching.","cn":"想象两个舞者彼此绕行却不相触。"},{"en":"Picture an old harbour that nobody can quite leave.","cn":"想象一座谁都舍不得离开的旧港。"}]},"examples":[{"en":"The gravitational force between two masses grows as they come closer.","cn":"两个质量之间的引力随距离缩短而增大。"},{"en":"Astronauts feel a weaker gravitational force on the moon.","cn":"宇航员在月球上感受到的引力更弱。"},{"en":"The gravitational force of a black hole bends light around it.","cn":"黑洞的引力使周围的光弯曲。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「gravitational（引力的）+ force（力）」——由质量产生的拉力 → 引力","word":"gravitational force"},"root":"拉丁 gravitas「重量」← gravis「重的」+ 拉丁 fortis「强」经古法语 force；近代物理短语，用于指质量之间的吸引作用。","sensesIntro":{"en":"Eight senses follow one pull: masses attract, distance weakens it, weight measures it locally, tides reveal its difference, it is the weakest of four forces, orbits balance it, people feel it as charm and modern physics calls it geometry.","cn":"八个义项沿同一种拉力展开：质量相吸；距离使它减弱；重量是它的局部度量；潮汐显出它的差值；它是四种力中最弱的；轨道靠它平衡；人们把它感受为魅力；现代物理则称它为几何。"},"semanticMap":{"core":{"en":"CORE IMAGE: an arrow drawn from the moon toward the earth's centre.","cn":"核心意象：一支从月球指向地心的箭头。"},"chain":["MASSES ATTRACT","INVERSE SQUARE","WEIGHT HERE","TIDAL STRETCH","WEAKEST FORCE","ORBIT BALANCE"],"branches":[{"senses":"S1 · S5","en":"THE FORCE ITSELF: always attractive, weak per particle, unlimited in range.","cn":"力本身：总是吸引，单粒子很弱，作用距离不受限。"},{"senses":"S2","en":"THE LAW OF DISTANCE: the inverse square.","cn":"距离的定律：平方反比。"},{"senses":"S3 · S4","en":"LOCAL READINGS: weight at one point, tidal difference across a body.","cn":"局部读数：某一点的重量，横跨物体的潮汐差。"},{"senses":"S6 · S8","en":"BALANCE AND BOOKKEEPING: what holds an orbit, and what relativity renames as geometry.","cn":"平衡与记账：维持轨道的东西，以及相对论改称为几何的东西。"},{"senses":"S7","en":"THE METAPHOR: an invisible pull that acts at a distance.","cn":"比喻：隔空起作用的无形拉力。"}]},"affixes":{"intro":{"en":"The phrase is an English adjective plus a French-borrowed noun, both from Latin roots; the adjective carries the weight family, the noun the strength family.","cn":"这个短语是英语形容词加一个法语借入的名词，两者都源自拉丁词根；形容词带「重」词族，名词带「强」词族。"},"latinIntro":{"en":"Latin gravis gives gravity and gravitation; Latin fortis gives force, fortify and fortress.","cn":"拉丁 gravis 给出 gravity 与 gravitation；拉丁 fortis 给出 force、fortify、fortress。"},"items":[{"word":"gravis","structure":"gravis, gravis, grave (Latin adjective)","meaning":"heavy, weighty","meaningCN":"重的；有分量的","example":"The root supplies the first element of gravitational.","exampleCN":"这个词根提供 gravitational 的第一成分。"},{"word":"gravitas","structure":"gravitas, gravitatis (Latin noun)","meaning":"weight, heaviness","meaningCN":"重量；沉重","example":"Gravitation is built on this stem.","exampleCN":"gravitation 建立在这个词干上。"},{"word":"-ation","structure":"-atio, -ationis (Latin suffix)","meaning":"action or process","meaningCN":"动作或过程","example":"The suffix forms the abstract noun gravitation.","exampleCN":"这个后缀构成抽象名词 gravitation。"},{"word":"-al","structure":"-alis (Latin adjective suffix)","meaning":"of or relating to","meaningCN":"……的","example":"Gravitational means of gravitation.","exampleCN":"gravitational 意为引力的。"},{"word":"force","structure":"fortia (Late Latin) < fortis (strong)","meaning":"strength in action","meaningCN":"力；力量","example":"The noun entered English through Old French.","exampleCN":"这个名词经古法语进入英语。"},{"word":"fortis","structure":"fortis, fortis, forte (Latin adjective)","meaning":"strong, powerful","meaningCN":"强的；有力的","example":"The root also gives fortify.","exampleCN":"这个词根还给出 fortify。"},{"word":"gravitational","structure":"gravitation + -al","meaning":"of gravitational force","meaningCN":"引力的","example":"The adjective is required before force.","exampleCN":"这个形容词在 force 前是必需的。"},{"word":"gravity","structure":"gravis + -ity","meaning":"heaviness; the force","meaningCN":"重力","example":"The shorter noun is the everyday form.","exampleCN":"较短的名词是日常形式。"},{"word":"fortify","structure":"fortis + -fy","meaning":"to make strong","meaningCN":"加固；增强","example":"The same root appears in military vocabulary.","exampleCN":"同一词根也出现在军事词汇中。"}],"latinEntries":[{"word":"gravis","structure":"gravis, gravis, grave (adjective, third declension)","meaning":"heavy, weighty","meaningCN":"重的；有分量的"},{"word":"gravitas","structure":"gravitas, gravitatis (f., third declension)","meaning":"weight, heaviness","meaningCN":"重量；沉重"},{"word":"fortis","structure":"fortis, fortis, forte (adjective, third declension)","meaning":"strong, powerful","meaningCN":"强的；有力的"}]}},{"word":"light-year","ipa_uk":"/ˈlaɪt jɪə/","ipa_us":"/ˈlaɪt jɪr/","definition_zh":"光年；光在一年内走过的距离；比喻极远的距离或巨大的差距","definition_en":"the distance light travels in one year, or a figurative very great distance or gap","core_image":"一束光从一枚星出发，穿过一整年的日历，最后落在另一枚星旁","scene":"形容远处那团云气宽得难以想象，你说 The cloud is nearly a light-year across.","sceneCN":"这里 light-year 指「光在一年内走过的距离」（第 1 个义项：一种长度单位，不是时间）；句意为那团云气宽近一光年。图中可辨识物件：一束光、成叠的日历、两端的天体、标尺。","pos":[{"tag":"n.","zh":"光年（长度单位；复数 light-years；亦作定语）"}],"collocations":[{"phrase":"a few light-years away","zh":"几光年之外"},{"phrase":"ten light-years across","zh":"宽十光年"},{"phrase":"light-years ahead","zh":"领先许多年；领先极远"},{"phrase":"a light-year of distance","zh":"一光年的距离"},{"phrase":"measured in light-years","zh":"以光年计"}],"forms":[{"label":"复数","form":"light-years"},{"label":"相关单位（更小）","form":"light-second（光秒）"},{"label":"相关单位（更小）","form":"light-minute（光分）"},{"label":"相关单位（天文学）","form":"parsec（秒差距）"},{"label":"相关形容词（每年的）","form":"yearly"},{"label":"相关名词（光）","form":"light"}],"derivatives":[{"word":"light","pos":"n./adj.","zh":"light 为英语本族词；本词前半，指光"},{"word":"yearly","pos":"adj./adv.","zh":"year + -ly：每年的；由后半 year 加后缀构成"},{"word":"light-second","pos":"n.","zh":"light + second：光秒；按同一构词法造出的更小单位"},{"word":"light-minute","pos":"n.","zh":"light + minute：光分；同一构词法的平行单位"}],"senses":[{"no":"01","title":"The distance light covers in a year","titleCN":"光在一年内走过的距离","definition":"the distance that light travels in one year, about nine and a half trillion kilometres","definitionCN":"光在一年内走过的距离，约九点五万亿公里","example":"The cloud is nearly a light-year across.","exampleCN":"那团云气宽近一光年。","why":"the name states the definition: light, multiplied by a year of travel, gives a length rather than a duration.","whyCN":"名字即定义：光速乘以一年的行进，得到的是长度而非时长。"},{"no":"02","title":"A unit for star distances","titleCN":"用于恒星距离的长度单位","definition":"a unit used to express distances between stars and other galaxies","definitionCN":"用来表示恒星之间与星系之间距离的单位","example":"The nearest star is a few light-years away.","exampleCN":"最近的恒星在几光年之外。","why":"ordinary units fail at this scale: kilometres become unreadable, so the unit is defined by something that always moves at the same speed.","whyCN":"普通单位在这个尺度上失效：公里数会变得无法阅读，于是用一种速度恒定的东西来定义单位。"},{"no":"03","title":"A measure that looks back in time","titleCN":"因光速有限而看到过去的度量","definition":"a distance that also measures how far back in time the light left its source","definitionCN":"同时也是光离开源头多久以前的度量","example":"A star a hundred light-years away is seen as it was a hundred years ago.","exampleCN":"百光年外的恒星，看到的是它百年前的样子。","why":"because light takes time, distance and delay are the same number, and the unit carries that double meaning.","whyCN":"由于光需要时间，距离与延迟是同一个数，这个单位就带着双重含义。"},{"no":"04","title":"The common mistake that it is time","titleCN":"常见误解：把它当作时间单位","definition":"the widespread misuse of the word as if it named a period of time","definitionCN":"把它误当作表示一段时间的普遍误用","example":"The phrase 'a light-year later' is a misuse of the unit.","exampleCN":"「一光年之后」这种说法是对该单位的误用。","why":"the second half of the word is year, so the error is built into the form; the first half, light, tells you it is a distance.","whyCN":"词的后半是 year，错误就藏在词形里；前半 light 才说明它是距离。"},{"no":"05","title":"Figurative: an enormous gap","titleCN":"比喻义：极大的距离或差距","definition":"a figurative use for a very great distance or difference between things or people","definitionCN":"比喻事物或人之间极大的距离或差异","example":"The two teams are light-years apart in preparation.","exampleCN":"两队在准备程度上相差极远。","why":"the metaphor borrows both features at once: a distance too large to imagine, and a delay that cannot be closed quickly.","whyCN":"这个比喻同时借用两个特征：大到难以想象的距离，以及无法迅速弥补的延迟。"},{"no":"06","title":"How it compares with the parsec","titleCN":"与秒差距等单位的换算关系","definition":"the relation between this unit and the parsec or the astronomical unit","definitionCN":"这个单位与秒差距或天文单位之间的换算关系","example":"One parsec is about three and a quarter light-years.","exampleCN":"一秒差距约为三点二五光年。","why":"astronomers use both units: the light-year explains itself to the public, while the parsec comes straight from measurement geometry.","whyCN":"天文学家两者都用：光年便于向公众解释，秒差距则直接来自测量几何。"},{"no":"07","title":"A scale used in fiction","titleCN":"科幻作品中的行程尺度","definition":"a unit used in science fiction for journeys between star systems","definitionCN":"科幻作品中用于恒星系统之间行程的单位","example":"The story measures its voyages in light-years.","exampleCN":"这个故事用光年来衡量它的航行。","why":"fiction needs a familiar unit for an unfamiliar scale, and the light-year supplies both the number and the sense of vastness.","whyCN":"科幻需要一个熟悉单位来承载陌生尺度，光年同时提供数字与浩瀚感。"},{"no":"08","title":"Figurative: being years ahead","titleCN":"比喻义：领先许多年","definition":"an informal use for being far ahead in progress or understanding","definitionCN":"非正式用法：在进展或理解上领先很多","example":"Her research is light-years ahead of the field.","exampleCN":"她的研究领先该领域许多年。","why":"here the distance becomes time again, but only in the metaphor: to be far ahead is to be many years in front.","whyCN":"此处距离又在比喻中变回时间：领先很远就是领先许多年。"}],"etymology":{"intro":{"en":"Light-year joins native English light and year, both Germanic; the compound was coined in astronomy in the nineteenth century. It contains no Latin root. Dates are approximate.","cn":"light-year 由英语本族的 light 与 year 组合，两者都属日耳曼语；这个复合词在 19 世纪由天文学界造出。其中没有拉丁词根。年代均为约数。"},"items":[{"era":"OLD ENGLISH LEOHT","en":"Light descends from Old English lēoht, native Germanic; Latin lux and Greek leukos are cognates, not sources.","cn":"light 承自古英语 lēoht，属本族日耳曼语；拉丁 lux 与希腊 leukos 是同源词，并非来源。"},{"era":"OLD ENGLISH GEAR","en":"Year descends from Old English gēar, also native Germanic, and has no Latin source.","cn":"year 承自古英语 gēar，同属本族日耳曼语，没有拉丁来源。"},{"era":"THE COINAGE","en":"The unit is generally attributed to Friedrich Bessel, who used it in 1838 after measuring the first stellar parallax.","cn":"这个单位一般归功于弗里德里希·贝塞尔，他在 1838 年测出首个恒星视差后使用了它。"},{"era":"THE APPEAL OF THE UNIT","en":"The light-year spread in popular writing because it states its own definition, unlike the parsec, which requires geometry to explain.","cn":"光年在通俗写作中流行，因为它自带定义，而秒差距需要几何解释。"},{"era":"THE MODERN VALUE","en":"The distance is now fixed from the defined speed of light and the length of the year, so the unit needs no new measurement.","cn":"这个距离现由定义的光速与年长固定，因此单位无需重新测量。"},{"era":"UNCERTAIN DETAILS","en":"Root uncertainty: neither half has a disputed root. First-date uncertainty only: the exact first printed use of light-year is not fully documented, and the 1838 attribution is generally believed rather than proven.","cn":"词根存疑：两半都没有争议性词根，不涉及重构形式。仅首见年代存疑：light-year 最早印刷用例没有完整记录，1838 年之说一般认为成立但未获证明。"}]},"similar":{"note":{"en":"Group one holds distance units and words that look like time; group two holds the near expressions for very great distance.","cn":"第一组是距离单位与看似时间的词；第二组是「极远距离」的近义说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"parsec","ipa":"/ˈpɑːsek/","tag":"another star-distance unit","definition":"About three and a quarter light-years, defined by parallax rather than by travel time; the two units measure the same kind of thing.","definitionCN":"约三点二五光年，由视差而非行进时间定义；两者测的是同一类量。"},{"word":"light-second","ipa":"/ˈlaɪt sekənd/","tag":"a much smaller unit","definition":"The distance light covers in one second; the same construction at a smaller scale.","definitionCN":"光在一秒内走过的距离；同一构词法的更小尺度。"},{"word":"year","ipa":"/jɪə/","tag":"the time unit inside the word","definition":"A period of time, not a distance; it is the second element of light-year and the source of the common confusion.","definitionCN":"一段时间，不是距离；它是 light-year 的第二成分，也是常见混淆的来源。"}]},{"heading":"NEAR MEANING","entries":[{"word":"astronomical unit","ipa":"/ˌæstrəˈnɒmɪkl ˈjuːnɪt/","tag":"a solar-system unit","definition":"The earth-sun distance, used inside a planetary system; the light-year is far larger and used between stars.","definitionCN":"地日距离，用于行星系统内部；光年大得多，用于恒星之间。"},{"word":"distance","ipa":"/ˈdɪstəns/","tag":"the general noun","definition":"The plain word for how far apart things are; light-year is a specific unit of distance.","definitionCN":"指事物相隔多远的普通词；light-year 是具体的距离单位。"},{"word":"gap","ipa":"/ɡæp/","tag":"the figurative noun","definition":"A separation of any kind, often figurative; it is what the metaphorical light-year measures.","definitionCN":"任何形式的间隔，常用于比喻；正是比喻中的光年所测量的东西。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"light + year: how far light gets in a year.","cn":"light + year：光一年能走多远。"},{"en":"It is a distance, not a time.","cn":"它是距离，不是时间。"},{"en":"Smaller siblings: light-second, light-minute.","cn":"更小的同族单位：光秒、光分。"},{"en":"One parsec is about three and a quarter light-years.","cn":"一秒差距约三点二五光年。"},{"en":"Popular phrases: light-years ahead, light-years apart.","cn":"常见短语：领先许多年、相差极远。"}],"abstract":[{"en":"Picture a beam of light walking past a whole year of calendar pages.","cn":"想象一束光走过整年的日历页。"},{"en":"Picture two towns so far apart that a letter takes a lifetime.","cn":"想象两座城镇远到一封信要走一辈子。"},{"en":"Picture a runner so far ahead that the others seem to be standing still.","cn":"想象一名跑者领先太远，其他人像站着不动。"}]},"examples":[{"en":"The nearest star system is about four light-years away.","cn":"最近的恒星系统约在四光年之外。"},{"en":"The galaxy is a hundred thousand light-years across.","cn":"这个星系宽约十万光年。"},{"en":"Their level of preparation is light-years beyond the competition.","cn":"他们的准备程度远超竞争对手。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「light（光）+ year（年）」——光跑一年那么远 → 光年（长度单位）","word":"light-year"},"root":"古英语 lēoht「光」+ 古英语 gēar「年」，均为本族日耳曼词；复合单位一般认为由贝塞尔于 1838 年使用。","sensesIntro":{"en":"Eight senses follow one beam: light travelling for a year gives a distance, that distance becomes a unit for stars, a look back in time, a unit people mistake for time, a metaphor for any vast gap, a comparison with the parsec, a scale for fiction and a way to say 'far ahead'.","cn":"八个义项沿同一束光展开：光走一年给出一个距离；这个距离成为恒星间的单位、回望过去的方式、被人误当时间的单位、任何巨大差距的比喻、与秒差距的比较、科幻的尺度，以及「领先很远」的说法。"},"semanticMap":{"core":{"en":"CORE IMAGE: a beam crossing a whole year of calendar pages and landing beside another star.","cn":"核心意象：一束光穿过整年的日历页，落在另一颗星旁。"},"chain":["LIGHT TRAVELS","ONE YEAR","STAR DISTANCE","LOOKBACK TIME","MISTAKEN FOR TIME","VAST GAP"],"branches":[{"senses":"S1 · S2","en":"DEFINITION AND USE: a length defined by travel, then used between stars.","cn":"定义与用途：由行进定义的长度，再用于恒星之间。"},{"senses":"S3","en":"LOOKING BACK: the same number is a delay as well as a distance.","cn":"回望：同一个数既是距离也是延迟。"},{"senses":"S4","en":"THE BUILT-IN TRAP: the word says year, so people hear time.","cn":"内置的陷阱：词里有 year，人们就听成时间。"},{"senses":"S5 · S8","en":"THE METAPHOR: enormous separation, and being far ahead.","cn":"比喻：极大的间隔，以及遥遥领先。"},{"senses":"S6 · S7","en":"COMPARISON AND FICTION: parsecs for measurement, light-years for the story.","cn":"比较与虚构：测量用秒差距，讲故事用光年。"}]},"affixes":{"intro":{"en":"The compound is built from two native English nouns; there is no Latin suffix and no Latin root inside it.","cn":"这个复合词由两个英语本族名词构成；内部没有拉丁后缀，也没有拉丁词根。"},"latinIntro":{"en":"Latin lux 'light' is a cognate of light, not its source, and no Latin element enters the compound; the unit's Latin neighbours appear only in borrowed technical terms.","cn":"拉丁 lux「光」是 light 的同源词而非来源，复合词中不含拉丁成分；其拉丁近亲只出现在借入的技术术语中。"},"items":[{"word":"light","structure":"Old English lēoht (native noun)","meaning":"light","meaningCN":"光","example":"The first half is a free native noun.","exampleCN":"前半是自由的本族名词。"},{"word":"year","structure":"Old English gēar (native noun)","meaning":"a year","meaningCN":"年","example":"The second half is a free native noun.","exampleCN":"后半是自由的本族名词。"},{"word":"light-year","structure":"light + year","meaning":"distance travelled in a year","meaningCN":"光年","example":"The compound is fixed as a unit name.","exampleCN":"这个复合词固定为单位名。"},{"word":"light-second","structure":"light + second","meaning":"distance travelled in a second","meaningCN":"光秒","example":"The same pattern at a smaller scale.","exampleCN":"同一构词法的更小尺度。"},{"word":"light-minute","structure":"light + minute","meaning":"distance travelled in a minute","meaningCN":"光分","example":"Another parallel unit.","exampleCN":"另一个平行单位。"},{"word":"-ly","structure":"-ly (English suffix)","meaning":"having the quality of","meaningCN":"具有……性质的","example":"Yearly means each year.","exampleCN":"yearly 意为每年的。"},{"word":"parsec","structure":"parallax + second","meaning":"a parallax-based unit","meaningCN":"秒差距","example":"A unit built from measurement words instead.","exampleCN":"一个改用测量词构成的单位。"},{"word":"astronomical unit","structure":"astronomical + unit","meaning":"the earth-sun distance","meaningCN":"天文单位","example":"A smaller unit used inside the solar system.","exampleCN":"用于太阳系内部的较小单位。"},{"word":"lux","structure":"lux, lucis (Latin noun)","meaning":"light","meaningCN":"光","example":"A Latin cognate of light, not its source.","exampleCN":"light 的拉丁同源词，不是来源。"}],"latinEntries":[{"word":"lux","structure":"lux, lucis (f., third declension)","meaning":"light","meaningCN":"光"}]}},{"word":"astronomical unit","ipa_uk":"/ˌæstrəˈnɒmɪkl ˈjuːnɪt/","ipa_us":"/ˌæstrəˈnɑːmɪkl ˈjuːnɪt/","definition_zh":"天文单位；地球与太阳的平均距离（约一亿五千万公里）；太阳系距离的常用尺度","definition_en":"a unit of length equal to the mean distance between the earth and the sun","core_image":"从太阳到地球拉出一条直尺，尺上只刻一个刻度，却正好量出整个太阳系的间距","scene":"讲解太阳系内的距离单位，你说 One astronomical unit is the span from the earth to the sun.","sceneCN":"这里 astronomical unit 指「地球与太阳的平均距离这一长度单位」（第 1 个义项：太阳系距离的基本尺度）；句意为一个天文单位就是从地球到太阳的跨度。图中可辨识物件：太阳、地球、拉出的直尺、轨道弧线。","pos":[{"tag":"n.","zh":"天文单位（长度单位；缩写 AU；复数 astronomical units）"}],"collocations":[{"phrase":"one astronomical unit","zh":"一个天文单位"},{"phrase":"measured in astronomical units","zh":"以天文单位计"},{"phrase":"about one astronomical unit from the sun","zh":"距太阳约一个天文单位"},{"phrase":"the astronomical unit of distance","zh":"距离的天文单位"},{"phrase":"convert to astronomical units","zh":"换算成天文单位"}],"forms":[{"label":"复数","form":"astronomical units"},{"label":"缩写","form":"AU"},{"label":"相关形容词","form":"astronomical"},{"label":"相关名词（天文学）","form":"astronomy"},{"label":"相关名词（天文学家）","form":"astronomer"},{"label":"相关单位（光年）","form":"light-year"}],"derivatives":[{"word":"astronomical","pos":"adj.","zh":"astronomy + -ical：天文的；巨大的（口语）"},{"word":"astronomy","pos":"n.","zh":"希腊 astron + nomos：天文学"},{"word":"astronomer","pos":"n.","zh":"astronomy + -er：天文学家"},{"word":"unit","pos":"n.","zh":"拉丁 unus「一」经法语进入英语：单位；本词后半"}],"senses":[{"no":"01","title":"The earth-sun mean distance","titleCN":"地球与太阳的平均距离","definition":"the mean distance from the earth to the sun, used as a base unit of length","definitionCN":"地球到太阳的平均距离，用作长度的基本单位","example":"One astronomical unit is the span from the earth to the sun.","exampleCN":"一个天文单位就是从地球到太阳的跨度。","why":"the phrase defines a unit by a natural span: instead of a metal bar, the yardstick is the orbit itself.","whyCN":"这个短语用自然跨度定义单位：尺子不是金属杆，而是轨道本身。"},{"no":"02","title":"A ruler for the solar system","titleCN":"量度太阳系距离的常用尺度","definition":"the standard unit for expressing distances within a planetary system","definitionCN":"表示行星系统内部距离的标准单位","example":"The orbit of Neptune is about thirty astronomical units from the sun.","exampleCN":"海王星轨道距太阳约三十个天文单位。","why":"inside one system the numbers stay small in this unit, which is exactly why it was chosen.","whyCN":"在同一个系统内，用这个单位时数字不会过大，这正是它被选中的原因。"},{"no":"03","title":"The exact modern definition","titleCN":"现代的精确定义","definition":"the exact length fixed by international agreement, stated in metres","definitionCN":"由国际协议固定、以米表述的确切长度","example":"Since 2012 the astronomical unit has been defined as a fixed number of metres.","exampleCN":"自 2012 年起，天文单位被定义为一个固定的米数。","why":"a unit that once depended on measurement now depends on definition, so it no longer changes when new data arrive.","whyCN":"曾经依赖测量的单位如今依赖定义，因此新数据到来时它不再变动。"},{"no":"04","title":"The parallax baseline","titleCN":"视差测量的基线","definition":"the baseline used in triangulating the distance to nearby stars","definitionCN":"用于三角测量邻近恒星距离的基线","example":"The astronomical unit is the base line of every stellar parallax.","exampleCN":"天文单位是每一个恒星视差的基线。","why":"parallax works by viewing from two ends of a base line, and the earth's orbit supplies the longest one available to us.","whyCN":"视差靠从基线两端观测，而地球轨道提供了我们能得到的最长基线。"},{"no":"05","title":"A scale in catalogues","titleCN":"星表与系外行星目录中的尺度","definition":"the unit in which orbits and exoplanet separations are listed","definitionCN":"列出行星轨道与系外行星间距时使用的单位","example":"The catalogue lists the planet at two astronomical units from its star.","exampleCN":"目录把这颗行星列在距其恒星两个天文单位处。","why":"catalogues need one unit for every system, and the earth-sun span is the only natural ruler that every observer already knows.","whyCN":"星表需要为每个系统提供同一个单位，而地日跨度是每位观测者都已知道的唯一自然尺。"},{"no":"06","title":"A bridge to other units","titleCN":"与其他单位的换算桥梁","definition":"the conversion factor linking this unit to the light-year and the parsec","definitionCN":"把该单位与光年、秒差距联系起来的换算因子","example":"One astronomical unit is about eight light-minutes.","exampleCN":"一个天文单位约为八光分。","why":"the smaller unit is the bridge: from it, both light-based and parallax-based units can be reached.","whyCN":"较小单位充当桥：由它可以通向以光速计的与以视差计的单位。"},{"no":"07","title":"The older definition by orbit","titleCN":"历史上以轨道长半轴为定义","definition":"the historical definition as the semi-major axis of the earth's orbit","definitionCN":"历史上以地球轨道的长半轴作为定义","example":"Older tables treated the astronomical unit as the earth's semi-major axis.","exampleCN":"旧表把天文单位当作地球轨道的长半轴。","why":"the old definition was geometrical and slightly variable; the modern one replaced it with a fixed number.","whyCN":"旧定义是几何的，且略有变动；现代定义用一个固定数取代了它。"},{"no":"08","title":"Figurative: an unimaginably large measure","titleCN":"比喻义：大得难以想象的计量","definition":"an informal figurative use for a huge measure of anything, not only distance","definitionCN":"非正式比喻：不仅指距离，也指任何大得难以想象的量","example":"The report demanded an astronomical unit of patience.","exampleCN":"这份报告需要一份天文单位级别的耐心。","why":"the figurative use leans on astronomical itself, whose everyday sense is simply 'enormous'.","whyCN":"这个比喻依托的是 astronomical 一词，其日常义就是「极大」。"}],"etymology":{"intro":{"en":"Astronomical unit joins astronomical, from Greek astron 'star' plus nomos 'law', to unit, from Latin unus 'one'. The term is a modern measurement label. Dates are approximate.","cn":"astronomical unit 把出自希腊 astron「星」加 nomos「法则」的 astronomical，与出自拉丁 unus「一」的 unit 并置。这个术语是近代测量标签。年代均为约数。"},"items":[{"era":"GREEK ASTRON","en":"Greek astron 'star' is the first element of astronomy, and its deeper origin is a reconstruction rather than an attested form.","cn":"希腊 astron「星」是 astronomy 的第一成分，其更深来源属重构而非有书证的形式。"},{"era":"GREEK NOMOS","en":"Nomos meant 'law, custom, arrangement'; astron plus nomos gave astronomia, the ordering of the stars.","cn":"nomos 意为「法则、习俗、安排」；astron 加 nomos 构成 astronomia，即对星辰的编排。"},{"era":"LATIN UNUS","en":"Unus 'one' gave Latin unitas and, through French, English unit; the unit is literally a single measure.","cn":"unus「一」给出拉丁 unitas，并经法语给出英语 unit；单位字面上就是「一个」度量。"},{"era":"THE MEASUREMENT","en":"The earth-sun distance was first estimated in the seventeenth century and refined by transits of Venus in the eighteenth and nineteenth; the unit grew out of that work.","cn":"地日距离在 17 世纪首次被估算，又经 18、19 世纪的金星凌日得到改进；这个单位正是从这项工作中生长出来的。"},{"era":"THE FIXED DEFINITION","en":"In 2012 the International Astronomical Union redefined the unit as an exact number of metres, ending its dependence on a measured orbit.","cn":"2012 年国际天文联合会把这个单位重新定义为一个确切的米数，结束了它对实测轨道的依赖。"},{"era":"UNCERTAIN DETAILS","en":"Root uncertainty: the Indo-European shape behind astron is a reconstruction. First-date uncertainty only: the earliest printed use of the exact phrase astronomical unit is not precisely recorded and is placed in the nineteenth century.","cn":"词根存疑：astron 背后的印欧形态属重构。仅首见年代存疑：astronomical unit 这一确切短语的最早印刷用例没有确切记录，通常定在 19 世纪。"}]},"similar":{"note":{"en":"Group one holds the distance units and the words that resemble the phrase; group two holds the everyday expressions for huge size.","cn":"第一组是距离单位与形似该短语的词；第二组是表示「极大」的日常说法。"},"groups":[{"heading":"LOOK-ALIKE","entries":[{"word":"light-year","ipa":"/ˈlaɪt jɪə/","tag":"a far larger unit","definition":"About sixty-three thousand astronomical units; the light-year is used between stars, the astronomical unit inside a solar system.","definitionCN":"约合六万三千个天文单位；光年用于恒星之间，天文单位用于太阳系内部。"},{"word":"parsec","ipa":"/ˈpɑːsek/","tag":"a parallax unit","definition":"Built from parallax and second, about two hundred thousand astronomical units; a different construction for the same kind of quantity.","definitionCN":"由视差与角秒构成，约合二十万个天文单位；同一类量的另一种构词。"},{"word":"astronomical","ipa":"/ˌæstrəˈnɒmɪkl/","tag":"the adjective, also 'enormous'","definition":"The adjective alone means 'of astronomy' and, informally, 'extremely large'; it does not name the unit by itself.","definitionCN":"这个形容词单独表示「天文的」，口语中也指「极大的」；它本身不指这个单位。"}]},{"heading":"NEAR MEANING","entries":[{"word":"solar distance","ipa":"/ˈsəʊlə ˈdɪstəns/","tag":"a descriptive phrase","definition":"A general description of the earth-sun span; the astronomical unit is the standardized unit built on it.","definitionCN":"对地日跨度的泛称；天文单位是在此基础上标准化的单位。"},{"word":"AU","ipa":"/ˌeɪ ˈjuː/","tag":"the abbreviation","definition":"The written symbol for the unit, used in tables and diagrams rather than in running prose.","definitionCN":"该单位的书写符号，多用于表格与图示而非行文。"},{"word":"huge","ipa":"/hjuːdʒ/","tag":"the everyday adjective","definition":"The plain word for very large size, which the figurative astronomical unit leans on.","definitionCN":"表示极大的普通形容词，天文单位的比喻义正依托于它。"}]}]},"mnemonics":{"normalIntro":{"en":"Normal associations: real morphemes, real collocations and real relatives, not invented rhymes.","cn":"正常联想：真实的构词成分、真实搭配与真实同族词，而非编造的顺口溜。"},"normal":[{"en":"Greek astron 'star' + nomos 'law' + Latin unus 'one'.","cn":"希腊 astron「星」+ nomos「法则」+ 拉丁 unus「一」。"},{"en":"The unit is the earth-sun span.","cn":"这个单位就是地日跨度。"},{"en":"Inside the solar system the numbers stay small.","cn":"在太阳系内，数字不会大到难读。"},{"en":"The abbreviation is AU.","cn":"缩写是 AU。"},{"en":"Since 2012 it is a fixed number of metres.","cn":"自 2012 年起它是一个固定的米数。"}],"abstract":[{"en":"Picture a ruler laid from the sun to the earth with one mark on it.","cn":"想象一把从太阳拉到地球的尺，上面只刻一个刻度。"},{"en":"Picture a map of a city measured in blocks, then a map of a country measured the same way.","cn":"想象先用街区量城市，再用同一办法量整个国家。"},{"en":"Picture a request for patience measured in lifetimes.","cn":"想象一份以一辈子为计量单位的耐心要求。"}]},"examples":[{"en":"Mars orbits the sun at about one and a half astronomical units.","cn":"火星以约一点五个天文单位绕太阳运行。"},{"en":"The astronomical unit is the baseline for stellar parallax.","cn":"天文单位是恒星视差的基线。"},{"en":"Pluto lies roughly forty astronomical units from the sun.","cn":"冥王星距太阳约四十个天文单位。"}],"dict_mnemonic":{"note":"谐音记忆 · 非词源","text":"「astronomical（天文的）+ unit（单位）」——量太阳系用的那一把尺 → 天文单位","word":"astronomical unit"},"root":"希腊 astron「星」+ nomos「法则」→ astronomia；拉丁 unus「一」→ unit；长度取地球与太阳的平均距离，2012 年起由国际协议固定为确切米数。","sensesIntro":{"en":"Eight senses follow one ruler: a natural span becomes a unit, that unit measures a whole planetary system, is fixed by definition, serves as a parallax baseline, fills catalogues, bridges other units, recalls its older orbital definition, and finally stands for any enormous measure.","cn":"八个义项沿同一把尺展开：一个自然跨度成为单位；这个单位量度整个行星系统、被定义固定、充当视差基线、填入星表、连接其他单位、追忆旧的轨道定义，最后代表任何极大的计量。"},"semanticMap":{"core":{"en":"CORE IMAGE: a ruler stretched from the sun to the earth, carrying a single mark.","cn":"核心意象：一把从太阳拉到地球的尺，上面只有一个刻度。"},"chain":["EARTH-SUN SPAN","BASE UNIT","SOLAR RULER","FIXED DEFINITION","PARALLAX BASE","SCALE MARKER"],"branches":[{"senses":"S1 · S3","en":"THE SPAN AND ITS DEFINITION: a natural distance turned into exact metres.","cn":"跨度与定义：一个自然距离被固定为确切的米数。"},{"senses":"S2 · S5","en":"THE RULER IN USE: planetary orbits and catalogue entries.","cn":"使用中的尺：行星轨道与星表条目。"},{"senses":"S4 · S7","en":"THE OLD GEOMETRY: the baseline of parallax, and the semi-major axis it once was.","cn":"旧日几何：视差基线，以及它曾经是的长半轴。"},{"senses":"S6","en":"THE BRIDGE: a small unit that converts into light-years and parsecs.","cn":"桥：一个可换算为光年与秒差距的小单位。"},{"senses":"S8","en":"THE METAPHOR: any measure that feels astronomical.","cn":"比喻：任何大得像天文数字的计量。"}]},"affixes":{"intro":{"en":"The phrase joins a Greek-derived adjective to a Latin-derived noun; the two halves come from different languages, which is typical of scientific English.","cn":"这个短语把希腊来源的形容词接到拉丁来源的名词上；两半来自不同语言，这是科学英语的典型状况。"},"latinIntro":{"en":"Greek astron and nomos give astronomy, astronomical and astronomer; Latin unus gives unit, unite and unity.","cn":"希腊 astron 与 nomos 给出 astronomy、astronomical、astronomer；拉丁 unus 给出 unit、unite、unity。"},"items":[{"word":"astron","structure":"astron (Greek noun)","meaning":"star","meaningCN":"星","example":"The Greek noun begins the astronomy family.","exampleCN":"这个希腊名词开启 astronomy 词族。"},{"word":"nomos","structure":"nomos (Greek noun)","meaning":"law, custom","meaningCN":"法则；习俗","example":"Astronomy is the law or arrangement of the stars.","exampleCN":"astronomy 即星辰的法则或编排。"},{"word":"-ia","structure":"-ia (Greek noun suffix)","meaning":"activity or field","meaningCN":"活动；领域","example":"Astronomia names the field of study.","exampleCN":"astronomia 指这门研究领域。"},{"word":"-ical","structure":"-ical (adjective suffix)","meaning":"relating to","meaningCN":"与……有关的","example":"Astronomical means relating to astronomy.","exampleCN":"astronomical 意为与天文学有关的。"},{"word":"-er","structure":"-er (English agent suffix)","meaning":"a person who","meaningCN":"从事……的人","example":"Astronomer names the practitioner.","exampleCN":"astronomer 指从业者。"},{"word":"unus","structure":"unus, una, unum (Latin numeral)","meaning":"one","meaningCN":"一","example":"The numeral is the base of unit.","exampleCN":"这个数词是 unit 的基础。"},{"word":"unit","structure":"unus + -ite (through French)","meaning":"a single measure","meaningCN":"单位","example":"A unit is literally a one.","exampleCN":"单位字面上就是「一个」。"},{"word":"astronomical unit","structure":"astronomical + unit","meaning":"the earth-sun distance","meaningCN":"天文单位","example":"The phrase is a modern scientific label.","exampleCN":"这个短语是近代科学标签。"},{"word":"unity","structure":"unus + -ity","meaning":"oneness","meaningCN":"统一；一体","example":"The same numeral noun family.","exampleCN":"同一数词名词族。"}],"latinEntries":[{"word":"unus","structure":"unus, una, unum (numeral and adjective)","meaning":"one","meaningCN":"一"},{"word":"unitas","structure":"unitas, unitatis (f., third declension)","meaning":"oneness, unity","meaningCN":"单一；统一"}]}}]);
